(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.2"]={"from":48,"a":[["ומקשים: \u0003מידי כוליה קאמרינן\u0004 \u0005[וכי כל\u0006 הנזק \u0005אומרים אנו],\u0006 רוצים אנו לומר שישלם, מלימוד הקל וחומר? \u0003פלגא קאמרינן\u0004 \u0005[חצי\u0006 הנזק \u0005אומרים אנו]\u0006 והכוונה שיהא דין שן ורגל ברשות הרבים כדין קרן שם, וישלם חצי נזק!","ודוחים: אף דבר זה לא ניתן להיאמר, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי תשלום חצי נזק: \u0003\"וחצו את כספו\"\u0004 (שמות כא, לה) והביטוי \"כספו\" (ולא \"וחצו את הכסף\") בא לשם הדגשה מיוחדת, לומר: דווקא \u0003כספו של זה\u0004 של שור המזיק בנגיחה בקרן חוצים, כלומר, שמשלם חצי נזק, \u0003ולא כספו של אחר,\u0004 בסוגים אחרים של נזק שגורם השור.","ושואלים באופן אחר: \u0003ולא תהא שן ורגל חייבת\u0004 אף שהזיקה \u0003ברשות הניזק אלא חצי נזק,\u0004 ונלמד הדבר \u0003מקל וחומר מקרן.\u0004 וכך נאמר: \u0003ומה קרן\u0004 החמור \u0003ש\u0004כן אפילו \u0003ברשות הרבים חייבת,\u0004 מכל מקום \u0003ברשות הניזק\u0004 — \u0003אינה משלמת אלא חצי נזק, שן ורגל\u0004 הקל \u0003ש\u0004כן \u0003ברשות הרבים פטורה\u0004 — \u0003אינו דין שברשות הניזק משלם\u0004 רק \u0003חצי נזק?\u0004","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בנזקי שן ורגל: \u0003\"\u0004מיטב שדהו ומיטב כרמו \u0003ישלם\"\u0004 (שמות כב, ד), והכוונה: \u0003תשלומין מעליא\u0004 \u0005[מעולים,\u0006 שלמים\u0005].\u0006","ושואלים עוד ובאופן אחר: \u0003ולא תהא קרן ברשות הרבים חייב\u0004 כלל, ונלמד הדבר \u0003מקל וחומר,\u0004 ונאמר כך: \u0003ומה שן ורגל שברשות הניזק\u0004 משלם \u0003נזק שלם\u0004 — \u0003ברשות הרבים פטורה\u0004 לגמרי, \u0003קרן\u0004 הקלה יותר \u0003ש\u0004כן \u0003ברשות הניזק\u0004 משלם \u0003חצי נזק\u0004 — \u0003אינו דין שברשות הרבים פטורה?\u0004","\u0003אמר ר' יוחנן: אמר קרא\u0004 \u0005[הכתוב]\u0006 בשור תם: \u0003\"\u0004וגם את המת \u0003יחצון\"\u0004 (שמות כא, לה), ללמד כי \u0003אין חצי נזק חלוק, לא ברשות הרבים ולא ברשות היחיד\u0004 ומשלם אותו בעל השור התם בכל מקרה.","ועוד שואלים: \u0003ויהא אדם\u0004 שהרג את חבירו בשוגג \u0003חייב ב\u0004תשלום \u0003כופר\u0004 ונלמד הדבר \u0003מקל וחומר,\u0004 ונאמר כך: \u0003ומה שור ש\u0004הזיק אדם \u0003אינו חייב בארבעה דברים\u0004 (שבת, ריפוי, בושת וצער) — \u0003חייב\u0004 בעליו \u0003בכופר\u0004 אם הרג השור אדם, \u0003אדם שחייב בארבעה דברים\u0004 אם הזיק לחבירו — \u0003אינו דין שיהא חייב בכופר\u0004 אם הרגו?","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשור שהרג אדם: \u0003\"\u0004אם כופר יושת עליו ונתן פדיון נפשו \u0003ככל אשר יושת עליו\"\u0004 (שמות פסוק ל), ויש כאן הדגשה \u0003\"עליו\" ולא על אדם\u0004 שהרג אדם.","ומקשים מן הצד השני: \u0003ויהא שור\u0004 שהזיק אדם \u0003חייב בארבעה דברים מקל וחומר: ומה אדם שאינו חייב בכופר\u0004 אם הרג אדם — \u0003חייב בארבעה דברים\u0004 אם הזיקו, \u0003שור שחייב בכופר\u0004 — \u0003אינו דין שיהא חייב בארבעה דברים?\u0004","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \"ואיש כי יתן מום בעמיתו\" (ויקרא כד, יט), הרי זו הדגשה הבאה למעט: \u0003איש בעמיתו\u0004 \u0003ולא שור בעמיתו.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003רגל\u0004 של בהמה \u0003שדרסה על גבי תינוק בחצר הניזק\u0004 והמיתה אותו, \u0003מהו שתשלם,\u0004 שישלם בעליו, \u0003כופר?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מידי דהוה אקרן\u0004 \u0005[כשם שהוא בקרן],\u0006 \u0003קרן כיון דעבד תרי ותלתא זמני אורחיה\u0004 \u0005[שעשה שתים ושלש פעמים דרכו]\u0006 \u0003הוא\u0004 ונעשה מועד \u0003ומשלם\u0004 בעליו \u0003כופר, הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 ולפי שהרגל מועדת לדרוס מתחילתה — משלם כופר.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 אפשר לומר מצד אחר כך: \u0003קרן\u0004 חמורה שכן \u0003כוונתו להזיק,\u0004 ולכן משלם בעליו כופר כשהמית, \u0003האי\u0004 \u0005[זו]\u0006 רגל הרומסת \u0003אין כוונתו להזיק\u0004 ולכן יהא פטור מכופר?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו בברייתא זו: \u0003הכניס שורו לחצר בעל הבית שלא ברשות, ונגחו\u0004 השור \u0003לבעל הבית ומת\u0004 — \u0003השור בסקילה, ובעליו\u0004 של השור \u0003בין\u0004 שהיה השור \u0003תם בין מועד\u0004 — \u0003משלם כופר שלם,\u0004 אלו \u0003דברי ר' טרפון.\u0004","ונברר: \u0003כופר שלם בתם לר' טרפון מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דסבר ליה\u0004 \u0005[שסבור הוא]\u0006 \u0003כר' יוסי הגלילי,\u0004 ש\u0003אמר:\u0004 שור \u0003תם\u0004 שהמית אדם — \u0003משלם חצי כופר ברשות הרבים, ומייתי לה\u0004 \u0005[ומביא,\u0006 לומד \u0005אותה]\u0006 \u0003מקל וחומר מרגל\u0004 ובאופן זה: ומה רגל שפטורה לגמרי ברשות הרבים — מכל מקום חייבת כופר שלם ברשות הניזק, קרן שחייבת חצי כופר ברשות הרבים — כל שכן שתהא חייבת ברשות הניזק כופר שלם? \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003איכא\u0004 \u0005[\u0006ש\u0005יש]\u0006 \u0003כופר ברגל.\u0004","\u0003אמר רב שימי מנהרדעא:\u0004 אפשר לדחות ולומר כי ה\u0003תנא\u0004 \u0003מניזקין\u0004 של \u0003רגל מייתי לה\u0004 \u0005[מביא,\u0006 לומד \u0005אותה]\u0006 מקל וחומר: ומה רגל שפטורה אם הזיקה ברשות הרבים — משלמת נזק שלם ברשות הניזק, קרן שחייבת חצי כופר ברשות הרבים — כל שכן שתהא חייבת כופר שלם ברשות הניזק?","ומקשים: אם בדרך זו הוא לומד \u0003ולפרוך\u0004 \u0005[ושיקשה]:\u0006 \u0003מה לניזקין\u0004 של \u0003רגל שכן ישנן באש,\u0004 שכשם שמשלם על נזקי רגל כך משלם על נזקי האש, ומכל מקום כופר אינו משלם בנזקי אש, אם נהרג על ידה אדם (לעיל בבא קמא י,א). והרי זו ראיה שאין ללמוד דין כופר מדין אבות נזיקין אחרים! ואומרים: למדים זאת \u0003מטמון\u0004 (דבר שהיה חבוי ולא גלוי) שפטור בנזקי אש וחייב ברגל, ונאמר כי אם חייב כופר על נזקי טמון ברגל ברשות הניזק, כל שכן שיהא חייב כופר על קרן ברשות הניזק.","ומקשים גם על כך: \u0003מה לטמון\u0004 — \u0003שכן ישנו בבור,\u0004 ובבור פטור מכופר! אלא יש לומר כי למדים זאת \u0003מכלים\u0004 שחייב בהם בנזקי רגל ברשות הניזק אף שפטור בהם בבור, ומכאן נלמד לענין כופר בקרן ברשות הניזק.","ודוחים: \u0003מה לכלים ש\u0004כן \u0003ישנן באש,\u0004 ובאש פטור מכופר! ומשיבים: אם כן נלמד \u0003מכלים טמונים\u0004 שאין חייבים עליהם באש, וחייב עליהם בנזקי הרגל. ודוחים: \u0003מה לכלים טמונים\u0004 — \u0003שישנן באדם,\u0004 שהרי אדם שמזיקם חייב, ואינו חייב בכופר אם הרג אדם!","\u0003אלא\u0004 הואיל ולא ניתן ללמוד דין כופר ברשות הניזק מנזקי רגל \u0003לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003מכופר\u0004 של \u0003רגל מייתי לה\u0004 \u0005[מביא\u0006 מוכיח \u0005אותה],\u0006 \u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003איכא\u0004 \u0005[\u0006ש\u0005יש]\u0006 \u0003כופר ברגל.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006 שכן הוא\u0005],\u0006 והרי זה פתרון לבעיה שדנו בה ברגל שדרסה על תינוק בחצר הניזק והמיתה אותו, שדינה שחייב בכופר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כופר ברגל, דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003כופר ברגל, ו\u0004ה\u0003תנא מניזקין\u0004 של \u0003רגל מייתי לה\u0004 \u0005[מביא,\u0006 לומד \u0005אותה],\u0006 אם כן \u0003לפרוך\u0004 \u0005[שיקשה\u0006 כך\u0005]:\u0006 \u0003מה לניזקין\u0004 של \u0003רגל\u0004 — \u0003שכן ישנן ברגל,\u0004 תאמר בכופר שאינו ברגל!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003מכופר\u0004 של \u0003רגל מייתי לה\u0004 \u0005[\u0006הוא \u0005מביא,\u0006 לומד \u0005אותה],\u0006 \u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 \u0003כופר ברגל,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006 שכן הוא\u0005].\u0006","\u0003אדם\u0004 שהזיק בגופו נחשב \u0003מועד לעולם\u0004 (תמיד), לפיכך \u0003בין\u0004 שהיה \u0003שוגג\u0004 בשעה שהזיק \u0003בין\u0004 שהיה \u0003מזיד, בין\u0004 שהיה \u0003ער בין\u0004 שהיה \u0003ישן,\u0004 אם \u0003סימא את עין חבירו ו\u0004כן אם \u0003שיבר את הכלים\u0004 — \u0003משלם נזק שלם.\u0004","מלשון המשנה מדייקים: \u0003קתני\u0004 \u0005[שנה]\u0006 במשנה דוגמא לחיובו כמועד \u0003\"סימא את עין חבירו\" דומיא\u0004 \u0005[בדומה]\u0006 לדוגמא נוספת של \u0003\"שיבר את הכלים\",\u0004 ללמדנו שדומים הם חיובי הנזקים הללו: \u0003מה התם\u0004 \u0005[שם]\u0006 בשבירת הכלים \u0003נזק\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלם, ואולם \u0003ארבעה דברים\u0004 נוספים שמשלמים בנזקי אדם באדם: ריפוי, שבת, צער, ובושת — \u0003לא\u0004 משלם, אם כן \u0003אף סימא את עין חבירו, נזק\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלם, ואולם \u0003ארבעה דברים\u0004 — \u0003לא\u0004 משלם, שכיון שעשה זאת תוך שינה או בשוגג אינו חייב."],["ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שהמזיק משלם את הנזק אפילו כשלא התכוון להזיק? מה מקור הדין בתורה? \u0003אמר חזקיה, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 ברייתא זו: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"פצע תחת פצע\"\u0004 (שמות כא, כה), ולשון יתירה זו באה \u0003לחייבו\u0004 בתשלומי נזק \u0003על השוגג כמזיד ועל האונס כרצון.\u0004","ומקשים: \u0003האי מבעי ליה\u0004 \u0005[\u0006הרי פסוק \u0005זה נצרך לו]\u0006 כדי \u0003ליתן צער במקום נזק,\u0004 שאף שמשלם את מלוא תשלום הנזק שנגרם על ידי מכתו בכל זאת צריך לשלם גם על הצער (הכאב) שהצטער הנפגע! ומשיבים: \u0003אם כן\u0004 שרק לכך בא ייתור לשון זה \u0003לכתוב קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"פצע בפצע\",\u0004 כלומר, הפצע שבתוך הפצע, דהיינו צער, \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 ההדגשה היתירה \u0003\"\u0004פצע \u0003תחת פצע\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים]\u0006 הן לענין שוגג כמזיד, והן לענין צער במקום נזק.","\u0003אמר רבה: היתה אבן מונחת לו\u0004 לאדם \u0003בחיקו\u0004 כשהיה יושב, \u0003ולא הכיר בה,\u0004 שלא ידע כלל שיש שם אבן, \u0003ועמד, ונפלה\u0004 אבן זו והזיקה. \u0003לענין נזקין\u0004 — \u0003חייב\u0004 לשלם כל מה שהזיקה האבן, \u0003לענין ארבעה דברים\u0004 הנוספים לתשלום הנזק עצמו (צער וריפוי וכו') שחייב אדם לשלם על מה שהזיק אדם אחר — \u0003פטור. לענין שבת\u0004 אם על ידי כך נעשתה מלאכה האסורה בשבת, כגון שיצאה האבן מרשות היחיד לרשות הרבים — הרי \u0003מלאכת מחשבת אסרה תורה\u0004 בשבת, שחושב לעשותה, וכאן אין זו מלאכת מחשבת, שהרי לא חשב ולא התכוון למלאכה, ופטור. \u0003לענין גלות,\u0004 שחייב ההורג אדם בשגגה, אם המית אדם בהפלת האבן — הרי זה \u0003פטור,\u0004 שאין אנו רואים אותו כשוגג שחייב גלות, אלא כאנוס.","ו\u0003לענין עבד,\u0004 כלומר, אם על ידי כך גרם להוציא שינו או עינו של עבדו, האם יוצא בכך העבד לחופשי (ראה שמות כא, כו –כז), הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה רבו\u0004 (אדוניו) של העבד \u0003רופא, ואמר לו\u0004 העבד: \u0003כחול עיני\u0004 כדי לרפא אותה, \u0003וסימאה\u0004 (עיוור אותה) האדון בתוך כדי הטיפול, או שביקש מן האדון \u0003חתור לי שיני\u0004 (עשה נקב בשיני) כדי לרפאה, \u0003והפילה\u0004 את השן — הרי \u0003שיחק\u0004 (היתל) העבד \u0003באדון ויצא\u0004 על ידי כך \u0003לחרות.\u0004","\u0003רבן שמעון בן גמליאל אומר:\u0004 אין העבד יוצא לחירות במקרים אלה משום שנאמר בענין זה \u0003\"ושחתה\"\u0004 (שמות כא, פסוק כו) — \u0003עד שיתכוין\u0004 האדון במעשהו \u0003לשחתה\u0004 ולא כאשר הוא מתכוון לתקן ולרפא. ואף לענייננו, באבן שנפלה ופגעה בעינו או בשינו של העבד ולא התכוון האדון לפגוע בו, נחלקו חכמים ורבן שמעון בן גמליאל אם משתחרר העבד בכך. עד כאן דנים באופן שלא הכיר באבן.","ואם \u0003הכיר בה\u0004 באבן שהיא בחיקו \u0003ושכחה\u0004 שהיא נמצאת שם, \u0003ועמד, ונפלה\u0004 האבן, \u0003לענין נזקין\u0004 — גם כאן \u0003חייב\u0004 בוודאי, שהרי חייב גם אם לא ידע כלל. \u0003לענין ארבעה דברים\u0004 — גם כאן \u0003פטור,\u0004 שהרי לא נתכוון. אבל \u0003לענין גלות\u0004 — \u0003חייב,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ונס שמה רוצח מכה נפש \u0003בשגגה\"\u0004 (במדבר לה, יא) — \u0003מכלל דהוה ליה\u0004 \u0005[שהיתה לו\u0006 קודם\u0005]\u0006 \u0003ידיעה,\u0004 שזאת היא הגדרת המושג שגגה לענין זה — דבר ידוע שנשכח, \u0003והא הויא ליה\u0004 \u0005[והרי\u0006 כאן \u0005היתה לו]\u0006 \u0003ידיעה\u0004 קודמת באבן שבידו. \u0003לענין שבת\u0004 — גם כאן \u0003פטור,\u0004 שלא היתה \"מלאכת מחשבת\" בזריקת האבן. \u0003לענין עבד\u0004 — הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים]\u0006 כפי שאמרנו.","ובמקרה שנתכוון לזרוק את האבן, אלא ש\u0003נתכוין לזרוק\u0004 את האבן \u0003שתים\u0004 (שתי אמות) \u0003וזרק ארבע\u0004 אמות, שעלתה בידו יותר ממה שנתכוון, \u0003לענין נזקין\u0004 — \u0003חייב, לענין ארבעה דברים\u0004 — \u0003פטור, לענין שבת\u0004 — פטור, כי \u0003\"מלאכת מחשבת\" בעינן\u0004 \u0005[צריכים אנו]\u0006 כתנאי לחיובו ואין זו מלאכה שנעשתה מתוך כוונה. \u0003לענין גלות\u0004 הרי \u0003\"\u0004ו\u0003אשר לא צדה\"\u0004 (שמות כא, יג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שאם לא נתכוון להורגו — גולה, ובכלל זה \u0003פרט לנתכוין לזרוק שתים וזרק ארבע\u0004 שאף הוא לא צדה, והאבן הלכה רחוק ממה שנתכוון, \u0003לענין עבד\u0004 — הרי זו אותה \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 שאמרנו בין \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים].\u0006","ומקרה נוסף: אם \u0003נתכוין לזרוק\u0004 את האבן \u0003ארבע\u0004 אמות \u0003וזרק שמנה,\u0004 הרי \u0003לענין נזקין\u0004 — \u0003חייב, לענין ארבעה דברים\u0004 — \u0003פטור. לענין שבת,\u0004 אם היה \u0003אומר\u0004 בזמן זריקתו: \u0003כל מקום שתרצה תנוח,\u0004 כלומר, שלא הקפיד לזורקה דווקא למקום מסויים, הרי כיון שרצה לזורקה ארבע אמות, שהוא שיעור מלאכה שחייבים עליה בשבת — \u0003אין\u0004 \u0005[כן],\u0006 הרי הוא חייב, שהרי זרק כשיעור ארבע אמות שחייבים עליו. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 התכוון לזריקה סתם, אלא רצה לזורקה דווקא למקום מסויים — \u0003לא\u0004 יהא חייב, שהרי לא היתה זאת מלאכת מחשבת, שלא עלה בידו מה שחשב. \u0003לענין גלות,\u0004 הרי \u0003\"אשר לא צדה\"\u0004 נאמר שגולה, ובכלל זה \u0003פרט לנתכוין לזרוק ארבע וזרק שמנה. לענין עבד\u0004 — עדיין זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים].\u0006","כיון שהבאנו את הדברים שאמר רבה במקרים שיש בהם צדדי חיוב ופטור באותו מעשה, מביאים עוד דברים שקבע רבה באופנים שונים של עשיית אותו מעשה. \u0003ואמר רבה: זרק\u0004 אדם \u0003כלי\u0004 כגון חרס \u0003מראש הגג, ובא אחר ושברו במקל\u0004 תוך כדי נפילתו — הרי השובר במקל \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003מנא תבירא תבר\u0004 \u0005[כלי שבור שבר],\u0006 שהרי משעת זריקתו ברור שעתיד הכלי להישבר, ולכן מי ששברו באויר אינו חייב על שבירתו.","\u0003ואמר רבה\u0004 באותו מקרה ובאופן שונה: \u0003זרק כלי מראש הגג והיו תחתיו כרים או כסתות\u0004 שאם היה נופל עליהם לא היה נשבר, \u0003ובא אחר וסלקן\u0004 לאותם כרים, \u0003או קדם\u0004 הוא עצמו \u0003וסלקן\u0004 ונשבר הכלי — הרי זה \u0003פטור\u0004 מן הנזקים, אף שנשבר הכלי בגללו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003בעידנא דשדייה\u0004 \u0005[בזמן שזרקו]\u0006 הרי \u0003פסוקי מפסקי גיריה\u0004 \u0005[נפסקו חציו],\u0006 כלומר, הפעולה שעשה בשעת הזריקה שהיתה כעין יריית חץ, לא היתה עשויה לשבור את הכלי, ואחריותו לדבר נפסקת עם גמר הזריקה, ומה שקרה לאחר מכן הוא פעולה שניה ונוספת, שאינה קשורה בראשונה.","\u0003ואמר רבה: זרק תינוק מראש הגג, ובא אחר וקבלו בסייף\u0004 ומת התינוק — הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003ר' יהודה בן בתירא ורבנן\u0004 \u0005[וחכמים]\u0006 מי חייב מיתה על הריגתו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכוהו עשרה בני אדם בעשרה מקלות, בין\u0004 שהיכוהו כולם \u0003בבת אחת בין בזה אחר זה\u0004 — \u0003כולן\u0004"],["\u0003פטורין,\u0004 לפי שאף אחד מהם לא הרג את האדם כולו, ואין חייבים מיתה על הריגת מקצת נפש. \u0003ר' יהודה בן בתירא אומר:\u0004 אם הכוהו \u0003בזה אחר זה\u0004 — \u0003האחרון חייב, מפני שקירב\u0004 את \u0003מיתתו.\u0004 ואף כאן, אף שהראשון זרק את התינוק, השני שקיבל את התינוק בסייף קירב את מיתתו, ולדעת ר' יהודה בן בתירה יהיה חייב.","ועוד מקרה דומה: זרק תינוק מראש הגג ו\u0003בא שור\u0004 מועד \u0003וקבלו בקרניו\u0004 ומת — הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב המדבר בתשלום הכופר: \u0003\"ונתן פדין נפשו\"\u0004 (שמות כא, ל) משמעו \u0003דמי ניזק,\u0004 שצריך משלם הכופר לשלם דמיו של הניזק, \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר: דמי מזיק,\u0004 כי המזיק הוא זה שצריך לכפר ולפדות נפשו ממיתה. ולענייננו, התינוק שנזרק לא היו לו דמים בעת שנגחו השור, כיון שהיה בהכרח מת בנפילתו, ולפיכך, לדעת הסובר שבעל השור משלם דמי ניזק — הרי הוא פטור. ואולם לדעה שמשלם דמי מזיק — צריך לשלם כופר על עצמו. \u0003ו\u0004עוד \u0003אמר רבה\u0004 דין דומה: \u0003נפל\u0004 אדם \u0003מראש הגג ו\u0004בתוך כדי נפילתו \u0003נתקע באשה\u0004 באופן שנמצא שבא עליה, הרי זה \u0003חייב בארבעה דברים, וביבמתו\u0004 אם היתה אשה זו יבמתו — \u0003לא קנה\u0004 אותה בכך שתהא כאשתו. שלמרות שהיבם קונה את היבמה בביאה כלשהי (בשוגג ובלא כוונה) מכל מקום במקרה זה לא קנה, מפני שלא התכוון כלל לביאה.","","ומפרטים: מה הם אותם ארבעה דברים שחייב בהם: \u0003חייב בנזק, בצער, בריפוי, בשבת. אבל\u0004 ב\u0003בשת\u0004 — \u0003לא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אינו חייב על הבשת עד שיהא מתכוין\u0004 לבייש, וזה ודאי לא נתכוון לכך. \u0003ו\u0004עוד \u0003אמר רבה\u0004 במקרה דומה: \u0003נפל\u0004 אדם \u0003מראש הגג ברוח שאינה מצויה\u0004 שלא יכול היה להביא בחשבון מראש שיפול, ו\u0003הזיק ובייש\u0004 בנפילתו — \u0003חייב על הנזק, ופטור בארבעה דברים,\u0004 לפי שלא נתכוון לכך. אם \u0003ברוח מצויה\u0004 נפל, הרי זו פשיעה (רשלנות), \u0003ו\u0004לכן אם \u0003הזיק ובייש\u0004 בנפילתו — \u0003חייב בארבעה דברים, ו\u0004אולם \u0003פטור על הבשת,\u0004 שהרי לא נתכוון ליפול. \u0003ואם נתהפך\u0004 תוך כדי נפילתו, שהתכוון ליפול דווקא על האדם, כדי שלא יינזק בנפילה בקרקע — \u0003חייב אף על הבשת\u0004 שגרם, שאף שלא נתכוון לבייש מכל מקום נתכוון לפגוע,","","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ממשמע שנאמר \"ושלחה ידה\"\u0004 (דברים כה, יא) \u0003איני יודע שהחזיקה,\u0004 אם כן \u0003מה תלמוד לומר\u0004 בהמשך הכתוב \u0003\"והחזיקה\u0004 במבושיו \u0003\"?\u0004 \u0003לומר לך: כיון שנתכוין להזיק,\u0004 \u0003אף על פי שלא נתכוין לבייש\u0004 — חייב גם על הבושת שבדבר. \u0003ו\u0004עוד \u0003אמר רבה: הניח\u0004 אדם \u0003לו,\u0004 לאדם אחר, \u0003גחלת על לבו, ומת\u0004 אותו אדם בשריפה — \u0003פטור\u0004 המניח, משום שהלה היה צריך להסיר מעצמו את הגחלת, והמניח לא היה צריך לחשוב שהנפגע לא יסירנה ממנו ויישרף. אבל אם שם גחלת \u0003על בגדו\u0004 של חבירו \u0003ונשרף\u0004 הבגד — \u0003חייב,\u0004 שיתכן שאותו אדם סבור שיתבע את נותן הגחלת ויקבל את דמי הבגד, ולכן אינו טורח להסיר את הגחלת.","","\u0003אמר רבא: תרוייהו תננהי\u0004 \u0005[\u0006את \u0005שניהם שנינו]\u0006 ברמז במקומות אחרים. ענין זה של הניח גחלת \u0003על לבו\u0004 שפטור — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כבש עליו\u0004 (לחץ אדם ודחפו) \u0003לתוך האור\u0004 (האש) \u0003או לתוך המים, ואינו יכול לעלות משם, ומת\u0004 בתוך כך — \u0003חייב\u0004 מיתה, כרוצח. \u0003דחפו לתוך האור או לתוך המים, ויכול לעלות שם, ומת\u0004 — \u0003פטור,\u0004 ואף המניח גחלת על לבו הריהו כנותנו לתוך האור באופן שיכול לצאת משם.","וכן ענין המניח גחלת על \u0003בגדו\u0004 של חבירו שחייב גם כן שנינו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אמר לחבירו \u0003\"קרע את כסותי\", \"שבר את כדי\"\u0004 אם עשה כן — \u0003חייב\u0004 בתשלומים, אבל אם אמר לו \u0003\"\u0004קרע את כסותי \u0003על מנת לפטור\"\u0004 — \u0003פטור.\u0004 הרי שאף אם אמר לו חבירו במפורש להזיק והזיק — חייב, וכל שכן כאשר לא אמר לו חבירו כלום. שאין זה מסיר מעליו את האיסור להזיק לחבירו ואת האחריות למה שעשה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה\u0004 בהמשך לסיכומי ההלכות הללו: אם \u0003הניח גחלת על לב עבדו\u0004 של חבירו, \u0003מהו\u0004 \u0005[מה]?\u0006 האם \u0003כגופו\u0004 של אדם אחר \u0003דמי\u0004 \u0005[נחשב]\u0006 ופטור, \u0003או כממונו דמי\u0004 \u0005[נחשב]\u0006 וחייב? \u0003אם תמצא לומר\u0004 שכאשר הניח גחלת על לב עבד הרי זה \u0003כגופו דמי\u0004 \u0005[נחשב]\u0006 שהיה לו דעת לסלקה, הניח על \u0003שורו מהו?\u0004","\u0003הדר פשטה\u0004 \u0005[חזר, ופתר אותה\u0006 את השאלה\u0005]\u0006 באופן זה: \u0003עבדו כגופו\u0004 שהרי יש בו דעת להסיר הגחלת, \u0003שורו\u0004 הרי הוא \u0003כ\u0004שאר \u0003ממונו\u0004 — לפי שאין בו דעת.","","\u0003המניח את הכד ברשות הרבים ובא אחר ונתקל בה ושברה\u0004 — הרי זה \u0003פטור\u0004 על מה ששבר, \u0003ואם הוזק בה,\u0004 בכד — \u0003בעל החבית\u0004 שהניחה \u0003חייב בנזקו\u0004 של הניזק.","ומעירים: \u0003פתח\u0004 משנה זו \u0003בכד\u0004 (\"המניח את הכד\"), \u0003וסיים בחבית\u0004 (\"בעל החבית חייב\").","\u0003ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה להלן \u0005גם כן]\u0006 חילופי לשון אלה: שני אנשים שהיו מהלכים ברחוב, \u0003זה בא בחביתו וזה בא בקורתו, נשברה כדו של זה בקורתו של זה\u0004 — \u0003פטור.\u0004 אף שם התחלפו הלשונות: \u0003פתח בחבית וסיים בכד.\u0004 \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 כעין זה במשנה אחרת: \u0003זה בא בחביתו של יין וזה בא בכדו של דבש, נסדקה חבית של דבש\u0004 שהיא יקרה יותר \u0003ושפך זה יינו והציל את הדבש לתוכו\u0004 — \u0003אין לו אלא שכרו\u0004 (שכר טרחתו), אבל אינו יכול לתבוע את מחיר היין ששפך, כיון שלא עשה זאת על פי הוראתו של בעל הדבש. ואף כאן \u0003פתח בכד וסיים בחבית.\u0004","","\u0003אמר רב פפא:\u0004 מכל אלה אנו למדים כי \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003כד היינו\u0004 \u0005[זהו]\u0006 \u0003חבית\u0004 ואין הבדל מהותי ביניהם, ולכן המשנה מערבת ושונה שניהם כאחד. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא\u0006 להלכה \u0005מכאן]\u0006 מלימוד זה שכד וחבית נחשבים כדבר אחד? ומשיבים: \u0003למקח וממכר,\u0004 שאם ביקש אדם לקנות חבית ונתן לו המוכר כד — אין הקונה יכול לומר: לא לכך נתכוונתי.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003באתרא דכדא לא קרו\u0004 \u0005[במקום ש\u0006ל\u0005כד אין קוראים]\u0006 \u0003חבית, ו\u0004ל\u0003חבית לא קרו כדא\u0004 \u0005[אין קוראים כד]\u0006 אלא מבחינים ביניהם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא קרו\u0004 \u0005[קוראים]\u0006 \u0003לה,\u0004 לחבית, כד, וברור שאם מבקש אדם חבית רצונו בחבית ולא בכד!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקום \u0003דרובא קרו לה לכדא כדא ולחביתא חביתא\u0004 \u0005[שרוב\u0006 האנשים מקפידים ו\u0005קוראים לכד כד ולחבית חבית],\u0006 \u0003ואיכא נמי דקרו לחביתא כדא ולכדא חביתא\u0004 \u0005[ויש גם כן\u0006 אנשים \u0005הקוראים לחבית כד ולכד חבית]\u0006 וזאת באה ההלכה לחדש: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003זיל בתר רובא\u0004 \u0005[לך אחר הרוב],\u0006 וכיון שרוב האנשים מבחינים ביניהם, הרי אף המוכר והקונה חייבים להבחין ביניהם,"],["\u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנה ש\u0003אין הולכין בממון אחר הרוב,\u0004 שבספק בענייני ממונות אין הולכים לפי הרוב, אלא המוציא מחבירו עליו הראיה.","שנינו במשנה שאם \u0003בא אחר ונתקל בה\u0004 בחבית שהונחה ברשות הרבים \u0003ושברה\u0004 — \u0003פטור.\u0004 ושואלים על הלכה זו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור? איבעי ליה לעיוני ומיזל\u0004 \u0005[צריך היה לו להתבונן\u0006 במה שלפניו \u0005וללכת],\u0006 שאפילו ברשות הרבים אין אדם יכול להלך בלא להסתכל, ומדוע לא יתחייב על שבירת החבית!","\u0003אמרי דבי\u0004 \u0005[אמרי\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 מדובר כאן לא במניח חבית אחת אלא \u0003בממלא רשות הרבים כולה\u0004 ב\u0003חביות,\u0004 והרי הוא חוסם את דרכם של ההולכים בה, וכיון שרשות הרבים שייכת לכל אדם, יכול הוא לבקע דרכו בין החביות וללכת. \u0003שמואל אמר:\u0004 \u0003באפילה שנו\u0004 הלכה זו שבמשנתנו שפטור, שאז לא היה יכול להתבונן שלא ייתקל בחבית. \u0003ר' יוחנן אמר:\u0004 מדובר במקרה שהיתה החבית מונחת \u0003בקרן זוית\u0004 (פינה) של רשות הרבים, ולכן לא יכול היה ההולך לראותה קודם שנתקל בה.","על הסברים אלו \u0003אמר רב פפא: לא דיקא מתניתין\u0004 \u0005[אין משנתנו מדוייקת]\u0006 בלשונה \u0003אלא או כ\u0004פי שהסביר \u0003שמואל או כ\u0004פי שהסביר \u0003ר' יוחנן. דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004הסברו של \u0003רב,\u0004 \u0003מאי אריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 מדובר ב\u0003נתקל\u0004 בחבית? \u0003אפילו שבר\u0004 את החבית במזיד \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יהא חייב, שהרי אין בעל החבית רשאי לחסום את רשות הרבים.","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 אפשר לתרץ לשיטת רב כי \u0003הוא הדין\u0004 ש\u0003אפילו שבר\u0004 ביודעין יהא פטור, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 במשנתנו בלשון \u0003\"נתקל\",\u0004 טעמו של דבר הוא כי \u0003איידי דבעי למתני סיפא\u0004 \u0005[על ידי,\u0006 מתוך, \u0005שרצה לשנות\u0006 ב\u0005סופה]\u0006 \u0003ואם הוזק בה\u0004 — \u0003בעל\u0004 ה\u0003חבית חייב בנזקו,\u0004 שדין זה הוא \u0003דוקא\u0004 ב\u0003נתקל, אבל שבר\u0004 את החבית מדעת והוזק בה בשבירתו — \u0003לא\u0004 יצטרך בעל החבית לשלם לו על נזקו, למרות ששברה ברשות, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003הוא דאזיק אנפשיה\u0004 \u0005[שהזיק לעצמו],\u0006 שלא נזהר שלא ייפגע בזמן ששברה. לכן \u0003קתני רישא\u0004 \u0005[שנה\u0006 גם ב\u0005תחילתה]\u0006 \u0003\"נתקל\",\u0004 ואם כן אין להקשות מדיוק לשון המשנה על הסברו של רב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: הכי אמרי במערבא משמיה\u0004 \u0005[כך אומרים בארץ ישראל משמו]\u0006 של \u0003ר' עולא\u0004 הסבר אחר למשנה: אפילו היתה החבית במקום הנראה לעין — פטור הנתקל בה, \u0003לפי שאין דרכן של בני אדם להתבונן בדרכים,\u0004 שכן העובר מניח שרשות הרבים פנויה ופתוחה לכל, ואם לא התבונן ושבר דבר שהונח ברשות הרבים — אינו חייב לשלם.","מסופר: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 \u0003בנהרדעא\u0004 שנתקל אדם בכד במקום גלוי \u0003וחייב שמואל\u0004 את הנתקל לשלם. היה מעשה כזה \u0003בפומבדיתא, וחייב רבא.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שמואל\u0004 שפסק כן — עשה \u0003כשמעתיה\u0004 \u0005[כהלכתו,\u0006 כדעתו\u0005],\u0006 שהרי הוא אמר שהמשנה מדברת דווקא בנתקל באפילה. אבל במקרה אחר, היה לו להתבונן — וחייב. \u0003אלא רבא לימא כשמואל סבירא ליה\u0004 \u0005[האם לומר שכ\u0006 דעת \u0005שמואל\u0006 הוא \u0005סבור]\u0006 שפטור השובר ברשות הרבים רק אם היה הדבר באפילה?","\u0003אמר רב פפא:\u0004 לאו דווקא, \u0003קרנא דעצרא הוי\u0004 \u0005[קרן\u0006 זוית הסמוכה ל\u0005בית הבד היתה],\u0006 שהכל יודעים ששם מניחים אנשים את כדיהם כשהם ממתינים לקבל שמן, ש\u0003כיון\u0004 ש\u0003ברשות קעבדי\u0004 \u0005[עושים],\u0006 \u0003איבעי ליה לעיוני ומיזל\u0004 \u0005[היה צריך לו להתבונן\u0006 בדרכו \u0005וללכת].\u0006","ומביאים ענין בו הוזכרה גם משנתנו. מסופר: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב נחמן\u0004 שאלה זו: \u0003הרי אמרו\u0004 (כך אומרים, נוהגים הדיינים לפסוק) לגבי שיעורי עונשו של המכה את חבירו וביישו בכך: \u0003לרכובה\u0004 — אם בועט בו בברכו — משלם \u0003שלש\u0004 סלעים, \u0003ולבעיטה\u0004 — משלם \u0003חמש, ולסנוקרת\u0004 (אגרוף) — \u0003שלש עשרה.\u0004 ולפי זה \u0003לפנדא דמרא\u0004 \u0005[לקת המעדר]\u0006 \u0003ולקופינא דמרא\u0004 \u0005[לראש המעדר]\u0006 אם היכהו בהם \u0003מאי\u0004 \u0005[מה]\u0006 חייב לשלם לו?","\u0003שלח ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003חסדא חסדא, קנסא קא מגבית\u0004 \u0005[\u0006וכי \u0005קנס אתה גובה]\u0006 \u0003בבבל?!\u0004 הרי בבבל אין דיינים סמוכים ואינם רשאים לדון דיני קנסות, ואילו כל הסכומים שקצבו לתשלום בושת וכיוצא בהם — דיני קנסות הם. \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי גופא דעובדא היכי הוה\u0004 \u0005[גופו של מעשה איך היה],\u0006 שאוכל לדון בו.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 והסביר: \u0003דההוא גרגותא דבי תרי\u0004 \u0005[שהיה בור מים של שני\u0006 שותפים\u0005]\u0006 וההסדר ביניהם היה ש\u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003הוה דלי חד מנייהו\u0004 \u0005[היה דולה\u0006 ממנו \u0005אחד מהם]\u0006 לפי התור. \u0003אתא חד קא דלי ביומא דלא דיליה\u0004 \u0005[בא אחד\u0006 מהם \u0005דלה\u0006 מן הבור \u0005ביום שאינו שלו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 חבירו: \u0003יומא דידי\u0004 \u0005[היום שלי]\u0006 \u0003הוא\u0004 לדלות ולא שלך. \u0003לא אשגח ביה\u0004 \u0005[השגיח בו]\u0006 החבר. \u0003שקל פנדא דמרא\u0004 ו\u0003מחייה\u0004 \u0005[לקח\u0006 הלה \u0005קת של מעדר,\u0006 ו\u0005היכהו],\u0006 ותבעו הלה לדין על מכתו זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: אם כך היה הדבר \u0003מאה פנדי בפנדא למחייה\u0004 \u0005[מאה מכות במעדר\u0006 יש לו \u0005להכותו]\u0006 כי המכה צדק במה שעשה. שכן \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 בכלל: \u0003לא עביד איניש דינא לנפשיה\u0004 \u0005[אין אדם\u0006 רשאי \u0005לעשות דין לעצמו]\u0006 ועליו ללכת לדיין, גם לדעתו \u0003במקום פסידא\u0004 \u0005[הפסד]\u0006 אם לא יעשה מעשה — \u0003עביד איניש דינא לנפשיה\u0004 \u0005[עושה אדם דין לעצמו].\u0006","\u0003דאתמר\u0004 \u0005[שנאמר],\u0006 שנחלקו רב נחמן ורב יהודה בדבר, \u0003רב יהודה אמר: לא עביד איניש דינא לנפשיה\u0004 \u0005[אין אדם עושה דין לעצמו].\u0006 \u0003רב נחמן אמר: עביד איניש דינא לנפשיה\u0004 \u0005[עושה אדם דין לעצמו].\u0006","ומסבירים את מחלוקתם: \u0003היכא דאיכא פסידא\u0004 \u0005[במקום שיש הפסד]\u0006 אם לא יעשה מעשה — \u0003כולי עלמא לא פליגי דעביד איניש דינא לנפשיה\u0004 \u0005[הכל אינם חולקים,\u0006 ומודים \u0005שעושה אדם דין לעצמו].\u0006 \u0003כי פליגי היכא דליכא פסידא\u0004 \u0005[כאשר נחלקו,\u0006 הרי זה \u0005במקום שאין הפסד],\u0006 ש\u0003רב יהודה אמר: לא עביד איניש דינא לנפשיה\u0004 \u0005[אין אדם עושה דין לעצמו],\u0006 ש\u0003כיון דליכא פסידא\u0004 \u0005[שאין הפסד]\u0006 בדבר — \u0003ליזיל קמיה דיינא\u0004 \u0005[ילך לפני הדיין].\u0006 \u0003רב נחמן אמר: עביד איניש דינא לנפשיה\u0004 \u0005[עושה אדם דין לעצמו],\u0006 ש\u0003כיון\u0004 ש\u0003בדין\u0004 הוא \u0003עביד\u0004 \u0005[עושה]\u0006 — \u0003לא\u0004 צריך הוא \u0003טרח\u0004 \u0005[לטרוח]\u0006 וללכת לבית הדין, אלא יכול הוא לעשות דין לעצמו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא\u0004 ממה ששנינו, \u0003בן בג בג אומר: אל תיכנס\u0004 בחשאי \u0003לחצר חברך ליטול את שלך\u0004 ממנו \u0003שלא ברשות, שמא תראה עליו כגנב,\u0004 שיחשוד שאתה בא לגנוב ממנו, \u0003אלא שבור את שיניו,\u0004 כלומר, קח בחזקה, \u0003ואמור לו: שלי אני נוטל.\u0004 וקשה לדעת רב יהודה, שהרי מכאן רואים שעושה אדם דין לעצמו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003עמך!\u0004 כלומר, דבר זה יכול אתה להשאיר לעצמך, שאין זו קושיה כלל, הלא \u0003בן בג בג יחידאה\u0004 \u0005[יחיד]\u0006 \u0003הוא\u0004 בענין זה \u0003ופליגי רבנן עליה\u0004 \u0005[וחלקו חכמים עליו]\u0006 ואין להביא ממנו ראיה.","\u0003ר' ינאי אמר\u0004 תשובה אחרת: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שבור את שיניו\"\u0004 שבדברי בן בג בג — הכוונה הוצא ממנו \u0003בדין.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהכוונה היא שיתבענו לדין, הרי המשך הלשון \u0003\"ואמור לו\u0004 שלי אני נוטל \u0003\"\u0004אינו מתאים, אלא \u0003\"ואומרים לו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שבית דין הם האומרים לו, וכמו כן הלשון \u0003\"שלי אני נוטל\"\u0004 אינה מתאימה, אלא \u0003\"שלו הוא נוטל\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 אם הכוונה למה שנקבע בבית הדין! ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לפי הסבר זה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לענין זה, ממה ששנינו: \u0003שור שעלה על גבי חבירו להורגו, ובא בעל התחתון ושמט את\u0004 השור \u0003שלו, ו\u0004על ידי כך \u0003נפל\u0004 ה\u0003עליון ומת\u0004 — \u0003פטור. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004מקרה שהיה השור המזיק שור \u0003מועד, דליכא פסידא\u0004 \u0005[שאין הפסד]\u0006 לבעל השור המותקף, שגם אם לא ישמוט את שורו יקבל לבסוף מבעל השור המזיק את כל דמי הנזק, ובכל זאת שנינו שפטור אם גרם להריגת השור המזיק? משמע שאדם עושה דין לעצמו אף שלא במקום הפסד!","ודוחים: \u0003לא,\u0004 כאן מדובר \u0003ב\u0004מקרה שהשור התוקף היה \u0003תם, דאיכא פסידא\u0004 \u0005[שיש הפסד]\u0006 לבעל השור התחתון אם לא היה עושה מעשה, שהרי תם אינו משלם אלא חצי נזק.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: לא שמט את השור התחתון, אלא \u0003דחפו לעליון ומת\u0004 — \u0003חייב. ואי\u0004 \u0005[ואם]\u0006 \u0003ב\u0004שור \u0003תם\u0004 מדובר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הלא גם במקרה זה בעל השור מגן על רכושו שלא ייפסד!","ומשיבים: חייב לא משום שעשה מעשה אלא משום \u0003שהיה לו לשמטו\u0004 את השור שלו מתחת השור העליון \u0003ולא שמטו\u0004 אלא דחפו, ומשום כך מת, ועל כן חייב, אף שכרגיל אדם עושה דין לעצמו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, ממה ששנינו בברייתא: \u0003הממלא חצר חבירו כדי יין וכדי שמן\u0004 — \u0003בעל החצר משבר ויוצא, משבר ונכנס,\u0004 שכיון שהניח את הכדים שלא ברשות, אין בעל הבית צריך לחשוש כלל, ועושה דין לעצמו ומפנה לעצמו דרך, ומכאן שאדם עושה דין לעצמו גם באופן שאין נגרם לו הפסד!","\u0003אמר רב נחמן בר יצחק,\u0004 אפשר לומר כך: \u0003משבר ויוצא\u0004 בדרכו \u0003לבית\u0004 ה\u0003דין, משבר ונכנס\u0004 לביתו \u0003להביא זכיותיו,\u0004 כלומר, את התעודות והשטרות המוכיחים שהחצר שלו, ולשם כך יכול לצאת ולהיכנס ולשבר ביציאתו ובכניסתו, שהרי יש לו הפסד בכך, אבל יותר מזה אינו רשאי לעשות דין לעצמו, ואם כן אין הוכחה מכאן.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003מניין ל\u0004עבד \u0003נרצע שכלו לו ימיו,\u0004 שהגיעה שנת היובל, והרי הוא יוצא לחפשי, \u0003ורבו\u0004 (אדונו) \u0003מסרהב\u0004 (מפציר) \u0003בו\u0004 \u0003לצאת\u0004 והוא אינו רוצה, \u0003ו\u0004מתוך כך \u0003חבל\u0004 האדון בעבד \u0003ועשה בו חבורה\u0004 כדי להכריחו להשתחרר ולשוב לביתו, \u0003שהוא פטור\u0004 —","\u0003תלמוד לומר: \"\u0004ו\u0003לא תקחו כפר... לשוב\"\u0004 (במדבר לה, לב) ודרשוהו כאילו היה כתוב \u0003\"לא תקחו כפר לשב\"\u0004 שאדם זה השב למקומו ולבית אבותיו אין משלמים לו פיצויים אם נחבל כשלא רצה לשוב. משמע שמותר לו לאדון לעשות דין לעצמו אף שאין לו הפסד בדבר!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בעבדא גנבא\u0004 \u0005[בעבד גנב]\u0006 שאם ישאר יימצאו הבעלים נפסדים, ולכן רשאי לעשות דין לעצמו כאשר רוצה להיפטר ממנו.","ותוהים: \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא גנב, והשתא גנב\u0004 \u0005[ועכשיו\u0006 הוא \u0005גונב]?!\u0006 ומה ראה האדון להיזהר בו רק עכשיו? ומשיבים: \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 שהשתחרר \u0003הוה אימתיה דרביה עליה\u0004 \u0005[היתה אימת אדוניו עליו],\u0006 \u0003השתא לית ליה אימתא דרביה עליה\u0004 \u0005[עכשיו אין אימת אדוניו עליו].\u0006","\u0003רב נחמן בר יצחק אמר,\u0004 אפשר להסביר זאת באופן אחר: מדובר כאן \u0003בעבד שמסר לו רבו שפחה כנענית\u0004 והעבד רוצה להישאר עימה. \u0003עד האידנא\u0004 \u0005[עכשיו],\u0006 עד שהשתחרר, שפחה זו היא לו \u0003היתירא\u0004 \u0005[היתר],\u0006 שעבד עברי מותר בשפחה כנענית שנותן לו אדוניו, \u0003והשתא איסורא\u0004 \u0005[ועכשיו\u0006 היא \u0005איסור],\u0006 ואם רצונו להישאר עימה ואדוניו אינו מניח לו — הריהו נעשה כשליח בית דין, המפריש אותו מן האיסור. ואין זה משום עושה דין לעצמו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003המניח את הכד ברשות הרבים ובא אחר ונתקל בה ושברה\u0004 — \u0003פטור. טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003נתקל בה, הא\u0004 \u0005[הרי]\u0006 אם \u0003שברה\u0004 מדעת — \u0003חייב,\u0004 משמע שאין אדם עושה דין לעצמו!","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 אין להוכיח מכאן, ו\u0003הוא הדין אפילו שברה\u0004 מדעת יהא פטור, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003\"נתקל\"\u0004 — \u0003איידי דקבעי למיתני סיפא\u0004 \u0005[מתוך שרצה לשנות\u0006 ב\u0005סוף]\u0006 ש\u0003אם הוזק\u0004 השובר את החבית — \u0003בעל חבית חייב בנזקו,\u0004 ודין זה הוא \u0003דוקא\u0004 ב\u0003נתקל, אבל שבר\u0004 מדעת — \u0003לא,\u0004 מפני ש\u0003הוא אזיק נפשיה\u0004 \u0005[הזיק את עצמו]\u0006 בשבירה זו, לכן \u0003קתני רישא\u0004 \u0005[שנה\u0006 ב\u0005תחילה]\u0006 גם כן לשון \u0003\"נתקל\",\u0004 ואין לדייק מלשון זו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: נאמר באשה, שכדי לסייע לבעלה בקטטה החזיקה במבושיו של האחר \u0003\"וקצתה את כפה\"\u0004 (דברים כה, יב), ופירשו חכמים: אין הכוונה לכף ידה ממש אלא לעונש \u0003ממון. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004מקרה \u0003שאינה יכולה להציל\u0004 את בעלה מידי תוקפו \u0003על ידי דבר אחר,\u0004 אלא רק באופן זה שהחזיקה במבושיו של התוקף, ובכל זאת נענשת? משמע שאסור לאדם לעשות דין לעצמו! ודוחים: \u0003לא,\u0004 מדובר כאן \u0003שיכולה\u0004 היתה \u0003להציל על ידי דבר אחר.\u0004","וממשיכים להקשות: \u0003אבל\u0004 אם \u0003אינה יכולה להציל על ידי דבר אחר\u0004 לשיטתך \u0003פטורה\u0004 היא? \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אדתני סיפא\u0004 \u0005[\u0006\u0005עד\u0006 \u0005ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא \u0003\"ושלחה ידה\"\u0004 — \u0003פרט לשליח בית דין\u0004 שאינו נענש אם עושה זאת, כיון שעושה ברשות, \u0003לפלוג ולתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה],\u0006 בהבדלי דין זה עצמו, ויאמר כך: \u0003במה דברים אמורים\u0004 שחייבת — \u0003בשיכולה להציל על ידי דבר אחר, אבל אינה יכולה להציל על ידי דבר אחר\u0004 — \u0003פטורה!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, זו היא בעצם משמעות הדברים שבברייתא: \u0003במה דברים אמורים\u0004 — \u0003בשיכולה להציל על ידי דבר אחר, אבל אינה יכולה להציל על ידי דבר אחר\u0004 — \u0003נעשה ידה כשליח בית דין, ופטורה.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003הרי שהיתה דרך הרבים עוברת בתוך שדהו\u0004 של אדם, \u0003נטלה,\u0004 כלומר, נעל את הדרך לרבים, מפני שרצונו להשתמש בה לצורך אחר, \u0003ונתן להם,\u0004 לרבים, דרך אחרת שילכו \u0003מן הצד\u0004 — \u0003מה שנתן נתן,\u0004 כלומר, אותה דרך שנתן לרבים להשתמש בה — נתונה להם ורשאים הרבים ללכת בה, \u0003ושלו,\u0004 אותה דרך שרצה שתהיה שלו — \u0003לא הגיעו,\u0004 אינו יכול לקחת מהם, שאינו רשאי לקחת מן הרבים דבר שהיו משתמשים בו.","\u0003ואי אמרת עביד איניש דינא לנפשיה\u0004 \u0005[ואם אומר אתה\u0006 ש\u0005עושה אדם דין לעצמו]\u0006 מדוע אם כן אינו יכול לעצור את הרבים מלהשתמש בדרך? \u0003לנקוט פזרא וליתיב\u0004 \u0005[שיחזיק\u0006 שיקח \u0005מקל\u0006 בידו \u0005וישב]\u0006 בדרך זו שעוברת בתוך שדהו ולא יתן להם לעבור בה, שהרי רשותו היא זו, אלא שילכו בדרך האחרת שנתן להם!","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: גזירה\u0004 היא \u0003שמא יתן להם,\u0004 לרבים, \u0003דרך עקלתון,\u0004 שכיון שיש לרבים זכות מעבר בשדה זה אנו חוששים שמא יתן להם דרך שאינה ראויה, ומשום כך תיקנו שלא יוכל אדם לעשות זאת שלא מדעתם.","\u0003רב משרשיא אמר:\u0004 כאן מדובר \u0003ב\u0004מקרה שאכן \u0003נותן להם דרך עקלתון,\u0004 אבל אם נתן דרך ישרה — אינו צריך לוותר, שעושה אדם דין לעצמו, ויכול להכריחם שלא ילכו בדרך הראשונה.","\u0003רב אשי אמר: כל\u0004 שנתן דרך אחרת \u0003מן הצד\u0004 — \u0003דרך עקלתון הוא,\u0004 שהרי \u0003קרובה לזה ורחוקה לזה\u0004 שאמנם אחדים מן העוברים מרוויחים בכך, ואולם לאחרים רחוקה היא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003שלו לא הגיעו? לימא להו\u0004 \u0005[שיאמר להם]:\u0006 אם כן, אני מחזיר את הדברים לקדמותם, \u0003שקולו דידכו והבו\u0004 \u0005[קחו\u0006 את הדרך \u0005שלכם\u0006 הראשונה \u0005ותנו]\u0006 \u0003לי\u0004 חזרה \u0003דידי\u0004 \u0005[\u0006את \u0005שלי],\u0006 שלא יימצא נפסד מכל הצדדים!","ומשיבים: טעמו של דבר \u0003משום\u0004 מה שאמר \u0003רב יהודה.\u0004 ש\u0003אמר רב יהודה: מיצר שהחזיקו בו רבים\u0004 — \u0003אסור לקלקלו.\u0004 כלומר, דבר שהרבים כבר החזיקו בו אסור עכשו לקלקלו. וכיון שגם בדרך השניה החזיקו הרבים — אינו יכול עכשיו לקחתה מהם.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003בעל הבית שהניח פאה מצד אחד\u0004 של השדה, \u0003ובאו עניים ונטלו\u0004 \u0003מצד אחר\u0004 — \u0003זה וזה פאה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003עביד איניש דינא לנפשיה\u0004 \u0005[עושה אדם דין לעצמו],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003זה וזה פאה?\u0004 \u0003לנקוט פזרא וליתיב\u0004 \u0005[שיחזיק מקל וישב]\u0006 בשדהו בצד שממנו נוטלים עניים את הפאה שלא ברצונו, ויאמר לעניים: איני מרשה לכם ליטול מכאן, אלא מן הצד השני!","\u0003אמר רבא:\u0004 לענין ממונות באמת יכול הוא להבריחם במקל, שלא יקחו אלא מן החלק שהפריש. אבל כאן מדובר בנושא אחר, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זה וזה פאה\"\u0004 — \u0003לפוטרן מן המעשר,\u0004 כשם שעל אותו חלק שנטלו עניים אינם חייבים לתת ממנו מעשר, גם על החלק שנתן מתחילה לצורך העניים פטור מן המעשרות.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המפקיר את כרמו\u0004 לכל, \u0003והשכים\u0004 בעל הכרם \u0003בבקר,\u0004 לפני שנודע הדבר, \u0003ובצרו\u0004 — \u0003חייב בפרט ובעוללות ובשכחה ובפאה, ו\u0004אולם \u0003פטור מן המעשר.\u0004 שכיון שהפקירו — אין הפקר חייב במעשרות. ואף כאן, כיון שהפריש חלק מן השדה לפאה — הרי זה כאילו הפקירו לכל, ומשום כך נפטר אותו חלק מחיוב המעשרות.","\u0003נשברה כדו ברשות הרבים והוחלק\u0004 (החליק) \u0003אחד במים\u0004 שהיו בכד, ונפל ונחבל, \u0003או שלקה בחרסית,\u0004 בחרסים של שברי הכד — \u0003חייב\u0004 בעל הכד. \u0003ר' יהודה אומר: במתכוין\u0004 לשפוך את המים — \u0003חייב, באינו מתכוין\u0004 — \u0003פטור.\u0004","\u0003אמר רב יהודה אמר רב: לא שנו\u0004 במשנתנו שחייב בעל הכד לשלם נזקי כדו ברשות הרבים, \u0003אלא\u0004 באופן \u0003שטינפו\u0004 (נתלכלכו) \u0003כליו\u0004 (בגדיו) של המחליק \u0003במים\u0004 שהיו מטונפים,"],["\u0003אבל\u0004 אם \u0003הוא עצמו\u0004 נפל והוזק בהם — \u0003פטור\u0004 בעל הכד, כי \u0003קרקע עולם הזיקתו,\u0004 שהרי לא נחבל בכד ובמים, אלא בקרקע.","והוסיף רב יהודה: \u0003כי אמריתה\u0004 \u0005[כאשר אמרתיה]\u0006 להלכה זו שאמר רב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל,\u0004 \u0003אמר לי: מכדי\u0004 \u0005[הרי]\u0006 \u0003אבנו סכינו ומשאו\u0004 שהזיקו ברשות הרבים \u0003מבורו למדנו, וכולן אני קורא בהן,\u0004 שבכל אלה צריכים להתקיים אותם כללים לחיוב כמו בבור, שנאמר בו \"ונפל שמה שור או חמור\" (שמות כא, לג), ודרשו חכמים: \u0003\"שור\"\u0004 — \u0003ולא אדם, \"חמור\"\u0004 — \u0003ולא כלים.\u0004","\u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 בהגבלת האחריות עבורם אמורים רק \u0003לענין קטלא\u0004 \u0005[מיתה]\u0006 אם מת האדם, \u0003אבל לענין נזקין,\u0004 על \u0003אדם\u0004 שהוזק — \u0003חייב ו\u0004על \u0003כלים\u0004 — \u0003פטורין,\u0004 שאין בהם הבדל בין מיתה לנזק. ולכן צריך להיות להיפך, שחייב בנזקי אדם (שלדעת שמואל אף שנחבט בקרקע עולם — חייב) ופטור על נזקי הכלים.","ושואלים: \u0003ורב\u0004 כיצד הוא מסביר את דבריו? ומסבירים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאבנו סכינו ומשאו נעשו כבור, ופטור על הכלים שהוזקו בהם ברשות הרבים, אמורים \u0003היכא דאפקרינהו\u0004 \u0005[היכן\u0006 \u0005שהפקיר אותם],\u0006 ואחריותו מוגבלת רק על התקלה שגרם וכמו בבור. \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם]\u0006 — ככל \u0003ממונו\u0004 שהזיק \u0003הוא\u0004 וחייב גם על כלים שהוזקו בהם. ומכל מקום לדעתו פטור על האדם, שלא מימיו הזיקוהו, אלא קרקע עולם.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא\u0004 מברייתא השנויה על הכתוב בנזקי בור, נאמר: \u0003\"ונפל שמה שור או חמור\"\u0004 ופירשו חכמים: \u0003\"שור\"\u0004 — \u0003ולא אדם, \"חמור\"\u0004 — \u0003ולא כלים.\u0004 ו\u0003מכאן אמרו:\u0004 בור ש\u0003נפל לתוכו שור וכליו\u0004 וניזוק השור \u0003ונשתברו\u0004 הכלים, או \u0003חמור וכליו\u0004 וניזוק החמור \u0003ונתקרעו\u0004 הכלים — \u0003חייב על הבהמה, ופטור על הכלים. הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה\u0004 — \u0003לאבנו סכינו ומשאו שהניחן ברשות הרבים והזיקו.\u0004","ותחילה תוהים על לשון הברייתא: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 \u0003\"מה דומה לזה\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי אבנו סכינו ומשאו אינם כתובים בתורה והם נלמדים מדין בור! \u0003אלא\u0004 יש לתקן ולשנות אכן כך: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דומה לזה\u0004 — \u0003אבנו סכינו ומשאו שהניחן ברשות הרבים והזיקו.\u0004","וממשיכה הברייתא: \u0003לפיכך אם\u0004 אדם אחר \u0003הטיח\u0004 (השליך, מחמת שנפל) \u0003צלוחיתו באבן\u0004 שהניח הלה ברשות הרבים, ונשברה — \u0003חייב\u0004 בעל האבן","\u0003.\u0004 ולענייננו \u0003רישא קשיא\u0004 \u0005[ההתחלה\u0006 של הברייתא \u0005קשה]\u0006 \u0003לרב,\u0004 שהרי היא מדמה אבנו סכינו ומשאו לבור, ואינה מחלקת בין אם הפקיר אותם ובין אם לא. \u0003וסיפא קשיא\u0004 \u0005[וסופה קשה]\u0006 \u0003לשמואל\u0004 שאם הוכתה הצלוחית ונשברה באבן — חייב, ולדברי שמואל חייב רק בנזקי אדם ולא בנזקי כלים!","את הקושיה הזו דוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מבין את הדברים כך, אם כן \u0003תיקשי\u0004 \u0005[תקשה]\u0006 \u0003לך היא\u0004 הברייתא \u0003גופא\u0004 \u0005[עצמה],\u0006 שהרי ב\u0003רישא\u0004 \u0005[\u0006ב\u0005ראשה]\u0006 נאמר ש\u0003פטור\u0004 על נזקי כלים \u0003וסיפא\u0004 \u0005[ו\u0006ב\u0005סופה]\u0006 נאמר שהוא \u0003חייב!\u0004","\u0003אלא רב מתרץ\u0004 \u0005[מיישב\u0006 את הברייתא\u0005]\u0006 \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ושמואל מתרץ\u0004 \u0005[מיישב]\u0006 את הברייתא \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006","ומפרטים: \u0003רב מתרץ לטעמיה\u0004 \u0005[מיישב לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003במה דברים אמורים\u0004 שאבנו סכינו ומשאו דינם כבור ופטור על הכלים שנשברו בהם — הרי זה דווקא \u0003כשהפקירן, אבל\u0004 אם \u0003לא הפקירן\u0004 — \u0003חייב.\u0004 ו\u0003לפיכך\u0004 אם \u0003הטיח צלוחיתו באבן\u0004 השייכת לאדם אחר, שהניחה ברשות הרבים — \u0003חייב.\u0004","\u0003ושמואל מתרץ לטעמיה\u0004 \u0005[מיישב לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003השתא דאמרת\u0004 \u0005[עכשיו שאומר אתה]\u0006 \u0003אבנו סכינו ומשאו כבורו דמי\u0004 \u0005[נחשבים],\u0006 הרי \u0003ל\u0004דעת \u0003ר' יהודה\u0004 ש\u0003מחייב על נזקי כלים בבור,\u0004 יש לומר: \u0003לפיכך הטיח צלוחיתו באבן\u0004 — \u0003חייב.\u0004","ועל דין זה של הברייתא, שהטיח צלוחית באבן — חייב בעל האבן, \u0003אמר ר' אלעזר: לא שנו\u0004 שחייב \u0003אלא\u0004 במקרה \u0003שנתקל\u0004 בעל הצלוחית \u0003באבן ונשוף\u0004 (נשבר) הכלי \u0003באבן. אבל\u0004 אם \u0003נתקל בקרקע\u0004 ולא האבן גרמה לנפילתו, \u0003ונשוף\u0004 הכלי \u0003באבן\u0004 — הרי זה \u0003פטור.\u0004","ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 נאמרו הדברים — \u0003דלא כ\u0004דעת \u0003ר' נתן,\u0004 הסבור כי אם היו שני שותפים בנזק, אלא שמצד הדין אינו יכול לגבות מאחד מהם — גובה מן השני. ואף כאן, כיון שאינו יכול לגבות נזקיו מן הקרקע, לדעת ר' נתן יגבה אותם מבעל האבן.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 גרסה אחרת, \u0003אמר ר' אלעזר: לא תימא\u0004 \u0005[תאמר]\u0006 \u0003בנתקל באבן ונשוף באבן הוא דמחייב\u0004 \u0005[שחייב],\u0006 \u0003אבל נתקל בקרקע ונשוף באבן\u0004 — \u0003פטור, אלא אפילו נתקל בקרקע ונשוף באבן\u0004 — \u0003חייב,\u0004 ואם כן \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר דבר זה — \u0003כ\u0004דעת \u0003ר' נתן.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 שאם נשברה חבית ברשות הרבים, והחליק אדם במים או שהוזק בחרסים, שדווקא אם נשברה \u0003במתכוין חייב.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 ענין זה\u0005]\u0006 של \u0003מתכוין\u0004 שבכגון זה מחייב ר' יהודה","\u0003?\u0004 \u0003אמר רבה:\u0004 אף \u0003במתכוין להורידה\u0004 את החבית \u0003למטה מכתיפו,\u0004 ואז נפלה החבית ונעשתה מקור לנזק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מכלל\u0004 הדברים הללו אפשר ללמוד ש\u0003מחייב ר' מאיר\u0004 (שהוא התנא של סתם משנתנו) \u0003אפילו\u0004 כאשר \u0003נפשרה\u0004 (פקעה) החבית מעצמה, שהוא אונס? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מחייב היה ר' מאיר אפילו אזנה בידו,\u0004 שאפילו החזיק באוזנה של החבית כראוי, וניתקה האוזן ונשברה החבית, שדבר זה אונס גמור הוא — מכל מקום חייב בנזקים שגרמו שברי ומימי החבית.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הרי \u0003אנוס הוא, ו\u0004כלל הוא: \u0003אונס רחמנא פטריה\u0004 \u0005[התורה פטרה אותו]\u0006 מכל עונש, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בנערה האנוסה: \u0003\"ולנער\u0004 ה\u0003לא תעשה דבר\"\u0004 (דברים כב, כו)!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לענין קטלא\u0004 \u0005[מיתה],\u0006 שאין מחייבים אדם מיתה על מה שעשה באונס, \u0003אבל לענין נזקין\u0004 — \u0003חייב, והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003נשברה כדו\u0004 של אדם \u0003ולא סלקו\u0004 (את שברי הכד), \u0003נפל גמלו ולא העמידו\u0004 — \u0003ר' מאיר מחייב בהזיקן, וחכמים אומרים:\u0004"],["\u0003פטור מדיני אדם,\u0004 שאין זה בגדר בור, \u0003וחייב בדיני שמים\u0004 על שלא סילקם.","\u0003ומודים חכמים לר' מאיר באבנו סכינו ומשאו שהניחן בראש גגו ונפלו ברוח מצויה והזיקו\u0004 — \u0003שהוא חייב, ומודה ר' מאיר לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003במעלה קנקנין על הגג על מנת לנגבן\u0004 (לייבשם) \u0003ונפלו ברוח שאינה מצויה והזיקו\u0004 — \u0003שהוא פטור.\u0004 משמע שאפילו ר' מאיר המחמיר בדבר זה, מודה שאם נגרם היזק באונס הריהו פטור!","\u0003אלא אמר אביי:\u0004 יש לדחות מה שפירש רבה, שנחלקו ר' מאיר ור' יהודה במשנתנו במתכוון להוריד את החבית מעל כתיפו, ולפרש אחרת: \u0003בתרתי פליגי\u0004 \u0005[בשני\u0006 דברים \u0005נחלקו],\u0006 ואלו הם: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 כאשר גרמה החבית נזק \u0003בשעת נפילה, ופליגי\u0004 \u0005[ונחלקו]\u0006 כאשר גרמה החבית נזק \u0003לאחר נפילה.\u0004","ומסבירים: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בשעת נפילה ב\u0004שאלה האם ה\u0003נתקל פושע\u0004 (רשלן) הוא או לא. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003נתקל פושע הוא,\u0004 כלומר, אדם שנתקל בדבר — רשלנותו היא שגרמה לו להיתקל, וחייב בנזקים שנגרמו עקב כך. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור\u0006\u0005]:\u0006 \u0003נתקל לאו\u0004 \u0005[לא]\u0006 \u0003פושע הוא.\u0004","וכן \u0003פליגי\u0004 \u0005[נחלקו]\u0006 כאשר נגרם נזק \u0003לאחר נפילה, ב\u0004שאלה של \u0003מפקיר נזקיו, מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 ה\u0003מפקיר נזקיו,\u0004 כלומר, מפקיר חפץ שלו שגורם לנזק — \u0003חייב,\u0004 שאף שאין עוד החפץ קניינו, מכל מקום לא פקעה אחריותו לגבי נזקים. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 המפקיר נזקיו לגמרי — \u0003פטור,\u0004 שלאחר שהפקירם שוב אינו חייב באחריות על דבר שאינו שלו.","\u0003וממאי\u0004 \u0005[ומניין]\u0006 מסיק אתה מסקנה זו — \u0003מדקתני תרתי\u0004 \u0005[ממה ששנה\u0006 במשנה \u0005שנים,\u0006 שני מקרים\u0005]:\u0006 \u0003הוחלק אחד במים או שלקה בחרסית,\u0004 ולכאורה \u0003היינו הך\u0004 \u0005[זהו כך\u0006 אותו דבר\u0005]\u0006 ומה ההבדל בין זה לזה? \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר],\u0006 וכך יש להבין: \u0003הוחלק אחד במים בשעת נפילה, או שלקה בחרסית לאחר נפילה.\u0004","ומעירים: \u0003ומדמתניתין בתרתי\u0004 \u0005[ומ\u0006כיון \u0005שמשנתנו\u0006 עוסקת \u0005בשתים,\u0006 בשני מקרים\u0005],\u0006 \u0003ברייתא\u0004 שנחלקו בה ר' מאיר וחכמים בנשבר כדו ונפל גמלו \u0003נמי בתרתי\u0004 \u0005[גם כן בשתים,\u0006 בשני מקרים\u0005]\u0006 נחלקו: בתקלה שאירעה בשעת נפילה — בשאלה האם נתקל פושע הוא, ובתקלה שאירעה לאחר שהפקיר נזקיו.","ומעתה יש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003כדו משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 מחלוקת מתקיימת \u0003או בשעת נפילה או לאחר נפילה. אלא גמלו, בשלמא\u0004 \u0005[נניח]\u0006 \u0003לאחר נפילה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות זו שיפקיר נזקיו — \u0003במפקיר נבלתו,\u0004 שלא כדאי לו לטפל בנבילה ומפקירה. \u0003אלא בשעת נפילה היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 מציאות שנאמר בה שעצם נפילת הגמל היא ענין של פשיעה של בעליו?","\u0003אמר רב אחא: כגון\u0004 ש\u0003עברה\u0004 הבהמה \u0003במיא\u0004 \u0005[במים]\u0006 \u0003דרך שרעתא דנהרא\u0004 \u0005[התרחבות הנהר\u0006 בזמן הגאות\u0005]\u0006 ושם נתקל הגמל, שמעבר זה עצמו היה פשיעה, שלא היה לו לעבור שם.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאיכא דרכא אחרינא\u0004 \u0005[אם\u0006 במקרה \u0005שיש דרך אחרת]\u0006 לעבור והוא עובר דווקא בדרך זו — \u0003פושע הוא\u0004 לכל הדעות, \u0003ואי דליכא דרכא אחרינא\u0004 \u0005[ואם\u0006 במקרה \u0005שאין דרך אחרת]\u0006 — הרי \u0003אנוס הוא\u0004 ופטור לדברי הכל!","\u0003אלא משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 מציאות בה נחלקו אם נתקל פושע הוא, במקרה \u0003דאתקיל\u0004 \u0005[שנתקל]\u0006 הוא, בעל הבהמה, \u0003ו\u0004אחר כך \u0003אתקילה ביה גמלא\u0004 \u0005[נתקל בו הגמל]\u0006 שאז חוזרים אנו לבעיה אם אדם נתקל נחשב כפושע.","ושואלים: ולפי פירושו של אביי, שנחלקו ר' מאיר ור' יהודה גם ב\u0003מפקיר נזקיו, מאי\u0004 \u0005[מה]\u0006 \u0003מתכוין איכא\u0004 \u0005[יש\u0006 בו\u0005]?\u0006 שהרי שנינו שר' יהודה מחלק וסבור שהמתכוון חייב, ומה עניינו של מתכוון כאן, לאחר שנשבר הכד?","\u0003אמר רב יוסף: במתכוין לזכות\u0004 אחר כך \u0003בחרסיה\u0004 של החבית השבורה. ולפי זה לא הפקיר נזקיו, ודווקא אז לדעת ר' יהודה חייב הוא. \u0003וכן אמר לרב אשי: במתכוין לזכות בחרסיה.\u0004","\u0003ר' אלעזר אמר\u0004 לגבי פירוש הברייתא: \u0003בשעת נפילה מחלוקת.\u0004","ומבררים את שיטת ר' אלעזר: לפי דבריו \u0003אבל לאחר נפילה מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003דברי הכל פטור? והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003ר' מאיר\u0004 ש\u0003מחייב,\u0004 שהרי מדובר שם שלא סילקו את השברים! \u0003אלא מאי\u0004 \u0005[מה]\u0006 תפרש שלאחר נפילה \u0003דברי הכל חייב? והא איכא רבנן דפטרי\u0004 \u0005[והרי יש חכמים שפוטרים]!\u0006","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בשעת נפילה\"\u0004 — כוונתו: \u0003אף בשעת נפילה\u0004 מחלוקת, \u0003וקמשמע לן\u0004 \u0005[והשמיע לנו]\u0006 \u0003כ\u0004דברי \u0003אביי\u0004 בפירוש משנתנו, שהמחלוקת היא בין בשעת נפילה ובין לאחר נפילה."],["\u0003ור' יוחנן אמר: לאחר נפילה מחלוקת.\u0004","ושואלים: \u0003אבל בשעת נפילה מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 — \u0003דברי הכל פטור? והא מדקאמר\u0004 \u0005[והרי ממה שאמר]\u0006 \u0003ר' יוחנן לקמן\u0004 \u0005[לפנינו]\u0006 על משנה אחרת בפרקנו: \u0003לא תימא\u0004 \u0003מתניתין\u0004 \u0005[אל תאמר\u0006 ש\u0005משנתנו]\u0006 שיטת \u0003ר' מאיר היא\u0004 ש\u0003אמר נתקל פושע הוא,\u0004 \u0003מכלל\u0004 הדברים אתה למד כי הוא סבור ש\u0003ר' מאיר מחייב,\u0004 ואין כאן דברי הכל!","ומשיבים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר — \u0003דברי הכל חייב? והא מדקאמר\u0004 \u0005[והרי ממה שאמר]\u0006 \u0003ר' יוחנן לקמן\u0004 \u0005[לפנינו]:\u0006 \u0003לא תימא מתניתין\u0004 \u0005[אל תאמר\u0006 ש\u0005משנתנו]\u0006 \u0003ר' מאיר היא\u0004 ש\u0003אמר נתקל פושע הוא,\u0004 \u0003מכלל\u0004 הדברים אתה למד \u0003דפטרי רבנן\u0004 \u0005[שפוטרים חכמים]\u0006 ואינם סבורים שפושע הוא!","\u0003אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 ש\u0003מפקיר נזקיו דהכא\u0004 \u0005[של כאן]\u0006 \u0003הוא דפטרי רבנן\u0004 \u0005[שפוטרים חכמים]\u0006 כיון ש\u0003אנוס הוא\u0004 שנתקל, \u0003אבל מפקיר נזקיו דעלמא\u0004 \u0005[בכלל],\u0006 שלא מחמת אונס — הרי הם \u0003מחייבי\u0004 \u0005[מחייבים].\u0006","\u0003איתמר\u0004 \u0005[נאמר],\u0006 שנחלקו אמוראים במפורש בבעיה זו: \u0003מפקיר נזקיו,\u0004 כלומר, אדם שהשאיר דבר המזיק ברשות הרבים והפקירו, \u0003ר' יוחנן ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חייב, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פטור.\u0004","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מחייב\u0004 סבור \u0003כר' מאיר, ומאן דפטר כרבנן\u0004 \u0005[ומי שפוטר\u0006 סבור \u0005כחכמים]?\u0006","ודוחים: לא, \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' מאיר כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שמפקיר נזקיו חייב. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא דרבנן\u0004 \u0005[ל\u0006\u0005שיטת\u0006 \u0005חכמים].\u0006 \u0003מאן דפטר\u0004 \u0005[מי שפוטר]\u0006 סבור בפשטות \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ומאן דמחייב אמר\u0004 \u0005[ומי שמחייב\u0006 יכול \u0005לומר]\u0006 \u0003לך: אנא דאמרי\u0004 \u0005[אני שאומר אני]\u0006 את דברי \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אני אומרם, כיצד? \u0003עד כאן לא\u0004 שמעת כי \u0003פטרי רבנן\u0004 \u0005[פוטרים חכמים]\u0006 \u0003אלא במפקיר נזקיו דהכא\u0004 \u0005[של כאן]\u0006 במקרה שלנו, \u0003משום\u0004 ש\u0003אנוס הוא\u0004 שנתקל, \u0003אבל מפקיר נזקיו דעלמא\u0004 \u0005[בכלל]\u0006 — \u0003מחייבי\u0004 \u0005[מחייבים\u0006 הם\u0005].\u0006","במחלוקת זו לא היה ברור מי הוא זה שאמר חייב ומי אמר פטור, ומציעים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003ר' אלעזר\u0004 \u0003הוא\u0004 ש\u0003אמר חייב.\u0004 ש\u0003אמר ר' אלעזר משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל: שני דברים אינן ברשותו של אדם\u0004 מצד דיני הקניינים, \u0003ו\u0004בכל זאת \u0003עשאן הכתוב כאילו הן ברשותו,\u0004 שיש לו אחריות הלכתית עליהם, \u0003ואלו הן: בור\u0004 שחפר אדם \u0003ברשות הרבים, וחמץ\u0004 שנשאר ברשותו של אדם \u0003משש שעות ולמעלה\u0004 (כלומר, מחצות היום של ערב פסח), שאף שחמץ זה אסור בהנאה, ואם כן אין לו ערך והופקע מרשות בעליו, בכל זאת הוא מצווה בביעורו מן העולם. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכן הוא.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך]\u0006 שמפקיר נזקיו חייב? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר איפכא\u0004 \u0005[היפך]\u0006 הדברים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ההופך את הגלל\u0004 (זבל בהמות) \u0003ברשות הרבים והוזק בהן אחר\u0004 — ההופך \u0003חייב בנזקו. ואמר ר' אלעזר: לא שנו אלא שנתכוין\u0004 הופך הגללים \u0003לזכות בהן, אבל\u0004 אם \u0003לא נתכוין לזכות בהן\u0004 — \u0003פטור. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מפקיר נזקיו\u0004 — \u0003פטור,\u0004 שהרי מתחייב רק כאשר זכה בגללים הללו, ונעשו קניינו!","\u0003אמר רב אדא בר אהבה:\u0004 כשפטר ר' אלעזר את זה שהפך את הגלל בלא להתכוון לזכות בו, הרי זה במקרה \u0003שהחזירה,\u0004 את הגלל, \u0003למקומה\u0004 שהיה בו מתחילה. \u0003אמר רבינא: משל\u0004 של דברי \u0003רב אדא בר אהבה למה הדבר דומה\u0004 — \u0003למוצא בור מגולה\u0004 ברשות הרבים, \u0003וכסהו, וחזר וגילהו,\u0004 שהאחריות אינה מוטלת עליו, כיון שרק החזיר את מצב הדברים לקדמותו, ונשארה האחריות על מי שפתח תחילה את הבור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: מי דמי\u0004 \u0005[האם דומה]\u0006 המשל? \u0003התם\u0004 \u0005[שם]\u0006 בענין הבור \u0003לא אסתלק להו\u0004 \u0005[הסתלק לו]\u0006 \u0003מעשה ראשון\u0004 שהרי גם כשכיסה את הבור, הבור עצמו נשאר במקומו. \u0003הכא אסתלק להו\u0004 \u0005[כאן הסתלק להם]\u0006 \u0003מעשה ראשון,\u0004 שהרי כאשר סילק את הגלל ממקומו שוב לא היה שם \"בור\" (דבר הגורם לנזק) וכאשר החזירו — יצר מחדש דבר המזיק.","\u0003הא לא דמי\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא למוצא בור מגולה וטממה\u0004 (סתמו, ומילאוהו עפר) \u0003וחזר וחפרה, דאסתלקו להו\u0004 \u0005[שהסתלק לו]\u0006 ה\u0003מעשה\u0004 של החופר ה\u0003ראשון\u0004 \u0003וקיימא לה\u0004 \u0005[ועומד הוא]\u0006 \u0003ברשותו\u0004 של החופר השני, ואם כן צריך להיות חייב באופן שהעמיד רב אדא בר אהבה את דברי ר' אלעזר!","\u0003אלא אמר רב אשי:\u0004 כאן מדובר \u0003כשהפכה לפחות משלשה,\u0004 שלא הגביה את הגלל אלא פחות משלושה טפחים, שאין זו נקראת הזזה, והרי זה כמו שלא שינה כלל את המצב הקודם.","ושואלים: ולהסבר זה, \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003ר' אלעזר לאוקמיה\u0004 \u0005[להעמיד]\u0006 את המשנה במקרה המיוחד הזה \u0003כגון שהפכה לפחות משלשה, וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 \u0003דכי\u0004 \u0005[כאשר]\u0006 \u0003נתכוין לזכות בה\u0004 חייב, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין מתכוין לזכות בה\u0004 — \u0003לא? לוקמה\u0004 \u0005[שיעמידנה\u0006 את המשנה\u0005]\u0006 במקרה שהפכה \u0003למעלה משלשה, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא נתכוין לזכות בה\u0004 — \u0003חייב?\u0004","\u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו\u0006 עצמה היתה \u0005קשה לו],\u0006 והקושי הזה הוא שגרם לו להגיע למסקנה זו. כי \u0003מאי אריא\u0004 \u0005[מה שייך]\u0006 לשון \u0003\"הפך\"?\u0004 \u0003לתני\u0004 \u0005[שישנה]\u0006 \u0003\"הגביה\"! אלא\u0004 כיון שלא אמר \"הגביה\", שמשמעו סתם שהגביה לשם קנין ולמעלה משלושה טפחים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כל \"הפך\" למטה משלשה הוא.\u0004","ומעירים: כיון שהוכחנו ש\u0003ר' אלעזר אמר\u0004 כי המפקיר נכסיו ברשות הרבים והזיקו \u0003חייב,\u0004 אם כן \u0003ר' יוחנן\u0004 הוא ש\u0003אמר פטור.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שהמפקיר נזקיו פטור? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המצניע\u0004 (טומן, מחביא) \u0003את הקוץ ואת הזכוכית, ו\u0004כן \u0003הגודר גדרו בקוצים, וגדר שנפל לרשות הרבים, והוזק בהן\u0004 בכל אחד ממקרים אלה \u0003אחר\u0004 — הרי זה \u0003חייב בנזקו.\u0004","\u0003ואמר ר' יוחנן: לא שנו\u0004 בגודר גדרו בקוצים שחייב \u0003אלא במפריח,\u0004 כלומר, שהיו קוצי הגדר יוצאים בתוך רשות הרבים, \u0003אבל במצמצם\u0004 את הקוצים ברשותו — \u0003פטור.\u0004 ומעתה נברר: \u0003מצמצם מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003פטור\u0004 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 \u0003דהויא ליה\u0004 \u0005[שהרי הוא]\u0006 כ\u0003בור\u0004 \u0003ברשותו\u0004 שלו? ו\u0003מכלל\u0004 הדברים אתה לומד \u0003דחיובא\u0004 \u0005[שחיוב]\u0006 של \u0003בור\u0004 \u0003ברשות הרבים הוא. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מפקיר נזקיו חייב!\u0004 שהרי קוצים אלה בוודאי הפקירם.","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך: מפקיר נזקיו\u0004 בדרך כלל \u0003פטור, ומצמצם\u0004 את הגדר לרשותו \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003פטור?\u0004 לא משום שהוא בור ברשותו, אלא \u0003משום דאתמר עלה\u0004 \u0005[שכבר נאמר עליה],\u0006 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: לפי שאין דרכן של בני אדם להתחכך בכתלים\u0004 אלא להרחיק קצת מהם, ולכן אם אדם נתקל בקוצים של הגדר, אין זה נחשב למעשה רגיל אלא כיוצא דופן, ולכן אין בעל הגדר חייב על כך.","ושואלים עוד: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 כלל גדול: \u0003הלכה כסתם משנה. ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003החופר בור ברשות הרבים ונפל לתוכו שור או חמור ומת\u0004 — \u0003חייב,\u0004 משמע שחייב על נזקים בדבר שאינו קניינו!","\u0003אלא לעולם\u0004 תאמר ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שמפקיר נזקיו \u0003חייב.\u0004","ומקשים: \u0003ומ\u0004כיון ש\u0003ר' יוחנן\u0004 \u0003אמר חייב,\u0004 אתה צריך לומר כי \u0003ר' אלעזר\u0004 הוא הסבור ש\u0003פטור?\u0004 ואולם \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר\u0004"],["\u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל\u0004 שאדם חייב על הבור אף שאינו ברשותו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — שיטה \u0003דידיה\u0004 \u0005[שלו],\u0006 שסבור שעל נזקים שאינם שלו פטור. \u0003הא\u0004 \u0005[זו]\u0006 — \u0003דרביה\u0004 \u0005[של רבו],\u0006 כלומר, שאמר בשם ר' ישמעאל שסבור שחייב על נזקים אלה, אף כי הוא עצמו אינו סובר כן.","\u0003השופך מים ברשות הרבים והוזק בהן אחר\u0004 — \u0003חייב\u0004 השופך \u0003בנזקו. המצניע\u0004 (טומן, מחביא) \u0003את הקוץ ואת הזכוכית\u0004 באדמה, \u0003ו\u0004כן \u0003הגודר את גדרו\u0004 שבין רשותו לרשות הרבים \u0003בקוצים, ו\u0004כן \u0003גדר שנפל לרשות הרבים, והוזקו בהן אחרים\u0004 — הרי זה \u0003חייב בנזקן.\u0004","על מה ששנינו במשנה שהשופך מים ברשות הרבים חייב בנזקם, \u0003אמר רב: לא שנו\u0004 \u0003אלא\u0004 ש\u0003נטנפו\u0004 (נתלכלכו) \u0003כליו\u0004 של העובר \u0003במים, אבל הוא עצמו\u0004 שהוחלק בהם ונפל וניזוק — \u0003פטור\u0004 השופך, כי \u0003קרקע עולם הזיקתו\u0004 ולא המים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרב:\u0004 מדוע יפטר אם נחבט אדם בקרקע? \u0003לא יהא\u0004 דינם של המים שנשפכו באותו המקום \u0003אלא כרפשו\u0004 (הבוץ שלו) שהזיק ברשות הרבים שהרי עשו מים אלה טיט, וטיט זה שייך לו, וחייב על נזקיו!","ענה לו: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שמדובר ש\u0003לא תמו\u0004 נבלעו ויבשו \u0003מיא\u0004 \u0005[המים]\u0006 ונעשו רפש? כאן מדובר \u0003ב\u0004מקרה שכבר \u0003תמו מיא\u0004 \u0005[המים]\u0006 ונשארה רק לחלוחית, וממנה נתלכלכו בגדיו.","\u0003ו\u0004שאל: אם כן \u0003תרתי\u0004 \u0005[שתים]\u0006 שתי הלכות בענין ניטנפו כליו \u0003למה לי?\u0004 שהרי לשיטת רב כבר נאמרה הלכה זו במשנה הקודמת בענין הכד שנשבר והתלכלכו בגדיו במימיו!","ומשיבים: הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 נאמרה לנזק שאירע \u0003בימות החמה, וחדא\u0004 \u0005[ואחת]\u0006 לנזק \u0003בימות הגשמים.\u0004","והסבר להבדל בדברים, ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל אלו שאמרו פותקין ביבותיהן\u0004 (פותחים את הביב המנקז את השפכים מביתם) לרשות הרבים, \u0003וגורפין\u0004 (מנקים ומוציאים) החוצה את מי \u0003מערותיהן\u0004 שהיו מכונסים בהן מים שריחם רע, ש\u0003בימות החמה אין להן רשות\u0004 לעשות זאת, \u0003ובימות הגשמים\u0004 כיון שבין כה וכה יורד גשם \u0003יש להם רשות,\u0004 \u0003ואף על פי ש\u0004כל אלו \u0003ברשות\u0004 הם מוציאים את המים, \u0003אם הזיקו\u0004 אותם המים — \u0003חייבין לשלם.\u0004 וכיון שיש הבדל לענין רשות לשפוך מים בין ימות החמה וימות הגשמים, היה צורך לשנות גם משנה ראשונה וגם משנה זו, שאף ששפך ברשות — חייב בנזקים.","נאמר במשנה כי \u0003המצניע את הקוץ\u0004 ואת הזכוכית, והגודר את גדרו בקוצים — חייב בנזקו. ועל כך \u0003אמר ר' יוחנן: לא שנו\u0004 במשנתנו \u0003אלא מפריח,\u0004 שבנה את הגדר באופן שהיו הקוצים בולטים החוצה, \u0003אבל מצמצם,\u0004 שקוצי הגדר היו בתוך רשותו שלו — \u0003לא\u0004 חייב. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003פטור?\u0004 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: לפי שאין דרכן של בני אדם להתחכך בכתלים,\u0004 אלא בדרך כלל מרחיקים קצת מן הכותל, ונמצא שלא רק שהיה זה ברשותו, אלא שלא גרם היזק כלל ברשות הרבים.","ועוד באותו ענין, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המצניע קוצותיו\u0004 (קוציו) \u0003וזכוכיותיו לתוך כותל של חבירו, ובא בעל כותל וסתר כותלו ונפל לרשות הרבים, והזיקו\u0004 הקוצים והזכוכית — \u0003חייב המצניע.\u0004","\u0003אמר ר' יוחנן: לא שנו אלא בכותל רעוע,\u0004 שהיה המצניע צריך לשער שיהרסהו בעל הכותל במהרה, \u0003אבל בכותל בריא\u0004 (חזק) — \u0003המצניע פטור, וחייב בעל הכותל.\u0004","\u0003אמר רבינא, זאת אומרת: המכסה בורו בדליו של חבירו, ובא בעל הדלי ונטל דליו\u0004 ונגרם נזק בבור — \u0003חייב בעל הבור.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו שכן הוא\u0005],\u0006 שהרי הוא בדיוק כדברי ר' יוחנן בענין המצניע קוצים בכותל רעוע, שמתחילת הצנעת המזיק (הבור או הקוץ) עומד הוא להפוך למזיק, ומה חידש רבינא בדבריו?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 דווקא בכותל \u0003הוא\u0004 שפטור בעל הכותל, משום ש\u0003לא הוי ידע ליה דלודעיה\u0004 \u0005[ידע\u0006 מיהו \u0005אותו\u0006 שהצניע \u0005ש\u0006יוכל \u0005להודיעו]\u0006 שיוציא משם את קוציו, \u0003אבל הכא דידע ליה, הוה ליה לאודועיה\u0004 \u0005[כאן ש\u0006בעל הדלי הוא \u0005יודע אותו,\u0006 את בעל הבור, \u0005היה לו להודיעו]\u0006 שהוא נוטל משם את דליו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבינא, שאף כאן אין עליו חובה להודיע לבעל הבור, ואין מוטלת עליו כלל אחריות לדבר.","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חסידים הראשונים היו מצניעים קוצותיהם וזכוכיותיהם בתוך שדותיהן\u0004 שלהן, \u0003ומעמיקים להן\u0004 בהצנעה זו \u0003שלשה טפחים, כדי שלא יעכב\u0004 את \u0003המחרישה.\u0004","\u0003רב ששת שדי להו בנורא\u0004 \u0005[היה זורק אותם,\u0006 את קוציו, \u0005באש],\u0006 \u0003רבא שדי להו בדגלת\u0004 \u0005[היה זורק אותם ב\u0006תוך נהר \u0005חדקל]\u0006 הכל כדי שלא להזיק את הבריות.","\u0003אמר רב יהודה: האי מאן דבעי למהוי חסידא\u0004 \u0005[מי שרוצה להיות חסיד]\u0006 — \u0003לקיים מילי\u0004 \u0005[שיקיים\u0006 את \u0005הדברים]\u0006 של מסכת \u0003נזיקין\u0004 כדי שיימנע מלהזיק את חביריו. \u0003רבא אמר\u0004 שיקיים \u0003מילי\u0004 \u0005[הדברים]\u0006 שנאמרו במסכת \u0003אבות, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003מילי\u0004 \u0005[הדברים]\u0006 שנידונים במסכת \u0003ברכות.\u0004","\u0003המוציא את תבנו וקשו לרשות הרבים לזבלים,\u0004 שרוצה להשתמש בהם אחר כך לשם זיבול, \u0003והוזק בהן אחר\u0004 — \u0003חייב\u0004 המוציא את הקש \u0003בנזקו, וכל הקודם\u0004 לזכות \u0003בהן זכה\u0004 בהם, שיכול כל אדם לקחת קש זה לעצמו. \u0003רבן שמעון בן גמליאל אומר: כל המקלקלין ברשות הרבים והזיקו\u0004 בקלקול זה — \u0003חייבין לשלם, וכל הקודם בהן זכה.\u0004","\u0003ההופך את הגלל\u0004 (גללי בהמה) שהיו מונחים \u0003ברשות הרבים, והוזק בהן אחר\u0004 — \u0003חייב בנזקו.\u0004","ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 המחייבת את המוציא תבנו וקשו בנזקים שנגרמו ברשות הרבים. היא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 ש\u0003ר' יהודה אומר: בשעת הוצאת\u0004 ה\u0003זבלים,\u0004 כאשר דרך בני אדם לעשות זאת, \u0003אדם מוציא זבלו לרשות הרבים וצוברו\u0004 שם \u0003כל שלשים יום, כדי שיהא נישוף\u0004 (נדרס) \u0003ברגלי אדם וברגלי בהמה, שעל מנת כן הנחיל יהושע את הארץ,\u0004 כלומר, אין רשות לאחרים לעכב את המוציאים, כיון שעל תנאי זה קיבלו כל ישראל את הארץ בימי כיבושה בזמן יהושע בן נון. ואם כן, הואיל וברשות הוציא את זבלו — לא יתחייב עליו.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כדעת \u0003ר' יהודה,\u0004 מכל מקום \u0003מודה ר' יהודה שאם הזיק\u0004 — \u0003משלם מה שהזיק,\u0004 שאף שעשה ברשות, אין זה פוטר אותו מאחריות לנזקים.","ומקשים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 ש\u0003ר' יהודה אומר:\u0004 אם נדלקה ערימת קש שעל גבי בהמה העוברת ברשות הרבים \u0003בנר חנוכה\u0004 שהועמד ברשות הרבים — \u0003פטור\u0004 בעל הנר, \u0003מפני שהוא\u0004 מוציא את הנר לרשות הרבים \u0003ברשות.\u0004 משמע שדבר שנעשה ברשות — אינו חייב לשלם נזקיו. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שבעל הנר פטור \u0003משום\u0004 שהדליק ב\u0003רשות בית דין,\u0004 שכיון שיש לו רשות לעשות זאת בגלל הוראת בית דין שוב אינו חייב בנזקים?","ודוחים: \u0003לא, משום רשות מצוה,\u0004 שלא די בכך על מנת לפוטרו משום שמותר בכך, אלא דווקא אם מצוה לעשות כן. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בנר חנוכה\u0004 — \u0003פטור, מפני שהוא רשות מצוה,\u0004 שמפני שהוא מקיים מצוה הותר לו לעשות זאת. אבל דבר שאין בו מצוה, אף שיש לו רשות בית דין לעשות — אינו נפטר משום כך מחובת תשלום על נזקיו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקור אחר: \u0003כל אלו שאמרו מותרין לקלקל ברשות הרבים\u0004 — \u0003אם הזיקו חייבין ללשלם, ור' יהודה פוטר,\u0004 הרי למדנו במפורש שלדעת ר' יהודה אם עשה ברשות בית דין פטור מתשלום על נזקיו!","\u0003אמר רב נחמן: מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת כשהוציא \u0003שלא בשעת הוצאת זבלים\u0004 שאז אין לו רשות בית דין להוציא, \u0003ו\u0004שיטת \u0003ר' יהודה היא\u0004 שרק אם עשה שלא ברשות — חייב.","\u0003רב אשי אמר:\u0004"],["\u0003תבנו וקשו\u0004 דווקא \u0003תנן\u0004 \u0005[שנינו]\u0006 שחייב עליהם \u0003משום דמשרקי\u0004 \u0005[ש\u0006הם \u0005מחליקים]\u0006 ואנשים ניזוקים מהם יותר מבשאר דברים, ובזה אף ר' יהודה מודה שחייב עליהם.","שנינו במשנה כי המוציא את תבנו וקשו לרשות הרבים — \u0003כל הקודם בהן זכה.\u0004 ובפירושה של זכיה זו נחלקו חכמים. \u0003אמר רב:\u0004 זכה \u0003בין בגופן,\u0004 בעצם הדבר שהוציאו בעליו לרשות הרבים, \u0003בין בשבחן,\u0004 בריווח, בהשבחה שנוצרה בהם במשך הזמן שהיו ברשות הרבים. \u0003וזעירי אמר:\u0004 זכה \u0003בשבחן אבל לא בגופן,\u0004 וצריך לשלם לבעל הקש והתבן את שוויים כפי שהיה בזמן שהוציאם.","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 — \u0003רב סבר: קנסו גופן משום שבחן,\u0004 שקנסו חכמים על הבעלים שיפסידו את גוף הדבר שהוציא אף שהוא של בעליו, משום תוספת השבח שהרוויח על ידי מעשה אסור. \u0003וזעירי סבר: לא קנסו גופן משום שבחן,\u0004 אלא רק את שבחם בלבד. ומנסים להביא ראיה לשיטתו של זעירי, מדבר שאין בו שבח כלל.","\u0003תנן\u0004 \u0005[שנינו]\u0006 בהמשך המשנה: \u0003ההופך את הגלל ברשות הרבים והוזק בהן אחר\u0004 — \u0003חייב בנזקו. ואילו \"כל הקודם זכה\" לא קתני\u0004 \u0005[שנה],\u0006 הרי שעל גוף הדבר לא גזרו, וקשה לרב!","ומשיבים: מכאן אין להוכיח, כי \u0003תנא לרישא\u0004 \u0005[שנה בתחילה]\u0006 במוציא תבנו וקשו שהקודם זכה, \u0003והוא הדין לסיפא\u0004 \u0005[לסוף]\u0006 בהופך את הגלל שגם כן זכה בו, ולא היה צריך לחזור ולשנותו שנית.","ומקשים: \u0003והא תני עלה\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת \u0005עליה]:\u0006 \u0003אסורין משום גזל,\u0004 ומכאן שאין אדם אחר יכול לזכות בהם, וקשה לרב!","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \u0003\"אסורין משום גזל\"\u0004 — \u0003אכולה מתניתין קאי\u0004 \u0005[על כל משנתנו\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005]\u0006 ולא רק על קטע מסויים זה, והכוונה היא \u0003לאותו שקדם וזכה.\u0004 כלומר, כיון שזכה בהם אדם מן הרחוב — אסור באיסור גזל לכל אדם אחר לקחת את הדבר ממנו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא קתני הכי\u0004 \u0005[שנה כך],\u0006 \u0003דתנן\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוציא תבנו וקשו לרשות הרבים לזבלים, והוזק בהן אחר\u0004 — \u0003חייב בנזקו, וכל הקודם בהן זכה, ומותר משום גזל. וההופך את הגלל לרשות הרבים והוזק בהן אחר\u0004 — \u0003חייב, ואסור משום גזל!\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 וכי מדין \u0003גלל קרמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]\u0006 לשיטת רב שיכול אחר לזכות בו?! \u0003דבר שיש בו שבח,\u0004 כלומר, שערכו עולה במשך הזמן על ידי היותו ברשות הרבים, יכול אתה לתרץ לשיטת רב כי \u0003קנסו\u0004 את \u0003גופו\u0004 \u0003משום שבחו,\u0004 ואילו \u0003דבר שאין בו שבח\u0004 — \u0003לא קנסו\u0004 על גופו, והגללים אין ערכם עולה על ידי היותם ברשות הרבים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003לדברי\u0004 רב \u0003האומר\u0004 ש\u0003קנסו גופן משום שבחן,\u0004 האם \u0003לאלתר קנסינן\u0004 \u0005[מיד אנו קונסים]\u0006 אותו, שיכול אחר לזכות בו, אף שעדיין לא הספיק להשביח, \u0003או\u0004 שמא \u0003לכי מייתי שבחא קנסינן\u0004 \u0005[כאשר מביא שבח קונסים אנו]\u0006 אותו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, \u0003מדקאיירינן\u0004 \u0005[מכיון שדיברנו,\u0006 הקשינו\u0005]\u0006 מדין \u0003גלל\u0004 שאין בו שבח, משמע שקונסים אפילו לפני שהביא שבח!","ודוחים: \u0003ותסברא\u0004 \u0005[וסבור אתה]\u0006 שאפשר להוכיח מכאן? הלא \u0003כי איירינן\u0004 \u0005[כאשר דיברנו]\u0006 מדין \u0003גלל\u0004 היה זה \u0003מיקמי דלשני\u0004 \u0005[לפני שתירץ]\u0006 \u0003רב נחמן\u0004 בר יצחק שדין גלל שונה מאחרים. אבל \u0003לבתר דשני\u0004 \u0005[לאחר שתירץ]\u0006 \u0003רב נחמן\u0004 מה שתירץ, \u0003מי איכא למירמא\u0004 \u0005[האם יש\u0006 מקום \u0005להקשות]\u0006 מ\u0003גלל כלל?\u0004 ואין להביא משם ראיה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם\u0006 אפשר \u0005לומר\u0006 שהדבר שנוי במחלוקת \u0005תנאים]\u0006 שנחלקו באותו ענין, ששנינו: \u0003שטר שכתוב בו רבית\u0004 — \u0003קונסין אותו\u0004 את המלוה \u0003ואינו גובה לא את הקרן ולא את הרבית,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: גובה את הקרן, אבל לא את הרבית.\u0004 ואם כן \u0003לימא\u0004 \u0005[האם לומר]:\u0006 \u0003רב\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' מאיר\u0004 שלדבריו קונסים את גוף הדבר (הקרן) משום השבח (הריבית) האסור, \u0003וזעירי\u0004 ש\u0003אמר כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 שלדבריהם קונסים רק את השבח?","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את שיטתי \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אמרתי, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאין קונסים בגוף ההלוואה \u0003אלא\u0004 משום שהיתה זו \u0003קרן דבהתירא\u0004 \u0005[שבהיתר],\u0006 שהרי עצם ההלוואה של הקרן מעשה של היתר הוא, וכל האיסור הוא רק הריבית הנוספת, ואותה יש לקנוס. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במוציא קשו ותבנו לרשות הרבים, \u0003קרן גופא\u0004 \u0005[עצמו]\u0006 הדבר עצמו \u0003קמזיק\u0004 \u0005[מזיק]\u0006 ויש מקום לקנוס אותו בגוף הדבר.","\u0003ו\u0004מן הצד השני \u0003זעירי אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: אנא דאמרי\u0004 \u0005[אני שאמרתי\u0006\u0005]\u0006 את שיטתי \u0003אפילו ל\u0004דעת \u0003ר' מאיר\u0004 אמרתי, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 בהלוואה בריבית שאינו גובה אף הקרן, \u0003אלא\u0004 משום ש\u0003משעת כתיבה\u0004 של השטר כבר נעשית עבירה, \u0003דעבד ליה שומא\u0004 \u0005[ש\u0006כבר \u0005עשה את ההערכה]\u0006 בשטר בשעת כתיבת הסכום, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כשמוציא את קשו ותבנו לרשות הרבים \u0003מי יימר דמזיק\u0004 \u0005[מי יאמר\u0006 שהקש כלל \u0005יזיק]?\u0006 וכיון שבשעת הנחת הקש והתבן אין זה בהכרח שיזיקו — אין מקום לקנוס את האיש בקש ובתבן עצמם.","ומציעים עוד: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שרב וזעירי חלוקים \u0003כהני תנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים אלה],\u0006 ששנינו: \u0003המוציא תבנו וקשו לרשות הרבים לזבלים, והוזק בהן אחר\u0004 — \u0003חייב\u0004 המוציא \u0003בנזקו, וכל הקודם\u0004 לזכות \u0003בהן,\u0004 בזבלים — \u0003זכה, ואסורין משום גזל. רבן שמעון בן גמליאל אומר: כל המקלקלין ברשות הרבים והזיקו\u0004 — \u0003חייבין לשלם, וכל הקודם בהן זכה, ומותרין משום גזל.\u0004","ומעתה נברר: \u0003הא גופא קשיא\u0004 \u0005[\u0006הברייתא הזו \u0005היא עצמה קשה],\u0006 \u0003אמרת\u0004 בדברי חכמים: \u0003כל הקודם בהן זכה, והדר קאמר\u0004 \u0005[וחזר ואמר]\u0006 \u0003אסורין משום גזל,\u0004 משמע שאסור לזכות בהם! \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר],\u0006 כך יש להבין את הדבר: \u0003וכל הקודם בהן זכה\u0004 כוונתו — \u0003בשבחן, ואסורין משום גזל\u0004 כוונתו — \u0003אגופן\u0004 \u0005[לגבי גופן].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]:\u0006 \u0003אפילו גופן נמי\u0004 \u0005[גם כן]\u0006 \u0003כל הקודם בהן זכה.\u0004 ונמצא שיש מחלוקת תנאים אם קנסו גם בגופם או רק בשבחם.","ומעירים: \u0003ל\u0004דעת \u0003זעירי ודאי\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 יש בכך, שהרי רבן שמעון בן גמליאל במפורש מתיר אותם משום גזל, ואולם \u0003ל\u0004דעת \u0003רב, מי לימא תנאי\u0004 \u0005[האם לומר\u0006 כי מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004","משיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב:\u0004 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]:\u0006 \u0003קנסו גופן משום שבחן, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה של \u0003הלכה ואין מורין כן קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בענין זה של קנסו גופם משום שבחם אם מורים כן לרבים, ש\u0003רב הונא אמר ד\u0004בשם \u0003רב: הלכה ואין מורין כן,\u0004 כלומר, שאמנם מותר למוצא לקחת לעצמו אף את גוף הקש והתבן, אבל אין מורים לרבים בפומבי לעשות כן, כדי שלא ילמדו דרכי גזל, והיא כדברי תנא קמא בברייתא. \u0003רב אדא בר אהבה אמר: הלכה, ומורין כן,\u0004 וכדברי רבן שמעון בן גמליאל.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שכך דעתם? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא\u0004 עצמו \u0003אפקר חושלי\u0004 \u0005[הפקיר שעורים\u0006 קלופות\u0005]\u0006 ששטח אדם אחד ברשות הרבים, וכן \u0003רב אדא בר אהבה אפקר\u0004 \u0005[הפקיר]\u0006"],["\u0003סליקוסתא\u0004 \u0005[פסולת של תמרים].\u0006","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רב אדא בר אהבה\u0004 — \u0003כשמעתיה\u0004 \u0005[כהלכתו]\u0006 עשה, שהרי לדעתו הלכה ומורים כן. \u0003אלא רב הונא, לימא הדר ביה\u0004 \u0005[האם לומר\u0006 ש\u0005חזר בו]\u0006 מדעתו?","ומשיבים \u0003הנהו\u0004 \u0005[אלו]\u0006 בעלי השעורים \u0003מותרין הוו\u0004 \u0005[היו],\u0006 שהתרו בהם שיפנו את שעוריהם מרשות הרבים ולא פינו, ובמקרה זה ודאי מותר לקנוס אותם ולהורות לרבים שהכל הפקר.","\u0003שני קדרין\u0004 נושאי קדרות \u0003שהיו מהלכין\u0004 ברשות הרבים \u0003זה אחר זה, ונתקל הראשון\u0004 בגבשושית \u0003ונפל, ונתקל השני בראשון\u0004 ונפל — \u0003הראשון חייב ב\u0004תשלומי \u0003נזקי\u0004 ה\u0003שני.\u0004","ומבררים את משנתנו, \u0003אמר ר' יוחנן: לא תימא\u0004 \u0005[אל תאמר]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 רק כדעת \u0003ר' מאיר היא,\u0004 ש\u0003אמר נתקל פושע\u0004 (רשלן) \u0003הוא וחייב, אלא אפילו ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 כרגיל שהנתקל \u0003אנוס הוא ופטור, הכא\u0004 \u0005[כאן]\u0006 במקרה הזה \u0003חייב,\u0004 כיון שמדובר במקרה \u0003שהיה לו\u0004 אפשרות לאחר שנפל \u0003לעמוד ולא עמד.\u0004","\u0003רב נחמן בר יצחק אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר במקרה בו \u0003לא היה לו לעמוד,\u0004 מכל מקום \u0003היה לו להזהיר\u0004 את ההולך אחריו \u0003ולא הזהיר.\u0004","ומעירים: \u0003ור' יוחנן אמר\u0004 \u0005[\u0006יכול \u0005לומר]:\u0006 אין הדבר כן, כי במקרה שכזה \u0003כיון\u0004 ש\u0003לא היה לו לעמוד\u0004 — גם כן \u0003לא היה לו להזהיר, דטריד\u0004 \u0005[ש\u0006הוא \u0005טרוד]\u0006 לקום מנפילתו, ובהכרח יש לפרש את משנתנו המחייבת אותו, בזמן שהיה יכול לעמוד.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה להלן\u0005]:\u0006 \u0003היה בעל קורה\u0004 מהלך ברשות הרבים \u0003ראשון\u0004 וקורתו על גבו \u0003ובעל חבית אחרון,\u0004 כלומר, אחריו. \u0003נשברה חבית בקורה\u0004 — \u0003פטור\u0004 בעל הקורה, \u0003ואם עמד בעל קורה\u0004 — \u0003חייב,\u0004 שהרי הוא גרם בעצירתו שתישבר החבית.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003שעמד\u0004 שנעצר בעל הקורה על מנת \u0003לכתף\u0004 עליו את משאו, \u0003דאורחיה\u0004 \u0005[שדרכו]\u0006 \u0003הוא\u0004 לעשות כן, ואין בכך פשיעה, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[ושנה]\u0006 \u0003חייב,\u0004 וטעמו של דבר משום \u0003דהוה ליה\u0004 \u0005[שהיה לו]\u0006 \u0003להזהיר\u0004 את ההולך אחריו שהוא עומד ולא הזהיר, ומכאן ראיה לשיטת רב נחמן.","ודוחים: \u0003לא,\u0004 כאן מדובר \u0003כשעמד לפוש\u0004 (לנוח) וזה שהלך מאחוריו לא יכול היה לשער שיעשה כן, ומשום כך נתחייב.","ושואלים: אם כן, לשיטה זו \u0003אבל עמד לכתף מאי\u0004 \u0005[מה]\u0006 יהא דינו — \u0003פטור?\u0004 אם כן \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003ואם אמר לו לבעל חבית \"עמוד\"\u0004 — \u0003פטור,\u0004 אם כן \u0003לפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה\u0006 בהלכה ראשונה \u0005עצמה]\u0006 חלוקה זו: \u0003במה דברים אמורים\u0004 שחייב — \u0003כשעמד לפוש, אבל עמד לכתף\u0004 — \u0003פטור!\u0004","ומשיבים: במשנה זו יש חידוש גדול יותר בנוסח זה, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003עמד לפוש, כי קאמר לו\u0004 \u0005[כאשר אומר לו]\u0006 \u0003לבעל חבית \"עמוד\"\u0004 — \u0003פטור.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003הקדרין והזגגין שהיו מהלכין זה אחר זה, נתקל הראשון\u0004 בקרקע \u0003ונפל, ונתקל השני בראשון\u0004 ונפל וניזוק, \u0003והשלישי בשני\u0004 ונפל וניזוק — \u0003ראשון חייב בנזקי שני, ושני חייב בנזקי שלישי. ואם מחמת ראשון נפלו\u0004 כולם — \u0003ראשון חייב בנזקי כולם. ואם הזהירו זה את זה\u0004 — \u0003פטורין. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה \u0003שלא היה להן\u0004 אפשרות \u0003לעמוד,\u0004 ובכל זאת חייבים אם לא הזהירו, וכדעת רב נחמן?","ודוחים: \u0003לא,\u0004 כאן מדובר במקרה \u0003שהיה להן\u0004 אפשרות \u0003לעמוד\u0004 ולא עמדו.","ושואלים: ולפי שיטה זו \u0003אבל\u0004 אם \u0003לא היה להם לעמוד מאי\u0004 \u0005[מה]\u0006 יהא הדין — ש\u0003פטור? אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003אם הזהירו זה את זה\u0004 — \u0003פטור, לפלוג וליתני בדידה\u0004 \u0005[שיחלוק וישנה בה\u0006 בהלכה זו \u0005עצמה],\u0006 ויאמר: \u0003במה דברים אמורים\u0004 — \u0003שהיה להן לעמוד, אבל לא היה להן לעמוד\u0004 — \u0003פטורין!\u0004","ודוחים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003היה להן לעמוד,\u0004 מכל מקום \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003הזהירו זה את זה\u0004 — \u0003פטורין.\u0004","על הלכה זו \u0003אמר רבא:\u0004 ה\u0003ראשון\u0004 שנתקל \u0003חייב בנזקי שני\u0004 — \u0003בין בנזקי\u0004 השני שנגרמו על ידי \u0003גופו\u0004 של הראשון, \u0003בין בנזקי ממונו\u0004 שנתקל בכליו של ראשון. ואילו ה\u0003שני חייב בנזקי שלישי\u0004 רק \u0003בנזקי גופו,\u0004 אם נפגע השלישי מגופו של השני בנפילה זו, \u0003אבל לא\u0004 חייב \u0003בנזקי ממונו.\u0004","על דברי רבא תוהים: \u0003ממה נפשך\u0004 \u0005[רצונך]?\u0006 כלומר, בכל צד שתרצה, הדבר תמוה. כי \u0003אי\u0004 \u0005[אם]\u0006 סבור אתה כי \u0003נתקל פושע הוא\u0004 שרשלנותו היא שגרמה — \u0003שני נמי ליחייב\u0004 \u0005[גם כן שיתחייב]\u0006 לשלם הכל, שהרי אף הוא פושע הוא. ו\u0003אי\u0004 \u0005[ואם]\u0006 סבור אתה כי \u0003נתקל לאו\u0004 \u0005[לא]\u0006 \u0003פושע הוא,\u0004 אם כן \u0003אפילו\u0004 ה\u0003ראשון נמי ליפטר\u0004 \u0005[גם כן ייפטר]\u0006 ממה שהזיק את השני!"],["ומסבירים: \u0003ראשון ודאי פושע הוא\u0004 ולכן חייב על נזקי גופו ועל נזקי ממונו. \u0003שני,\u0004 על נזקים שהזיק ב\u0003גופו מחייב\u0004 \u0005[מתחייב]\u0006 — משום \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003לו לעמוד ולא עמד.\u0004 ואילו על \u0003ממונו,\u0004 כגון כליו שהיו שם ונתקל בהם השלישי — \u0003פטור, דאמר ליה\u0004 \u0005[\u0006שיכול הוא \u0005לומר לו]:\u0006 \u0003האי בירא לאו אנא כריתיה\u0004 \u0005[בור זה,\u0006 תקלה זו, \u0005לא אני כריתיו],\u0006 שהנופל הראשון הוא שגרם לתקלה, שחפציו של השני מוטלים על הארץ, ולכן אין השני חייב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מברייתא האומרת על מקרה זה: \u0003כולן חייבין על נזקי גופן ופטורין על נזקי ממונן. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה במה ששנינו \"כולם\" \u0003אפילו ראשון\u0004 ולמדנו שאף הוא פטור אם הזיק ממונו? והרי זו קושיה על רבא.","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מראשון.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"כולם\" קתני\u0004 \u0005[שנה],\u0006 משמע שאפילו הראשון בכלל! \u0003אמר רב אדא בר אהבה: \"כולן\"\u0004 פירושו כל \u0003הניזקין,\u0004 אבל הראשון הוא רק מזיק ואין הוא נכלל ב\"כולם\" זה.","על תירוץ זה תוהים: \u0003האי מאי\u0004 \u0005[זה מה\u0006 הוא\u0005]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\"כולן\" משמעו \u0003אפילו ראשון\u0004 — \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"כולן\"\u0004 משום שזו הדרך היחידה לכלול את כל האנשים שמדובר בהם, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהכוונה \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מראשון, מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"כולן\",\u0004 שהיא לשון שיש בה להטעות? \u0003ליתני\u0004 \u0005[שישנה]\u0006 לשון מדוייקת, ויאמר כך: \u0003הניזקין\u0004 חייבים על נזקי גופם, ופטורים על נזקי ממונם!","\u0003אלא,\u0004 יש לחזור לגמרי מהלכה זו כולה ולגרוס כך, \u0003אמר רבא: ראשון חייב בין בנזקי גופו\u0004 של \u0003שני בין בנזקי ממונו\u0004 של \u0003שני, ושני חייב בנזקי שלישי בנזקי גופו\u0004 של שלישי, \u0003אבל לא בנזקי ממונו. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 גופו, כשנפל, נעשה \u0003בור,\u0004 \u0003ולא מצינו\u0004 \u0005[מצאנו]\u0006 \u0003בור שחייב בו את הכלים\u0004 ולכן פטור על נזקי כלים.","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר: כל תקלה\u0004 שאדם גורם ברשות הרבים \u0003בור הוא,\u0004 ודינה דין בור, \u0003אלא ל\u0004דעת \u0003רב\u0004 ש\u0003אמר:\u0004 \u0003אי אפקריה\u0004 \u0005[אם הפקירו]\u0006 את גורם התקלה — \u0003אין\u0004 \u0005[כן]\u0006, דינו כדין בור, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 הפקירו — \u0003לא,\u0004 לשיטתו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בזה? שהרי הנופל לא הפקיר את עצמו, ומדוע יהא דינו כבור לפטור את נזקי הכלים!","ומשיבים: \u0003לעולם\u0004 תפרש \u0003כ\u0004מו ש\u0003אמר מעיקרא\u0004 \u0005[מתחילה]\u0006 שרבא דיבר על נזקי גופו וממונו של המזיק. \u0003ודקשיא\u0004 \u0005[ו\u0006מה \u0005ש\u0006היה \u0005קשה]\u0006 \u0003לך\u0004 מלשון הברייתא: \u0003\"כולן חייבין\u0004 על נזקי גופם אבל פטורים על נזקי ממונם \u0003\"\u0004ונכלל בזה אף הראשון, שלא כשיטת רבא — \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב אדא בר מניומי קמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא\u0004 שמדובר שם \u0003שהוזקו כלים בכלים,\u0004 שניזקו הכלים של השני לא מחמת גופו של הנופל, אלא מחמת כליו של הנופל, וכלים שבורים אלה ודאי הם בגדר בור שפטור בו על הכלים.","כיון שהובאה ברייתא זו מבארים בה פרט נוסף: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אם מחמת\u0004 ה\u0003ראשון נפלו\u0004 — \u0003ראשון חייב בנזקי כולם.\u0004 ושואלים: \u0003מחמת\u0004 ה\u0003ראשון היכי נפיל\u0004 \u0005[כיצד נפלו]\u0006 כולם? \u0003רב פפא אמר: דפסקה לאורחיה כשלדא\u0004 \u0005[שפסק,\u0006 חסם, \u0005את הדרך כשלד],\u0006 כלומר, שנפל לרוחב הדרך וממלא אותה, וכולם נתקלים במקומות שונים בגופו. \u0003רב זביד אמר: כחוטרא דסמיותא\u0004 \u0005[כמקל של עוורים],\u0006 שנפל באלכסון, ועל ידי כך כולם נתקלים בו.","\u0003זה בא בחביתו\u0004 ברשות הרבים \u0003וזה בא\u0004 מולו דלל \u0003בקורתו,\u0004 שהיו מהלכים זה כנגד זה. \u0003נשברה כדו של זה בקורתו של זה\u0004 — \u0003פטור\u0004 בעל הקורה משום \u0003שלזה\u0004 יש \u0003רשות להלך\u0004 ברשות הרבים, \u0003ו\u0004כן \u0003לזה\u0004 יש \u0003רשות להלך\u0004 בה.","\u0003היה בעל הקורה ראשון ובעל חבית אחרון,\u0004 מהלך אחריו, אם \u0003נשברה חבית בקורה\u0004 — \u0003פטור בעל הקורה,\u0004 שהרי בעל החבית רואה אותו והיה עליו להיזהר."],["\u0003ואם עמד,\u0004 נעצר, \u0003בעל קורה\u0004 ונתקלה החבית בקורה ונשברה — \u0003חייב,\u0004 שהרי בעל החבית אינו יודע שיעמוד, וממשיך בהילוכו ונתקל בו. \u0003ואם אמר\u0004 בעל הקורה \u0003לבעל\u0004 ה\u0003חבית \"עמוד\u0004 כיון שאני עוצר \u0003\"\u0004— הרי הוא \u0003פטור.\u0004","\u0003היה בעל חבית\u0004 מהלך \u0003ראשון ובעל קורה אחרון\u0004 (אחריו), \u0003נשברה חבית בקורה\u0004 — \u0003חייב. ואם עמד בעל חבית\u0004 פתאום — \u0003פטור\u0004 בעל הקורה, \u0003ואם אמר לבעל קורה \"עמוד\"\u0004 ולמרות זאת שבר את החבית בקורה — \u0003חייב. וכן\u0004 הם כל הדינים הללו נוהגים אם היה \u0003זה בא בנרו וזה\u0004 בא \u0003בפשתנו\u0004 וגרם הנר לשריפת הפשתן.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבה בר נתן מרב הונא:\u0004 אדם \u0003המזיק את אשתו ב\u0004תוך כדי \u0003תשמיש המטה, מהו\u0004 דינו לענין חיוב תשלומי נזקיה? וצדדי השאלה: האם נאמר \u0003כיון\u0004 ש\u0003ברשות קעביד\u0004 \u0005[הוא עושה]\u0006 — \u0003פטור, או דילמא\u0004 \u0005[שמא]\u0006 \u0003איבעי ליה לעיוני\u0004 \u0005[היה צריך לו לשים לב]\u0006 ולהיזהר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרבה בר נתן: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 את ההלכה במקרה זה, שהרי שנינו במשנתנו: זה בא בקורתו וזה בא בחביתו — פטור, \u0003שלזה רשות להלך ולזה רשות להלך.\u0004 ומכאן נלמד לשאלה שנשאלה, שכיון שלבעל רשות לתשמיש המטה, אם הזיק את אשתו תוך כדי כך — פטור הוא.","ומוסיפים: ויש החולקים על רב הונא וסבורים שהבעל חייב במקרה זה. והוא ש\u0003אמר רבא:\u0004 חייב הבעל, \u0003קל וחומר\u0004 מדיני רוצח בשוגג, שנאמר בו \"ואשר יבוא את רעהו ביער לחטוב עצים... ונשל הברזל מן העץ ומצא את רעהו ומת\" (דברים יט, ה). \u0003ומה יער שזה לרשותו נכנס וזה לרשותו נכנס,\u0004 שהרי הוא רשות הרבים, \u0003נעשה\u0004 ההורג \u0003כמי שנכנס לרשות חבירו וחייב\u0004 גלות, \u0003זה,\u0004 הבעל, \u0003שלרשות חבירו\u0004 (אשתו) \u0003נכנס, לא כל שכן\u0004 שחייב על נזק שגרם לה?","ומקשים: \u0003אלא\u0004 לשיטת רבא \u0003הא קתני\u0004 \u0005[הלא שנינו]\u0006 \u0003שלזה רשות להלך ולזה רשות להלך\u0004 ואם מזיק פטור, ומשם למד רב הונא שהבעל פטור!","ומשיבים: יש הבדל בין הדברים, \u0003התם תרוייהו כהדדי נינהו\u0004 \u0005[שם שניהם זה כמו זה הם],\u0006 ששניהם מהלכים, ולכן פטור המזיק ההולך ברשות, \u0003הכא איהו קעביד\u0004 \u0005[כאן הוא,\u0006 הבעל, \u0005עושה]\u0006 \u0003מעשה\u0004 בביאה וכיון שכל המעשה שלו הוא — לכן חייב, אף שהיה זה ברשות.","ושואלים: \u0003והיא\u0004 האשה \u0003לא\u0004 נחשבת כעושה מעשה? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לגבי ביאות אסורות \u0003\"ונכרתו הנפשות העשת מקרב עמם\"\u0004 (ויקרא יח, כט), משמע שגם האיש וגם האשה נחשבים כעושים מעשה!","ומשיבים: \u0003הנאה לתרוייהו אית להו\u0004 \u0005[לשניהם יש להם],\u0006 ולכן אף האשה נענשת אם עברה ברצון, שנחשב הדבר כמעשה, אבל לענין נזקים \u0003איהו\u0004 \u0005[הוא\u0006 הגבר\u0005]\u0006 \u0003מעשה הוא דקעביד\u0004 \u0005[שעושה]\u0006 ולכן חייב.","שנינו במשנה: \u0003היה בעל קורה\u0004 מהלך ברשות הרבים \u0003ראשון\u0004 ובעל חבית אחרון ו\u0003כו'. אמר ריש לקיש: שתי פרות\u0004 שהיו \u0003ברשות הרבים, אחת רבוצה\u0004 בדרך \u0003ואחת מהלכת, בעטה מהלכת ברבוצה\u0004 — הרי היא \u0003פטורה\u0004 מלשלם. \u0003בעטה רבוצה במהלכת\u0004 — \u0003חייבת\u0004 לשלם. ומציעים:","\u0003לימא\u0004 \u0003מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו במשנתנו: \u0003היה בעל קורה ראשון ובעל חבית אחרון, נשברה החבית בקורה\u0004 — \u0003פטור, ואם עמד בעל קורה\u0004 — \u0003חייב. והא הכא\u0004 \u0005[והרי כאן]\u0006 אם עמד בעל הקורה הרי זה \u0003כ\u0004פרה \u0003רבוצה\u0004 שבעטה \u0003במהלכת דמי\u0004 \u0005[נחשב],\u0006 שהרי בעל החבית הוא המהלך ובעל הקורה עומד במקומו ברשות הרבים וגורם לו לנזק, \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003חייב.\u0004","על כך תוהים: \u0003ותסברא\u0004 \u0005[וסבור אתה]\u0006 שאפשר לומר כך? \u0003הא סייעי בעיא\u0004 \u0005[הרי לסייע\u0006 לו \u0005רצה],\u0006 \u0003לא מסתייא\u0004 \u0005[די]\u0006 ש\u0003לא מסייעי\u0004 \u0005[מסייע]\u0006 לו מכאן, \u0003אלא מקשה נמי קשיא\u0004 \u0005[קשה היא גם כן],\u0006 כי בדברי ריש לקיש, חייב בעל הפרה הרבוצה, \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום ש\u0003בעטה\u0004 הרבוצה במהלכת, \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 אם \u0003הוזקה\u0004 המהלכת \u0003ממילא,\u0004 שנתקלה ברבוצה וניזוקה — \u0003פטור,\u0004 \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 העוסקת בנזק ש\u0003ממילא\u0004 הוזק בעל החבית, בלא מעשה של בעל קורה, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003חייב!\u0004","ומשיבים: אין מכאן קושיה, \u0003מתניתין דפסקה לאורחא כשלדא\u0004 \u0005[משנתנו\u0006 מדברת \u0005ש\u0006בעצירתו \u0005פסק,\u0006 חסם, בעל הקורה \u0005את הדרך כשלד,\u0006 לרוחב הדרך\u0005]\u0006 ובהכרח נתקל בו בעל החבית, ולכן הוא חייב אף בנזק שממילא. \u0003הכא\u0004 \u0005[כאן]\u0006 בדברי ריש לקיש, מדובר \u0003כגון דרבעה בחד גיסא\u0004 \u0005[שרבצה\u0006 הפרה \u0005בצד אחד]\u0006 של רשות הרבים, ומכיון שכן \u0003איבעי לה לסגויי באידך גיסא\u0004 \u0005[צריכה היתה\u0006 הפרה המהלכת \u0005ללכת בצד האחר\u0006 הפנוי\u0005],\u0006 ולכן אם היתה נתקלת בה בלבד — היתה הפרה הרובצת פטורה. ונמצא שאין מכאן לא ראיה ולא סתירה לדברי ריש לקיש.","\u0003אלא סיפא דמתניתין\u0004 \u0005[סופה של משנתנו]\u0006 \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לריש לקיש, דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003היה בעל חבית\u0004 מהלך \u0003ראשון ובעל קורה אחרון, נשברה חבית בקורה\u0004 — \u0003חייב, ואם עמד בעל חבית\u0004 — \u0003פטור. והא הכא\u0004 \u0005[והרי כאן]\u0006 אם עמד בעל החבית ופגע בה בעל הקורה הרי זה \u0003כ\u0004פרה \u0003מהלכת\u0004 שבעטה \u0003ברבוצה דמי\u0004 \u0005[נחשב]\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003פטור,\u0004 והרי זה סיוע לדברי ריש לקיש.","ודוחים: \u0003מתניתין דכי אורחיה קא מסגי\u0004 \u0005[משנתנו\u0006 פוטרת משום \u0005שכדרכו הוא הולך],\u0006 ובתוך כך פוגע בחבית. \u0003הכא אמרה לה\u0004 \u0005[כאן יכול לומר לו]\u0006 בעל הפרה הרובצת לבעל הפרה המהלכת: \u0003נהי דאית\u0004 \u0005[אמנם יש]\u0006 \u0003לך רשות לסגויי\u0004 \u0005[ללכת]\u0006 \u0003עלי,\u0004 אבל \u0003לבעוטי\u0004 \u0005[לבעוט]\u0006 \u0003בי לית\u0004 \u0005[אין]\u0006 \u0003לך רשותא\u0004 \u0005[רשות].\u0006","\u0003שנים שהיו מהלכין ברשות הרבים,\u0004 או \u0003אחד רץ ואחד מהלך, או שהיו שניהם רצין, והזיקו זה את זה\u0004 — \u0003שניהם פטורין.\u0004","מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003איסי בן יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר: רץ\u0004 ברשות הרבים והזיק — \u0003חייב, מפני שהוא משונה,\u0004 ששינה מדרך בני אדם ברשות הרבים. \u0003ומודה איסי בערב שבת בין השמשות שהוא פטור, מפני שרץ ברשות.\u0004","\u0003אמר ר' יוחנן: הלכה כאיסי בן יהודה.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שאם היה רץ והזיק — חייב? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 ככלל: \u0003הלכה כסתם משנה\u0004 (דברים המופיעים במשנה בלא ייחוס שם תנא מסויים), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אחד רץ ואחד מהלך, או שהיו שניהם רצין\u0004 — \u0003פטורין!\u0004","ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 הפוטרת את הרץ, מדברת \u0003בערב שבת בין השמשות,\u0004 שיש רשות לרוץ.","ומבארים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיקים אנו מסקנה זו להסביר את המשנה במקרה מיוחד זה בלבד? \u0003מדקתני\u0004 \u0005[ממה ששנה\u0006 שם\u0005]:\u0006 \u0003או שהיו שניהם רצין פטורין.\u0004 ונעיין בדבר, \u0003הא תו\u0004 \u0005[זו עוד]\u0006 קטע נוסף זה \u0003למה לי\u0004 לשנותו? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אחד רץ ואחד מהלך\u0004 — \u0003פטור\u0004 הרץ, \u0003שניהם רצין מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שפטור המזיק? \u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אחד רץ ואחד מהלך\u0004 — \u0003פטור. במה דברים אמורים\u0004 — \u0003בערב שבת בין השמשות\u0004 שרץ ברשות, \u0003אבל בחול אחד רץ ואחד מהלך\u0004 — \u0003חייב,\u0004 ואם היו \u0003שניהם רצין\u0004 — \u0003אפילו בחול פטורין.\u0004 ולפי זה מובן מדוע נוסף קטע זה במשנה, שנראה שלפי הבנתה הפשוטה הוא מיותר. ומבררים את ששנינו מקודם.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ומודה איסי\u0004 שהרץ \u0003בערב שבת בין השמשות\u0004 והזיק \u0003שהוא פטור, מפני שרץ ברשות.\u0004 ושואלים: \u0003בערב שבת מאי\u0004 \u0005[מה]\u0006 \u0003ברשות איכא\u0004 \u0005[יש כאן]?\u0006 כלומר, מה הצורך לריצה זו בערב שבת?","ומשיבים: \u0003כ\u0004דברי \u0003ר' חנינא,\u0004 ש\u0003אמר\u0004 \u0003ר' חנינא\u0004 (כך היה נוהג לומר) בערב שבת:"],["\u0003\"בואו ונצא לקראת כלה מלכתא\"\u0004 \u0005[המלכה],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היה אומר: \u0003\"\u0004בואו ונצא \u0003לקראת שבת כלה מלכתא\"\u0004 \u0005[המלכה].\u0006 ו\u0003ר' ינאי\u0004 היה \u0003מתעטף\u0004 מתכסה בטליתו \u0003וקאי\u0004 \u0005[ועומד]\u0006 בערב שבת, \u0003ואמר\u0004 \u0005[ואומר]\u0006 \u0003: \"בואי כלה, בואי כלה\".\u0004 וכיון שכך ראוי לו לאדם למהר ולרוץ לכבוד השבת.","\u0003המבקע\u0004 עצים \u0003ברשות הרבים\u0004 וניתז דבר \u0003והזיק ברשות היחיד\u0004 של אחרים, או שהיה מבקע עצים \u0003ברשות היחיד\u0004 שלו \u0003והזיק ברשות הרבים,\u0004 וכן אם היה מבקע \u0003ברשות היחיד\u0004 שלו \u0003והזיק ברשות היחיד\u0004 של \u0003אחר\u0004 — \u0003חייב\u0004 בכל אלה.","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 להביא את כל אותם המקרים במשנה שעל כולם הוא חייב, כי בכל אחד מהם יש חידוש. \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק \u0003המבקע ברשות היחיד והזיק ברשות הרבים,\u0004 היינו אומרים שחייב \u0003משום דשכיחי\u0004 \u0005[שמצויים]\u0006 \u0003רבים\u0004 ברשות הרבים, והיה לו להיזהר שלא יפגע בהם, למרות שהוא מבקע ברשות היחיד, \u0003אבל\u0004 אם נתזה \u0003מרשות הרבים לרשות היחיד\u0004 ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רבים\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתחייב, על כן צריך היה לשנות גם הלכה זו.","ולהיפך, \u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 רק \u0003מרשות הרבים לרשות היחיד\u0004 שחייב, הייתי סבור שדווקא שם הוא חייב \u0003משום דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003שלא ברשות עביד\u0004 \u0005[עושה],\u0006 שאין לו רשות לעשות מלאכה זו של בקיעת עצים ברשות הרבים, \u0003אבל\u0004 המבקע עצים \u0003מרשות היחיד לרשות הרבים,\u0004 ש\u0003ברשות עביד\u0004 \u0005[עושה],\u0006 שהרי רשות היחיד שלו היא — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתחייב, על כן הוצרכו שניהם.","\u0003ואי תנא הנך תרתי\u0004 \u0005[ואם היה שונה\u0006 רק את \u0005אלו השנים]\u0006 שחייב בהם, הייתי אומר שיש סיבה לחיובם: \u0003הא\u0004 \u0005[זה]\u0006 — \u0003משום דשכיחי\u0004 \u0005[שמצויים]\u0006 \u0003רבים, והא\u0004 \u0005[וזה]\u0006 — \u0003משום\u0004 שהוא \u0003שלא ברשות\u0004 עושה, \u0003אבל מרשות היחיד לרשות היחיד אחר\u0004 שיש בו שני צדדים לזכותו: ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רבים,\u0004 \u0003ומעיקרא\u0004 \u0005[ומתחילה]\u0006 \u0003ברשות\u0004 עושה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתחייב, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006","הלכה זו להיאמר בכל המקרים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס לחנותו של נגר שלא ברשות\u0004 הנגר, \u0003ונתזה בקעת\u0004 (חתיכה) מאחד העצים \u0003וטפחה\u0004 (הכתה) \u0003על פניו ומת\u0004 — \u0003פטור\u0004 הנגר. \u0003ואם נכנס\u0004 לחנות \u0003ברשות\u0004 — \u0003חייב.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003חייב\u0004 המזיק אם נכנס הניזק ברשות? \u0003אמר ר' יוסי בר חנינא: חייב בארבעה דברים\u0004 (נזק צער ריפוי ושבת) שמשלם אדם שהזיק לחבירו, \u0003ופטור מגלות\u0004 אם נהרג הנכנס,","\u0003לפי שאין דומה\u0004 מקרה זה \u0003ליער\u0004 שהיא הדוגמה הכתובה בתורה לענין חיוב רוצח בשגגה שגולה, \"ואשר יבוא את רעהו ביער לחטוב עצים ונדחה ידו בגרזן לכרות העץ ונשל הברזל מן העץ ומצא את רעהו ומת הוא ינוס אל אחת הערים האלה וחי\" (דברים יט, ה). כי \u0003יער\u0004 — \u0003זה לרשותו נכנס וזה לרשותו נכנס,\u0004 שרשות הרבים הוא, ואילו כאן \u0003זה\u0004 — \u0003לרשות חבירו נכנס,\u0004 ולכן ההורגו אינו חייב גלות.","\u0003אמר רבא:\u0004 להיפך, \u0003קל וחומר\u0004 הוא: \u0003ומה יער\u0004 ש\u0003זה לדעתו נכנס וזה לדעתו נכנס,\u0004 ואין חבירו יודע על כך, ולא נטל רשות ממנו להיכנס, מכל מקום \u0003נעשה כמי שנכנס לדעת חבירו\u0004 — \u0003וגולה\u0004 ההורג בגללו כאילו ידע שחבירו נמצא ביער, \u0003זה\u0004 \u0003שלדעת חבירו\u0004 הנגר \u0003נכנס\u0004 לחנות — \u0003לא כל שכן\u0004 שיגלה אם הרגו?!","\u0003אלא אמר רבא,\u0004 יש לומר באופן אחר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"פטור מגלות\"\u0004 — הכוונה ש\u0003לא סגי ליה\u0004 \u0005[די לו]\u0006 \u0003בגלות,\u0004 \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 של \u0003ר' יוסי בר חנינא\u0004 הפוטרו מגלות, \u0003משום דהוי ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003שוגג קרוב למזיד,\u0004 כי עונש גלות מכפר רק על מי שהרג מתוך שגגה גמורה, ושוגג קרוב למזיד אין לו כפרה על ידי גלות.","ועל כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו: מי שנידון למלקות בבית דין ואמדוהו הרופאים שיכול לקבל מספר מסויים של מלקות ו\u0003הוסיף לו\u0004 המלקה \u0003רצועה\u0004 (מכה) \u0003אחת ומת\u0004 על ידו — \u0003הרי זה גולה על ידו. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003שוגג קרוב למזיד הוא, דאיבעי אסוקי אדעתיה דמייתי אינשי בחדא רצועה\u0004 \u0005[שצריך היה\u0006 המלקה \u0005להעלות על דעתו שמתים אנשים ב\u0006מכת \u0005רצועה אחת,\u0006 יתירה\u0005],\u0006 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003הרי זה גולה! אמר רב שימי מנהרדעא:\u0004 כאן מדובר \u0003דטעי במנינא\u0004 \u0005[שטעה במנין]\u0006 המלקות, שאין זה שוגג קרוב למזיד.","\u0003טפח ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב שימי \u0003בסנדליה\u0004 \u0005[\u0006\u0005בסנדלו]\u0006 בדרך זלזול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו הוא מני\u0004 \u0005[וכי הוא,\u0006 המלקה, \u0005מונה]\u0006 את מנין המלקות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003גדול שבדיינין קורא\u0004 את המקראות שאומרים למוכה בזמן עונשו, \u0003ו\u0004הדיין \u0003השני מונה,\u0004 \u0003והשלישי אומר\u0004 למלקה \u0003\"הכהו\".\u0004 ואם כן לא יתכן שטעה המלקה במנין.","\u0003אלא אמר רב שימי מנהרדעא:\u0004 מדובר באופן ש\u0003טעה דיינא גופיה\u0004 \u0005[הדיין עצמו]\u0006 במנין שהוא מונה, והמלקה שלא שם לב והיכהו מכה נוספת ומת, ובכגון זה הרי עשה זאת בשגגה גמורה, ולכן גולה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003הזורק את האבן לרשות הרבים והרג\u0004 אדם — \u0003הרי זה גולה.\u0004 \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003שוגג קרוב למזיד הוא, דאיבעי ליה אסוקי אדעתיה\u0004 \u0005[שצריך היה להעלות על דעתו]\u0006 ש\u0003ברשות הרבים שכיחי אינשי\u0004 \u0005[מצויים אנשים],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 בכל זאת: \u0003הרי זה גולה!\u0004","\u0003אמר רב שמואל בר יצחק:\u0004 מדובר כאן \u0003בסותר את כותלו\u0004 הפונה לרשות הרבים, שאינו סתם זורק אבנים לרשות הרבים, אלא הורס את הכותל והאבנים נופלות לרשות הרבים, שאין זה קרוב למזיד.","ושואלים: ובכל זאת, \u0003איבעי ליה עיוני\u0004 \u0005[צריך היה לו להסתכל]\u0006 אם אין שם אנשים, ואף זה קרוב למזיד הוא! ומשיבים: מדובר \u0003בסותר בלילה.\u0004","ומקשים: \u0003בלילה נמי איבעי ליה עיוני\u0004 \u0005[גם כן צריך היה לו להסתכל]\u0006 אם אין שם אנשים! ומסבירים בדרך אחרת: מדובר \u0003בסותר את כותלו ביום לאשפה\u0004 שהיא אינה מקום הרבים.","ושואלים: \u0003האי\u0004 \u0005[זאת]\u0006 ה\u0003אשפה היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי דשכיחי\u0004 \u0005[אם\u0006 זה מקום \u0005שמצויים]\u0006 בו \u0003רבים\u0004 — הרי \u0003מזיד הוא,\u0004 כלומר, קרוב למזיד הוא, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רבים\u0004 — אם כן \u0003אנוס הוא,\u0004 שלא היה עליו להעלות על דעתו שיבוא אדם לשם, ואין זה בגדר שוגג כלל!","\u0003אמר רב פפא: לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא באשפה העשויה להפנות בלילה,\u0004 שבמקום אשפה זה עשויים אנשים להיפנות לצורכיהם בשעות הלילה, \u0003ואינה עשויה להפנות ביום,\u0004 שכיון שהמקום קרוב לרשות הרבים, לכן אין נוהגים לעשות כן ביום, \u0003ואיכא דמיקרי ויתיב\u0004 \u0005[ו\u0006אולם \u0005יש שמזדמן ויושב]\u0006 לעשות צרכיו שם אפילו ביום. ומעתה, הסותר ביום את כותלו למקום זה \u0003מזיד לא הוי\u0004 \u0005[איננו]\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אינה עשויה להפנות ביום,\u0004 ומצד שני \u0003אנוס נמי לא הוי\u0004 \u0005[גם כן איננו]\u0006 — \u0003דהא איכא דמיקרי ויתיב\u0004 \u0005[שהרי יש שמזדמן ויושב]\u0006 שם אדם, ולכן שוגג הוא וחייב גלות.","כל זה היה סביב הבנה אחת בדברי ר' יוסי בר' חנינא, ואילו \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא מתני לה ארישא\u0004 \u0005[היה שונה\u0006 את ההלכה ה\u0005זו\u0006 שאמר ר' יוסי בר' חנינא \u0005על תחילתה\u0006 של ברייתא שהבאנו\u0005]:\u0006 \u0003הנכנס לחנותו של נגר שלא ברשות, ונתזה לו בקעת וטפחה לו על פניו ומת\u0004 — הרי זה \u0003פטור.\u0004 ועל כך \u0003אמר ר' יוסי בר חנינא: חייב בארבעה דברים, ופטור\u0004 משמעו רק פטור \u0003מגלות.\u0004","ומבארים את היחס בין שתי הנוסחות, \u0003מאן דמתני לה אסיפא\u0004 \u0005[מי ששונה אותה\u0006 את ההלכה הזו \u0005על סופה\u0006 של הברייתא\u0005]\u0006 במי שנכנס ברשות, \u0003כל שכן\u0004 שהוא סבור שכן הדין \u0003ארישא\u0004 \u0005[בתחילתה]\u0006 אם נכנס שלא ברשות, שפטור הנגר מגלות אם הרגו. \u0003ומאן דמתני לה ארישא\u0004 \u0005[ומי ששונה אותה על ההתחלה],\u0006 לדעתו \u0003אבל אסיפא\u0004 \u0005[על הסוף]\u0006 \u0003כיון\u0004 ש\u0003ברשות\u0004 נכנס הניזק — \u0003חייב\u0004 הנגר \u0003גלות.\u0004","ושואלים לעצם ההלכה הזו: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003חייב גלות\u0004 גם אם נכנס ברשות? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לחנותו של נפח ונתזה ניצוצות וטפחה לו על פניו ומת\u0004 — \u0003פטור, ואפילו נכנס ברשות!\u0004","ומשיבים: \u0003הכא\u0004 \u0005[כאן],\u0006 בברייתא זו, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 — \u0003בשוליא דנפחי\u0004 \u0005[בעוזרו של הנפח]\u0006 הנכנס לחנותו. ותוהים: וכי \u0003שוליא דנפחי למקטלא קאי\u0004 \u0005[עוזרו של הנפח למיתה\u0006 הוא \u0005עומד]?\u0006 וכי מותר להורגו? ומשיבים: מדובר כאן \u0003כשרבו מסרהב\u0004 (מפציר) \u0003בו לצאת, ואינו יוצא.\u0004","ותוהים שוב: \u0003ומשום\u0004 ש\u0003רבו מסרהב בו לצאת למיקטליה קאי\u0004 \u0005[להורגו\u0006 הוא \u0005עומד]?\u0006 ימתין הנפח עד שיצא! ומשיבים: \u0003כסבור\u0004 הוא הנפח ש\u0003יצא\u0004 והתברר שלא יצא. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 במקרה כזה כשמפציר בו לצאת וסבור שיצא, מדוע מדובר דווקא בשוליה? אדם \u0003אחר נמי\u0004 \u0005[גם כן]\u0006 יהיה פטור מגלות עליו!"],["ומשיבים: \u0003אחר\u0004 — \u0003לית ליה אימתא דרביה\u0004 \u0005[אין לו אימת רבו\u0006 הנפח\u0005]\u0006 עליו, ולכן גם אם מפציר בו לצאת צריך הנפח לבדוק אם אמנם יצא, ואם לא עשה כן — חייב גלות, \u0003האי\u0004 \u0005[זה],\u0006 השוליה — \u0003אית ליה אימתא דרביה\u0004 \u0005[יש לו אימת רבו]\u0006 עליו, ולכן יכול הנפח להניח שאם ציוה עליו לצאת בוודאי יצא. ואם לא יצא ומת מהניצוצות — אינו חייב גלות, שאנוס הוא.","\u0003רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא מתני לה\u0004 \u0005[\u0006היה \u0005שונה אותה],\u0006 את הלכתו של ר' יוסי בר חנינא, \u0003אהא\u0004 \u0005[על\u0006 ברייתא \u0005זו]:\u0006 נאמר בפרשת הרוצח בשגגה \"ונשל הברזל מן העץ \u0003ומצא\u0004 את רעהו ומת\" (דברים יט, ה) — \u0003פרט לממציא את עצמו,\u0004 שההורגו בשוגג פטור מגלות. ו\u0003מכאן אמר ר' אליעזר בן יעקב: מי שיצתה אבן מתחת ידו, והוציא הלה\u0004 (הנפגע) \u0003את ראשו וקיבלה\u0004 (נפגע בה) ומת — \u0003פטור\u0004 הזורק מגלות. \u0003אמר ר' יוסי בר חנינא: פטור מגלות\u0004 אם הרגו, \u0003ו\u0004אולם \u0003חייב בארבעה דברים\u0004 של נזיקין אם לא הרגו.","ומעירים: \u0003מאן דמתני לה אהא\u0004 \u0005[מי ששונה אותה,\u0006 את ההלכה של ר' יוסי, \u0005על זו]\u0006 — \u0003כל שכן\u0004 ששונה \u0003אקמייתא\u0004 \u0005[על הראשונה]\u0006 במי שנכנס לחנותו של נגר שחייב בנזיקין, \u0003ומאן דמתני לה אקמייתא\u0004 \u0005[ומי ששונה אותה על הראשונה],\u0006 \u0003אבל אהא\u0004 \u0005[על זו]\u0006 \u0003פטור לגמרי,\u0004 משום שאפשר להגיד שזה אנוס לגמרי הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פועלים שבאו לתבוע שכרן מבעל הבית\u0004 ונכנסו לשם כך לחצירו, \u0003ונגחן\u0004 שם \u0003שורו של בעל הבית, ו\u0004כן אם \u0003נשכן כלבו של בעל הבית, ומת\u0004 הפועל — הרי בעל הבית \u0003פטור. אחרים אומרים: רשאין פועלים לתבוע שכרן מבעל הבית,\u0004 כלומר, ברשות נכנסו ואחריות נזקיהם על בעל הבית.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר כאן]?\u0006 \u0003אי דשכיח במתא\u0004 \u0005[אם שמצוי\u0006 בעל הבית \u0005בעיר]\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003אחרים\u0004 שחייב? שוודאי יכולים הפועלים לפגוש אותו בעיר ולתבוע שכרם שם, ואינם צריכים לשם כך להיכנס לחצירו! \u0003אי דשכיח\u0004 \u0005[אם שמצוי]\u0006 בעל הבית רק \u0003בבית\u0004 דווקא, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שפטור? הרי ברור שהם רשאים לתבוע את שכרם!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא \u0003בגברא דשכיח ולא שכיח\u0004 \u0005[באדם שמצוי ואיננו מצוי\u0006 תמיד בבית\u0005]\u0006 \u0003וקרי אבבא\u0004 \u0005[וקראו\u0006 לו הפועלים \u0005על השער]\u0006 שרצונם להיכנס, \u0003ואמר להו\u0004 \u0005[להם]\u0006 בעל הבית: \u0003\"אין\"\u0004 \u0005[כן].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 אחרים, \u0005סבור]\u0006 שמה שאומר \u0003\"אין\"\u0004 \u0005[כן]\u0006 — \u0003\"עול תא\" משמע\u0004 \u0005[\"היכנס\u0006 ו\u0005בוא\" משמעו]\u0006 ואם כן נתן להם רשות להיכנס ולכן חייב בנזקיהם. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003\"אין\"\u0004 \u0005[כן]\u0006 — \u0003\"קום אדוכתך\" משמע\u0004 \u0005[\"עמוד על מקומך\" משמעו]\u0006 שאני יוצא אליך, ואין להם רשות להיכנס, ומשום כך פטור בעל הבית.","ומעירים: \u0003תניא כמאן דאמר \"אין\" \"קום אדוכתך\" משמע\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006דעת \u0005מי\u0006 \u0005שאומר\u0006 ש\u0005\"כן\" \"עמוד על מקומך\" משמעו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פועל שנכנס לתבוע\u0004 את \u0003שכרו מבעל הבית ונגחו שורו של בעל הבית, או נשכו כלבו\u0004 — \u0003פטור, אף על פי שנכנס ברשות.\u0004 ויש לתהות: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור\u0004 אם נכנס ברשות? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003דקרי אבבא\u0004 \u0005[שקרא על השער]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 בעל הבית \u0003\"אין\"\u0004 \u0005[\"כן\"],\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003\"אין\"\u0004 \u0005[\"כן\"]\u0006 — \u0003\"קום אדוכתך\" משמע\u0004 \u0005[\"עמוד על מקומך\" משמע\u0006 ו\u0005].\u0006","\u0003שני שוורין תמין שחבלו זה את זה\u0004 — \u0003משלמין במותר\u0004 (בהפרש) \u0003חצי נזק.\u0004 כלומר, אומדים את הנזקים שהזיקו שניהם, ואם נמצא שניזוק אחד יותר מחבירו, הרי מי שהזיק שורו יותר משלם לניזק מחצית מן הנזק היתר. אם היו \u0003שניהן\u0004 (שני השוורים) \u0003מועדין\u0004 והזיקו זה את זה — \u0003משלמין במותר נזק שלם.\u0004","היה \u0003אחד\u0004 השוורים \u0003תם ואחד מועד,\u0004 אם הזיק יותר ה\u0003מועד בתם\u0004 מאשר התם במועד — \u0003משלם במותר נזק שלם,\u0004 ואם \u0003תם\u0004 הזיק \u0003במועד\u0004 יותר מאשר המועד בתם — \u0003משלם במותר חצי נזק.\u0004","\u0003וכן שני אנשים שחבלו זה בזה\u0004 — \u0003משלמין במותר נזק שלם,\u0004 שהרי אדם מועד לעולם.","\u0003אדם\u0004 שחבל \u0003ב\u0004שור \u0003מועד ו\u0004באותה שעה חבל השור ה\u0003מועד ב\u0004אותו \u0003אדם\u0004 — \u0003משלם במותר נזק שלם.\u0004 הזיקו זה את זה \u0003אדם בתם ותם באדם,\u0004 הרי \u0003אדם בתם\u0004 — \u0003משלם במותר נזק שלם, תם באדם\u0004 — \u0003משלם במותר חצי נזק. ר' עקיבא אומר: אף תם\u0004 \u0003שחבל באדם\u0004 — \u0003משלם במותר נזק שלם,\u0004 שלדעתו כאשר שור מזיק אדם אין הבדל בין תם למועד.","הוזכרה במשנתנו מחלוקת ר' עקיבא וחכמים בדין שור שנגח אדם, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"\u0004או בן יגח או בת יגח \u0003כמשפט הזה יעשה לו\"\u0004 (שמות כא, לא) כוונתו: \u0003כמשפט שור בשור\u0004 — \u0003כך משפט שור\u0004 הפוגע \u0003באדם. מה שור\u0004 שפגע \u0003בשור\u0004 — \u0003תם משלם חצי נזק ומועד\u0004 משלם \u0003נזק שלם, אף שור\u0004 שפגע \u0003באדם\u0004 — \u0003תם משלם חצי נזק, ומועד נזק שלם.\u0004","\u0003ר' עקיבא אומר: \"כמשפט הזה\"\u0004 — \u0003כתחתון,\u0004 כמאוחר יותר בפרשה הקודמת, דהיינו שור מועד, שהוזכר סמוך לפסוק זה, \u0003ולא כעליון\u0004 (הנזכר למעלה, מקודם) דהיינו שור תם.","\u0003יכול משלם מן העלייה,\u0004 שיהא דינו לכל דבר כשור מועד לגבות את הנזק מנכסי המזיק כולם — \u0003תלמוד לומר: \"יעשה לו\",\u0004 כוונתו: \u0003מגופו משלם, ואינו משלם מן העלייה,\u0004 שזהו ההבדל בין שור תם לשור מועד שנגח אדם, שאין הבדל ביניהם בשיעור הנזקים אלא לענין דרך גבייתם.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מחלקים בין נוגח אדם לנוגח בהמה לענין חיובי שור תם ושור מועד, המלה \u0003\"\u0004ה\u0003זה\"\u0004 שבאה לצמצם את ההשוואה \u0003למה לי?\u0004 ומשיבים: \u0003לפוטרו מארבעה דברים,\u0004 שאף שמשלם בעל השור עבור הנזק, אינו משלם שאר דברים שמשלם אדם שחבל באדם.","ושואלים: \u0003ור' עקיבא לפוטרו מארבעה דברים מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 מהכתוב \"ו \u0003איש כי יתן מום בעמיתו\u0004 כאשר עשה כן יעשה לו\" (ויקרא כד, יט) ומדייק: \u0003איש בעמיתו\u0004 חייב בתשלומי ארבעה דברים \u0003ולא שור בעמיתו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מדוע אף הם אינם למדים משם? ומסבירים: \u0003אי מההיא\u0004 \u0005[אם מ\u0006הכתוב \u0005ההוא]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003צער לחודיה\u0004 \u0005[בלבד]\u0006 אין הוא צריך לשלם לו, \u0003אבל ריפוי ושבת אימא\u0004 \u0005[אמור]\u0006 שצריך \u0003ליתן ליה\u0004 \u0005[לו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק הנוסף שאינו משלם דבר מלבד הנזק עצמו.","\u0003שור\u0004 תם \u0003שוה מנה\u0004 (מאה דינרים) \u0003שנגח שור שוה מאתים\u0004 דינרים, \u0003ואין הנבילה\u0004 של השור המת \u0003יפה\u0004 (שווה) \u0003כלום\u0004 — \u0003נוטל\u0004 הניזק \u0003את השור\u0004 המזיק כולו, שהרי הוא שווה חצי הנזק.","מעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 לאחר שהזיק \u0003יושם\u0004 (יוערך) \u0003השור בבית דין,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: הוחלט השור.\u0004 כלומר, אין צורך עוד בהליכים משפטיים אם הכל מסכימים לגבי שיעור הנזק, ומיד הוחלט השור לניזק.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005חלוקים\u0006 הם\u0005]?\u0006 \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 כי הניזק \u0003בעל חוב\u0004 של המזיק \u0003הוא, וזוזי\u0004 \u0005[וכסף]\u0006 \u0003הוא דמסיק ליה\u0004 \u0005[שנושה בו],\u0006 אבל אין לו בעלות בגוף השור המזיק. \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003שותפי נינהו\u0004 \u0005[שותפים הם],\u0006 שמשעה שניזק על ידי שור תם נעשה הניזק שותף למזיק בגופו של השור המזיק.","ומעירים: \u0003וקמיפלגי בהאי קרא\u0004 \u0005[וחלוקים\u0006 הם \u0005ב\u0006פירושו של \u0005פסוק זה]:\u0006 \u0003\"ומכרו את השור החי וחצו את כספו\"\u0004 (שמות כא, לה); \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003לבי דינא קמזהר רחמנא\u0004 \u0005[את בית הדין מזהירה התורה],\u0006 כלומר, ציווי זה נאמר לבית הדין כיצד יעריכו את הנזקים, \u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003לניזק ומזיק מזהר להו רחמנא\u0004 \u0005[מזהירה אותם התורה],\u0006 ואין כאן ענין לבית הדין.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]\u0006 אם שותפים הם אם לא? ומשיבים: במקרה ש\u0003הקדישו ניזק\u0004 את השור \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלדעת ר' ישמעאל כל עוד לא נמסר השור לניזק על ידי בית הדין הרי הוא שייך למזיק, ולדעת ר' עקיבא משעת הנזק הריהו שייך כבר לניזק, ולכן יכול להקדישו.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם \u0003מכרו\u0004 ה\u0003מזיק\u0004 לאחר, \u0003ל\u0004דעת \u0003ר' ישמעאל מהו\u0004 הדין? האם נאמר \u0003כיון\u0004 ש\u0003אמר ר' ישמעאל בעל חוב הוא\u0004 הניזק, \u0003וזוזי\u0004 \u0005[וכסף]\u0006 \u0003הוא דמסיק ליה\u0004 \u0005[שנושה בו],\u0006 אם כן כיון שמכרו — \u0003מכור, או דלמא\u0004 \u0005[שמא\u0006 נאמר\u0005]:\u0006"],["כי \u0003כיון דמשעבד ליה\u0004 \u0005[ש\u0006הוא \u0005משועבד לו]\u0006 \u0003לניזק\u0004 לשלם ממנו, אם אין בידו כסף — \u0003לאו כל כמיניה\u0004 \u0005[אין\u0006 זה \u0005בכחו\u0006 למוכרו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אינו מכור.\u0004","והקשה לו רבא על כך: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מכרו\u0004 — \u0003מכור!\u0004 השיב לו: ובכל זאת \u0003חוזר וגובהו\u0004 הניזק מן הלוקח. ושוב שואלים: \u0003וכי מאחר שחוזר וגובהו\u0004 מן הלוקח, \u0003למה,\u0004 לאיזה ענין, נחשב הוא \u0003מכור?\u0004 הרי נמצא שלא היתה זו מכירה כלל! ומשיבים: \u0003לרידיא\u0004 \u0005[ל\u0006ענין \u0005חרישה].\u0006 כלומר, שמה שהשתמש הקונה בשור למלאכתו, כגון לחרישה, עד שלקחו ממנו הניזק בחזרה — כדין עשה, ואין הניזק יכול לגבות ממנו את דמי החרישה בשורו.","ושואלים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005תלמד מכאן]\u0006 שמי ש\u0003לוה ומוכר\u0004 לאחר מכן \u0003מטלטלין\u0004 — \u0003בית דין גובין לו\u0004 למלווה את חובו \u0003מהם\u0004 מן הקונה? שהרי לדברי ר' ישמעאל יש על השור רק שעבוד מכוח החוב לניזק. ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בשור המזיק \u0003דכמאן\u0004 \u0005[שכמי]\u0006 ש\u0003עשאו אפותיקי\u0004 (משכון המיוחד לגבייה) \u0003דמי\u0004 \u0005[נחשב],\u0006 שהרי התורה אמרה שגובים מן השור, ואם כן נעשה השור משועבד במיוחד לגביית חוב זה, מה שאין כן בשאר מיטלטלים של הלווה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 אם \u0003עשה\u0004 את \u0003עבדו אפותיקי ומכרו\u0004 — \u0003בעל חוב גובה הימנו\u0004 (ממנו), מן הקונה, ואולם אם עשה את \u0003שורו אפותיקי ומכרו\u0004 — \u0003אין בעל חוב גובה הימנו\u0004 \u0005[ממנו]\u0006. ואם כן הרי זה בניגוד לדברים שאמרנו, ששור המזיק, שאף הוא נעשה אפותיקי — הניזק חוזר וגובה ממנו!","ומשיבים: מדברי רבא עצמם יש להסביר דבר זה, שכן \u0003עבד מאי טעמא\u0004 \u0005[מה טעם]\u0006 גובים אותו מהקונה אם עשאוהו אפותיקי — \u0003משום דאית ליה קלא\u0004 \u0005[שיש לו קול]\u0006 לענין זה, שעשיית עבד אפותיקי אינה מצויה והדבר מתפרסם ברבים, ועל דעת זו קנה אותו. \u0003האי נמי\u0004 \u0005[\u0006שור \u0005זה גם כן]\u0006 \u0003כיון\u0004 ש\u0003נגח\u0004 — \u0003קלא אית ליה, דתורא נגחנא קרו ליה\u0004 \u0005[קול יש לו, ששור נגחן קוראים אותו],\u0006 ויודע הקונה שיש עליו שעבוד, ומשום כך חוזר הניזק וגובה ממנו.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו\u0004 ברייתא זו: שור המזיק, אם \u0003מכרו\u0004 — \u0003אין\u0004 הוא \u0003מכור,\u0004 ואולם אם \u0003הקדישו\u0004 — \u0003מוקדש.\u0004","ושואלים: \u0003מכרו מאן\u0004 \u0005[מי],\u0006 הניזק או המזיק? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמכרו ה\u0003מזיק,\u0004 אם כן זה ששנינו \u0003\"מכרו\u0004 — \u0003אין\u0004 הוא \u0003מכור\", מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר הוחלט השור\u0004 לניזק, \u0003ו\u0004אולם בהמשך, כששנינו \u0003\"הקדישו מוקדש\" — אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003ר' ישמעאל,\u0004 ש\u0003אמר:\u0004 \u0003יושם השור בבית דין!\u0004","\u0003אלא\u0004 תאמר שמכרו \u0003ניזק.\u0004 ומעתה, מה ששנינו \u0003\"מכרו\u0004 — \u0003אין מכור\", מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' ישמעאל\u0004 היא, שהשור אינו שלו כלל, ואולם בהמשך, כששנינו \u0003\"הקדישו\u0004 — \u0003מוקדש\", אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003ר' עקיבא.\u0004 ואם כן ברייתא זאת אינה כאף אחת מן השיטות!","ומשיבים: \u0003לעולם\u0004 מדובר שמכרו והקדישו ה\u0003מזיק, ודברי הכל. מכרו אינו מכור,\u0004 ו\u0003אפילו ל\u0004שיטת \u0003ר' ישמעאל, דהא משעבדא ליה\u0004 \u0005[שהרי משועבד לו\u0006 השור\u0005]\u0006 \u0003לניזק\u0004 ואינו רשאי למכרו.","ואולם אם \u0003הקדישו מוקדש —\u0004 \u0003אפילו ל\u0004שיטת \u0003ר' עקיבא,\u0004 ולא כהקדש גמור, אלא \u0003משום\u0004 טעמו של \u0003ר' אבהו.\u0004 ש\u0003אמר ר' אבהו\u0004 שאם מקדיש אדם דבר שיש עליו שעבוד, למרות שאינו יכול להקדישו, מכל מקום עליו לפדותו, \u0003גזירה שמא יאמרו\u0004 האנשים הרואים ש\u0003הקדש יוצא בלא פדיון,\u0004 והם אינם יודעים שלא חל ההקדש. ולכן, אף שהקדש השור לא חל, מכל מקום פודים אותו פדיון כל שהוא, כדי שלא יבואו לזלזל בהקדש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שור תם שהזיק,\u0004 אם \u0003עד שלא עמד בדין מכרו\u0004 המזיק — הריהו \u0003מכור,\u0004 \u0003הקדישו\u0004 — הריהו \u0003מוקדש.\u0004 אם \u0003שחטו ו\u0004 כן אם \u0003נתנו במתנה —\u0004 \u0003מה שעשה עשוי. משעמד בדין\u0004 והתחייב לשלם לניזק, \u0003מכרו —\u0004 \u0003אינו מכור, הקדישו —\u0004 \u0003אינו מוקדש, שחטו\u0004 או \u0003נתנו במתנה —\u0004 \u0003לא עשה ולא כלום.\u0004","\u0003קדמו בעלי חובות\u0004 של הבעלים \u0003והגביהו\u0004 (גבו) את השור כפרעון, \u0003בין חב\u0004 (התחייב) בחוב זה \u0003עד שלא הזיק,\u0004 כלומר, קודם שהזיק, \u0003בין הזיק עד שלא חב —\u0004 \u0003לא עשו ולא כלום, לפי שאין משתלם\u0004 הניזק \u0003אלא מגופו\u0004 של השור התם, ולכן הוא משועבד לו.","ואילו \u0003מועד שהזיק, בין שעמד בדין בין שלא עמד בדין,\u0004 אם \u0003מכרו —\u0004 \u0003מכור,\u0004 אם \u0003הקדישו —\u0004 \u0003מוקדש,\u0004 אם \u0003שחטו ו\u0004כן אם \u0003נתנו במתנה —\u0004 \u0003מה שעשה עשוי. קדמו בעלי חובות והגביהו\u0004 אותו בחובם, \u0003בין חב עד שלא הזיק בין הזיק עד שלא חב —\u0004 \u0003מה שעשה עשוי, לפי שאין משתלם\u0004 הנזק \u0003אלא מן העלייה,\u0004 מנכסי בעל השור כולם, ולא מגופו של השור. ומשום כך אין הבדל מה ייעשה בשור זה עצמו.","את הברייתא הזו מבררים. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 שור תם שהזיק \u0003מכרו מכור,\u0004 יש לפרש כמו שאמרנו — \u0003לרדיא\u0004 \u0005[לחרישה],\u0006 שעד שהניזק יגבה אותו יכול בינתיים הקונה לחרוש בו.","\u0003הקדישו מוקדש —\u0004 לא שקדוש ממש, אלא \u0003משום\u0004 מה ש\u0003אמר ר' אבהו\u0004 שאין מפקיעים לגמרי מן ההקדש, אלא נותן בפדיונו דבר מועט ולוקחו.","ועוד שנינו בברייתא: \u0003שחטו\u0004 או \u0003נתנו במתנה\u0004 \u0003—\u0004 \u0003מה שעשה עשוי.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו \u0003נתנו במתנה\u0004 — \u0003מה שעשה עשוי\u0004 הכוונה היא \u0003לרדיא\u0004 \u0005[לחרישה],\u0006 שמקבל המתנה יכול לחרוש בו, \u0003אלא שחטו —\u0004 מדוע הפסיד הניזק? \u0003ליתי ולשתלם מבשריה\u0004 \u0005[שיבוא ויקבל את התשלום מבשרו]\u0006 של השור השחוט,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \"ומכרו את השור החי\" (שמות כא, לה) \u0003\"חי\", אין לי אלא חי, שחטו מנין\u0004 שגם כן כך הוא הדין? \u0003תלמוד לומר: \"ומכרו את השור\" —\u0004 כוונתו \u0003מכל מקום\u0004 ובכל מצב שהוא!","\u0003אמר רב שיזבי: לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לפחת שחיטה,\u0004 כלומר, הפחת שפחת ערכו מחמת השחיטה, שאם פחת ערכו ושוב אינו מכסה את דמי הנזק, מכל מקום אין הניזק יכול לגבות יותר מאשר השור כפי שהוא לפניו.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: זאת אומרת,\u0004 מכאן יש ללמוד כי \u0003המזיק שעבודו של חבירו,\u0004 כלומר, אם אדם מזיק נכס המשועבד לחבירו — הרי זה \u0003פטור\u0004 מלפצותו על כך, שהרי לבעל השעבוד יש רק זכות על אותו הנכס, ואולם אינו שלו ממש.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא, שהרי זהו ששנינו בברייתא! ומשיבים: יש מקום לחלק, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 דווקא \u0003התם\u0004 \u0005[שם],\u0006 בשוחט את השור, כך הוא הדין, משום \u0003הוא דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המזיק: \u0003לא חסרתיך\u0004 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 : \u0003זיקא בעלמא\u0004 \u0005[רוח בלבד]\u0006 \u0003הוא דשקלי מינך\u0004 \u0005[שלקחתי ממך],\u0006 שהרי לא לקח דבר מגוף השור, אלא שנטל ממנו את חייו, שהוא כעין \"היזק שאינו ניכר\" ולכן הוא פטור. \u0003אבל בעלמא\u0004 \u0005[בכלל],\u0006 אם מזיק נזק ניכר בשעבוד — \u0003ליחייב\u0004 \u0005[יהא חייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב הונא בריה דרב יהושע שאין הדבר כן, ובכל מקרה המזיק שעבוד חבירו פטור.","ושואלים: \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003רבה אמרה\u0004 כבר, ש\u0003אמר רבה: השורף שטרותיו של חבירו\u0004 שיש בהם התחייבויות של אחרים לחבירו — הריהו \u0003פטור,\u0004 אף שעתה חבירו אינו יכול לגבות עוד על ידם נכסים משועבדים!","ומשיבים: יש בכל זאת חידוש בדברי רב הונא בריה דרב יהושע, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 פטור משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המזיק לבעל השטרות: \u0003ניירא בעלמא קלאי מינך\u0004 \u0005[נייר בלבד שרפתי לך]\u0006 ואני מוכן לשלם עבור הנייר, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 \u0003ש\u0004\u0003חפר בה,\u0004 בשדה משועבדת, \u0003בורות שיחין\u0004 (חפירות) \u0003ומערות,\u0004 שהזיק לו באופן ממשי — \u0003ליחייב\u0004 \u0005[יהא חייב]\u0006 על כך, וישלם לבעל השעבוד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בזה פטור, \u0003דהא הכא\u0004 \u0005[שהרי כאן],\u0006 בשוחט את השור, הריהו \u0003כמאן דחפר\u0004 \u0005[כמי שחופר]\u0006 \u0003בה\u0004 בקרקע \u0003בורות שיחין ומערות דמי,\u0004 שהרי הזיקו נזק ממשי, \u0003וקאמר\u0004 \u0005[ואומר]\u0006 על כך התנא: \u0003מה שעשה עשוי.\u0004","ועוד בפירושה של הברייתא, נאמר שם: \u0003קדמו בעלי חובות והגביהו, בין חב עד שלא הזיק בין הזיק עד שלא חב —\u0004 \u0003לא עשה ולא כלום, לפי שאין\u0004 התם \u0003משלם אלא מגופו.\u0004","ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה ש\u0003הזיק עד שלא חב\u0004 מובן הדבר, כי \u0003ה\u0004\u0003ניזקין קדמו\u0004 ולכן יש להם שעבוד קודם על השור. \u0003אבל\u0004 אם היה זה במקרה ש\u0003חב\u0004 המזיק \u0003עד שלא הזיק\u0004 שורו, הלא \u0003בעל חוב קדים\u0004 \u0005[מוקדם]\u0006 לניזקין, ומדוע לא תהיה לו זכות קדימה בשור?"],["\u0003ו\u0004יתר על כך, \u0003אפילו הזיק עד שלא חב,\u0004 מכל מקום הלא \u0003בעל חוב קדים\u0004 \u0005[קדם]\u0006 ותפס את המגיע לו, האם \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בעל חוב מאוחר שקדם וגבה\u0004 את חובו — \u0003מה שגבה לא גבה,\u0004 ויינתן לבעל החוב הקודם?","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך: מה שגבה\u0004 בעל החוב המאוחר — \u0003גבה, ושאני התם\u0004 \u0005[ושונה שם]\u0006 במקרה שתפס בעל חוב שור תם שהזיק, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הניזק לבעל החוב שתפס את השור בחובו: \u0003אילו גבך הוה\u0004 \u0005[אצלך היה]\u0006 השור, וכי \u0003לא מינך הוה גבי ליה\u0004 \u0005[ממך הייתי גובה אותו]?\u0006 \u0003דהאי תורא דאזקן, מיניה משתלמנא\u0004 \u0005[שה\u0006רי \u0005אותו שור שהזיקני, ממנו\u0006 עצמו \u0005אני מקבל את התשלום],\u0006 ולכן אין בעל החוב, ואף אם חובו קדם להיזק, רשאי לקחת את השור, שהרי בין כה וכה גובה הניזק משור זה עצמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שור\u0004 תם \u0003שוה מאתים שנגח שור\u0004 אחר \u0003שוה מאתים, וחבל בו\u0004 בניזק \u0003ב\u0004ערך של \u0003חמשים זוז, ושבח\u0004 (והשביח) אחר כך השור הניזק \u0003ועמד על\u0004 שווי של \u0003ארבע מאות זוז,\u0004 ואף באופן כזה \u0003שאלמלא\u0004 (שאם) \u0003(לא)\u0004 \u0003הזיקו היה עומד\u0004 עכשיו \u0003על שמנה מאות זוז\u0004 — מכל מקום \u0003נותן\u0004 המזיק עשרים וחמישה זוז שהוא מחצית הנזק \u0003כ\u0004פי שהיה ב\u0003שעת הנזק.\u0004","אבל אם \u0003כחש\u0004 השור הניזק, ומחירו עכשיו פחות מבשעת נגיחה — הרי הנזק מחושב \u0003כ\u0004פי ערכו עכשיו, ב\u0003שעת העמדה בדין,\u0004 כמה היה ערכו קודם הנגיחה, וכמה הוא שווה עכשיו.","ואם \u0003שבח\u0004 השור ה\u0003מזיק\u0004 שאף בו חולקים בעלי השוורים — \u0003נותן לו\u0004 \u0003כ\u0004שוויו ב\u0003שעת הנזק.\u0004 אבל אם \u0003כחש\u0004 השור המזיק — נותן \u0003כשעת העמדה בדין\u0004 ולא כשעת הנזק. ומבררים את הדברים.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שבח\u0004 ה\u0003מזיק\u0004 — \u0003נותן\u0004 לו \u0003כשעת הנזק.\u0004 ושואלים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 הלכה זו — כשיטת \u0003ר' ישמעאל היא,\u0004 ש\u0003אמר: בעל חוב הוא\u0004 הניזק, \u0003וזוזי הוא דמסיק ליה\u0004 \u0005[וכסף הוא שחייב לו]\u0006 המזיק, אבל אין לו קנין ושותפות בשור המזיק.","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: אם \u0003כחש\u0004 המזיק — נידון \u0003כשעת העמדה בדין,\u0004 אם כן \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: שותפי נינהו\u0004 \u0005[שותפים הם]\u0006 הניזק והמזיק, שיש לניזק זכות בגוף השור. ואם כן \u0003רישא\u0004 \u0005[תחילתה\u0006 של ברייתא זו\u0005]\u0006 כשיטת \u0003ר' ישמעאל וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' עקיבא?\u0004","ודוחים: \u0003לא,\u0004 כל הברייתא \u0003כולה\u0004 כשיטת \u0003ר' עקיבא היא\u0004 ששותפים הם הניזק והמזיק, \u0003והכא\u0004 \u0005[וכאן]\u0006 במקרה ששבח המזיק, שנותן כשעת הנזק, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 — \u0003כ\u0004שהשביח השור משום \u0003שפיטמו\u0004 בעליו, ולא שבח מחמת עצמו, ובזה אין חלק לניזק, אף שלענין תשלומי הנזק הוא שותף בו.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר כאן \u0003כשפיטמו,\u0004 \u0003אימא רישא\u0004 \u0005[אמור\u0006 את \u0005ראשה]\u0006 של הברייתא בשור הניזק: \u0003שבח ועמד על ארבע מאות זוז\u0004 — \u0003נותן לו כשעת הנזק. אי\u0004 \u0005[אם]\u0006 מדובר בברייתא \u0003כשפיטמו צריכא למימר\u0004 \u0005[צריכה לומר]\u0006 שאין המזיק נפטר מתשלום הנזק?!","\u0003אמר רב פפא: רישא\u0004 \u0005[תחילת\u0006 הברייתא\u0005]\u0006 \u0003משכחת לה\u0004 \u0005[מוצא אתה\u0006 אפשרות להסביר \u0005אותה]\u0006 \u0003בין דפטמה פטומי\u0004 \u0005[שפיטם\u0006 את השור\u0005]\u0006 \u0003בין דשבחא ממילא\u0004 \u0005[\u0006\u0005שהשביח מעצמו],\u0006 \u0003ואצטריך לאשמועינן\u0004 \u0005[והוצרך להשמיע לנו]\u0006 \u0003דהיכא דשבחא ממילא\u0004 \u0005[ש\u0006אפילו \u0005במקום שהשביח\u0006 השור הניזק \u0005מעצמו]\u0006 מכל מקום \u0003נותן לו כשעת הנזק\u0004 ולא כשעת העמדה בדין. ואילו \u0003סיפא\u0004 \u0005[סופה\u0006 של הברייתא\u0005]\u0006 בשור המזיק \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא\u0006 אפשרות להסביר \u0005אותה]\u0006 \u0003אלא כשפטמו\u0004 בעליו.","שנינו בראש הברייתא: \u0003כחש\u0004 השור הניזק — נדון \u0003כשעת העמדה בדין.\u0004 ושואלים: \u0003כחש מחמת מאי\u0004 \u0005[מה]?\u0006 \u0003אילימא דכחשא\u0004 \u0005[אם תאמר שכחש]\u0006 השור \u0003מחמת מלאכה\u0004 שעשו בו, \u0003לימא ליה\u0004 \u0005[שיאמר לו\u0006 המזיק\u0005]:\u0006 \u0003את מכחשת ואנא יהיבנא\u0004 \u0005[אתה מכחיש\u0006 את שורך \u0005ואני אתן]?\u0006","\u0003אמר רב אשי:\u0004 ש\u0003כחש מחמת\u0004 ה\u0003מכה\u0004 שנגחו, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הניזק: \u0003קרנא דתורך קבירא ביה\u0004 \u0005[הקרן של שורך קבורה בו],\u0006 כלומר, מחמת המכה הוא מכחיש והולך.","\u0003שור\u0004 תם שהיה \u0003שוה מאתים שנגח שור\u0004 אחר \u0003שוה מאתים, ואין הנבילה יפה\u0004 (שווה) \u0003כלום, אמר ר' מאיר: על\u0004 מקרה \u0003זה נאמר\u0004 בתורה: \u0003\"ומכרו את השור החי וחצו את כספו\"\u0004 (שמות כא, לה).","\u0003אמר לו\u0004 \u0003ר' יהודה:\u0004 אכן \u0003וכן הלכה,\u0004 ואולם לענין פירוש הפסוק \u0003קיימת\u0004 (הסברת) מה שנאמר \u0003\"ומכרו את השור החי וחצו את כספו\", ולא קיימת\u0004 את חציו השני \u0003\"וגם\u0004 את \u0003המת יחצון\"\u0004 (שמות כא, לה), שהרי אין בשור המת כל שווי. \u0003ואיזה\u0004 המקרה שמדובר בו בכתוב — \u0003זה שור שוה מאתים שנגח שור\u0004 אחר \u0003שוה מאתים, והנבילה יפה\u0004 \u0003חמשים זוז, שזה נוטל חצי\u0004 ערכו של \u0003החי\u0004 (מאה) \u0003וחצי המת\u0004 (עשרים וחמישה), \u0003וזה נוטל חצי החי וחצי המת.\u0004","ועוד על מחלוקתם של ר' מאיר ור' יהודה בפירוש הכתובים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שור שוה מאתים שנגח שור שוה מאתים, והנבילה יפה חמשים זוז\u0004 — \u0003זה,\u0004 הניזק, \u0003נוטל חצי החי וחצי המת, וזה,\u0004 המזיק, \u0003נוטל חצי החי וחצי המת, וזהו\u0004 דין ה\u0003שור האמור בתורה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' מאיר אומר: אין זהו שור האמור בתורה, אלא\u0004 מדובר שם ב\u0003שור שוה מאתים שנגח לשור שוה מאתים, ואין הנבילה יפה כלום, על זה נאמר \"ומכרו את השור החי וחצו את כספו\". אלא מה אני מקיים\u0004 (מסביר) את המשך הכתוב \u0003\"וגם את המת יחצון\"?\u0004 כוונתו: \u0003פחת שפחתו מיתה מחצין בחי,\u0004 כלומר, את הנזק של המיתה משלמים מתוך מחצית השור החי המזיק, אבל אין לבעל השור המזיק חלק בנבילה של הניזק.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בין\u0004 לדעת \u0003ר' מאיר בין\u0004 לדעת \u0003ר' יהודה,\u0004 במקרה שדיבר עליו ר' יהודה, ששווה הנבילה חמישים, \u0003האי\u0004 \u0005[זה]\u0006 \u0003מאה ועשרים וחמשה שקיל\u0004 \u0005[לוקח],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003מאה ועשרים וחמשה שקיל\u0004 \u0005[לוקח],\u0006 שהרי לדעת ר' מאיר נוטל הניזק את הנבילה שהיא שווה חמשים זוז, ועוד שבעים וחמישה זוז, שהם מחצית הנזק, מגוף המזיק. ואף המזיק נותר עם מאה עשרים וחמישה זוז מתוך המאתיים שהיה שורו שווה. אם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם אנו אומרים שחוצים את מחירם של שני השוורים המזיק והניזק כדברי ר' יהודה, או אם אנו אומרים שחוצים בגוף המזיק את הפחת שפחת הניזק, כדברי ר' מאיר?","\u0003אמר רבא:\u0004 בענין \u0003פחת\u0004 ה\u0003נבילה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה. שאם פחת מחיר הנבילה בינתיים משעת המיתה עד המכירה, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003פחת נבילה\u0004 של \u0003ניזק הוי\u0004 \u0005[הוא]\u0006 ומה שפחת המחיר אינו עניינו של המזיק, לפי שהמזיק אין לו אחריות עוד על הנבילה, ולאחר שהעריכו את ההפסד — כל מה שאירע לאחר מכן אינו עניינו. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003פחת נבילה\u0004 של ה\u0003מזיק הוי פלגא\u0004 \u0005[הוא למחצה]\u0006 ולכן אם ירד ערך הנבילה, כיון שהם חולקים גם את המת וגם את החי נמצא שבהפסד זה נושא גם המזיק.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003אם כן,\u0004 לפי שיטת פירוש זו \u0003מצינו\u0004 (מצאנו) ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004"],["\u0003תם חמור ממועד,\u0004 שהרי במועד לדעת הכל הבעלים (של השור הניזק) הם המטפלים בנבילה, ואם פחת ערכה הם מפסידים!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן\u0006 הדין\u0005],\u0006 שתם חמור, וראיה לדבר \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 בענין אחר, \u0003ר' יהודה אומר:\u0004 אם שמר את השור שמירה שאינה מעולה, ויצא והזיק, אם היה זה שור \u0003תם\u0004 — \u0003חייב, ו\u0004אם היה זה שור \u0003מועד\u0004 — \u0003פטור.\u0004 ואולם אין להביא ראיה משם, \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' יהודה\u0004 אומר שתם חמור ממועד — הרי זה דווקא \u0003לענין שמירה,\u0004 שחייב לשמור עליו שמירה מעולה יותר, \u0003דכתיבי קראי\u0004 \u0005[שנאמרו כתובים]\u0006 מיוחדים לענין זה, ואולם \u0003לענין תשלומין מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 אומר שתם חמור ממועד?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה אומר: יכול\u0004 אפשר שיהא הדין כך שאם \u0003שור שוה מנה\u0004 (מאה דינרים) \u0003שנגח שור שוה חמש סלעים\u0004 (שהם עשרים דינרים) \u0003והנבילה יפה\u0004 (שווה) \u0003סלע\u0004 אחד (ארבעה דינרים), ש\u0003זה נוטל חצי החי וחצי המת, וזה נוטל חצי החי וחצי המת,\u0004 ונמצא שהניזק מקבל חמישים ושנים דינרים, שהם הרבה יותר ממה שהיה שווה שורו בחיים?","\u0003אמרת\u0004 (אומר אתה): \u0003וכי מועד למה,\u0004 לאיזה ענין, \u0003יוצא,\u0004 נקבע לו דין מיוחד כמועד, האם \u0003להחמיר עליו\u0004 מדינו של תם \u0003או להקל עליו? הוי אומר\u0004 שבוודאי בא \u0003להחמיר עליו.\u0004 ומעתה נאמר: \u0003ומה מועד אינו משלם אלא מה שהזיק\u0004 ולא יותר, \u0003תם הקל לא כל שכן?\u0004 עד כאן דברי ר' יהודה. ואם כן ברור מדבריו שאין להחמיר לענין תשלומים בתם יותר מבמועד.","\u0003אלא\u0004 יש לדחות הסבר זה של רבא, שבפחת נבילה נחלקו ר' מאיר ור' יהודה, ויש לפרש את מחלוקתם כפי ש\u0003אמר ר' יוחנן:\u0004 בענין \u0003שבח נבילה,\u0004 אם עלה מחירה לאחר מיתה, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 ר' מאיר \u0005סבור]:\u0006 שבח הנבילה כולו של \u0003ניזק הוי\u0004 \u0005[הוא],\u0006 שהרי אין למזיק שותפות בנבילה, \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' יהודה \u0005סבור]:\u0006 \u0003פלגא\u0004 \u0005[חצי]\u0006 מן השבח לניזק וחציו השני למזיק.","\u0003והיינו דקא קשיא ליה\u0004 \u0005[וזהו ש\u0006היה \u0005קשה לו]\u0006 \u0003לר' יהודה\u0004 בברייתא אחרת, לשיטתו: \u0003השתא דאמרת חס רחמנא עילויה\u0004 \u0005[עכשיו שאתה אומר\u0006 ש\u0005חסה התורה עליו]\u0006 על ה\u0003מזיק דשקיל בשבחא\u0004 \u0005[ש\u0006הוא \u0005לוקח בשבח\u0006 הנבילה\u0005],\u0006 אם כן \u0003יכול\u0004 אפשר שנאמר כי \u0003שור שוה חמש סלעים\u0004 (עשרים דינרים) \u0003שנגח שור שוה מנה\u0004 (מאה דינרים) \u0003והנבילה יפה\u0004 (שווה) \u0003חמשים זוז\u0004 (דינר), שיהא \u0003זה נוטל חצי החי וחצי המת, וזה נוטל חצי החי וחצי המת,\u0004 ונמצא שהמזיק נוטל לבסוף שלושים וחמישה זוז, יותר ממה שהיה שורו שווה (רק עשרים זוז)?","\u0003אמרת\u0004 (אומר אתה): \u0003היכן מצינו מזיק נשכר, שזה\u0004 המזיק יוצא \u0003נשכר\u0004 שנוטל יותר ממה שהיה שורו שווה? \u0003ואומר\u0004 הכתוב \u0003\"שלם ישלם\"\u0004 (שמות כא, לו) לומר: \u0003בעלים\u0004 של השור המזיק \u0003משלמין, ואין בעלים נוטלין.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה טעם הוצרך להוסיף \u0003\"ואומר\"?\u0004 ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 שאין המזיק נשכר \u0003היכא דאיכא פסידא\u0004 \u0005[במקום שיש הפסד]\u0006 \u0003לניזק,\u0004 שהרי במקרה זה היה הפחת שמחמת מיתה חמישים זוז, והניזק מפסיד, שהרי הוא מקבל רק שלושים וחמישה זוז, ודווקא במקרה זה לא יהא המזיק נשכר משבח הנבילה, \u0003אבל היכא דליכא פסידא\u0004 \u0005[במקום שאין הפסד]\u0006 \u0003לניזק, כגון שור שוה חמש סלעים\u0004 (עשרים דינר) \u0003שנגח שור שוה חמש סלעים, והנבילה יפה שלשים זוז,\u0004 שהתייקר בשר הנבילה עד שהיא שווה יותר מן השור כשהיה חי, במקרה זה נאמר כי \u0003שקיל נמי\u0004 \u0005[מקבל גם כן]\u0006 ה\u0003מזיק בשבחא\u0004 \u0005[בשבח\u0006 הנבילה\u0005],\u0006 שהרי הניזק אינו מפסיד כאן, שהרי הוא מקבל עשרה דינרים מן השור המזיק וחמישה עשר מן הנבילה, ונמצא מרוויח חמישה זוזים.","על כן מוסיף הוא: \u0003ואומר \"שלם ישלם\"\u0004 לומר: \u0003בעלים\u0004 של השור המזיק \u0003משלמין, ואין בעלים נוטלין.\u0004","ולעצם שיטתו של ר' יהודה, שהבעלים מחלקים ביניהם את השור המזיק ואת השור הניזק, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר תחליפא לרבא: אם כן מצינו\u0004 (מצאנו) ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004 לפעמים \u0003תם משלם יותר מחצי נזק,\u0004 כאשר ערך השור המזיק גדול בהרבה מערך הנזק, \u0003ו\u0004הרי \u0003התורה אמרה \"ומכרו את השור החי וחצו את כספו\"\u0004 (שמות כא, לה)!","השיב לו רבא: \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לר' יהודה,\u0004 גם הוא מסכים להלכה, כי רק \u0003פחת שפחתה מיתה\u0004 אותו \u0003מחצין בחי,\u0004 ולכן אין המזיק משלם יותר ממחצית הנזק.","ושואלים: \u0003מנא ליה\u0004 \u0005[מניין לו\u0006 לר' יהודה\u0005]\u0006 הלכה זו? — \u0003מ\"וגם את המת יחצון\"\u0004 (שמות כא, לה), כפי שלמד ר' מאיר? \u0003והא אפקיה\u0004 \u0005[והרי הוציא אותו,\u0006 השתמש בו כבר\u0005]\u0006 \u0003ר' יהודה\u0004 בפסוק זה \u0003ל\u0004למוד ש\u0003זה נוטל חצי החי וחצי המת וזה נוטל חצי החי וחצי המת!\u0004","ומשיבים: \u0003אם כן, נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"ואת המת\u0004 יחצון \u0003\",\u0004 \u0003מאי\u0004 \u0005[מה]\u0006 טעם התוספת \u0003\"וגם\u0004 את המת \u0003\"\u0004— \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 הן לענין דרך החלוקה, והן לענין זה שלעולם אין המזיק משלם יותר מחצי הנזק.","\u0003יש חייב על מעשה\u0004 נזק שעשה \u0003שורו ופטור על\u0004 אותו \u0003מעשה\u0004 אם עשה אותו הוא \u0003עצמו.\u0004 ולהיפך, יש \u0003פטור על מעשה שורו וחייב על מעשה עצמו.\u0004","\u0003כיצד? שורו שבייש\u0004 אדם — \u0003פטור\u0004 מלשלם על מה שבייש, \u0003ו\u0004אילו \u0003הוא\u0004 עצמו \u0003שבייש\u0004 — \u0003חייב.\u0004 וכן \u0003שורו שסימא את עין עבדו\u0004 של בעליו, \u0003ו\u0004כן אם \u0003הפיל את שינו\u0004 של העבד — \u0003פטור\u0004 האדון מלשחרר בשל כך את עבדו, \u0003ו\u0004אילו \u0003הוא\u0004 עצמו \u0003שסימא את עין עבדו ו\u0004כן אם \u0003הפיל את שינו\u0004 — \u0003חייב\u0004 לשחררו, כאמור בתורה (שמות כא, כו–כז) שהאדון העושה זאת לעבדו חייב לשחררו.","לעומת זאת, \u0003שורו שחבל באביו ובאמו\u0004 של בעליו — \u0003חייב\u0004 הבן לשלם את הנזק שהזיק להם, \u0003ו\u0004אילו \u0003הוא\u0004 עצמו \u0003שחבל באביו ובאמו\u0004 — \u0003פטור\u0004 מלשלם להם. וכן \u0003שורו שהדליק את הגדיש בשבת,\u0004 הרי בעליו \u0003חייב\u0004 לשלם את הנזקים, \u0003ו\u0004אילו \u0003הוא\u0004 עצמו \u0003שהדליק את הגדיש בשבת\u0004 — \u0003פטור\u0004 מתשלומים \u0003מפני שהוא מתחייב בנפשו\u0004 מיתה על שחבל באביו ואמו, וכן על שחילל את השבת, וחייבי מיתה פטורים מתשלומים.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אבהו קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: \u0003כל המקלקלין\u0004 בשבת \u0003פטורין\u0004 בדיני שבת, \u0003חוץ מחובל ומבעיר\u0004 אש, שאף שהם מקלקלים — מכל מקום נחשבים הם כעושים מלאכה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה\u0006 את הדבר הזה \u0005בחוץ],\u0006 כלומר, ברייתא זו אינה מוסמכת ואין מכניסים אותה לבית המדרש, כי הלכה זו ב\u0003חובל ומבעיר אינה משנה,\u0004 שאין פוסקים כן להלכה. \u0003ואם תימצי\u0004 \u0005[תרצה]\u0006 בכל זאת \u0003לומר\u0004 ש\u0003משנה\u0004 היא ויש לה מקום, צריך אתה לפרש כך: \u0003חובל\u0004 שיתחייב כעושה מלאכה בשבת הריהו \u0003בצריך\u0004 דם \u0003ל\u0004\u0003כלבו\u0004 וחבל בבהמה להוציא ממנה דם. \u0003מבעיר\u0004 יהיה חייב הריהו \u0003בצריך לאפרו,\u0004 שבמקרים אלה נמצא שאינו רק מקלקל אלא עושה מלאכה שיש בה תיקון.","ומנסים לברר את הענין מתוך משנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003שורו שהדליק את הגדיש בשבת\u0004 — \u0003חייב, ו\u0004אילו \u0003הוא\u0004 עצמו \u0003שהדליק את הגדיש בשבת\u0004 — \u0003פטור. וקתני\u0004 \u0005[ושנה]\u0006 \u0003הוא דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שורו,\u0004 כלומר, מן הסתם מדובר כאן באותו אופן עצמו. ומעתה נאמר: \u0003מה שורו\u0004 שהדליק את הגדיש ודאי מדובר ש\u0003לא קבעי ליה\u0004 \u0005[צריך לו\u0006 לאפרו\u0005]\u0006 שהרי אין השור חושב על כך,"],["\u0003אף הוא,\u0004 האיש שהדליק, \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר כאן ש\u0003לא קבעי ליה\u0004 \u0005[צריך אותו]\u0006 את האפר, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003פטור, מפני שהוא נדון בנפשו.\u0004 ומכאן מוכח שהמבעיר בשבת חייב אף שאינו צריך לאפרו, ושלא כדברי ר' יוחנן!","ודוחים: \u0003לא,\u0004 אין להשוות בין שור לאיש בדרך זו, אלא להיפך: \u0003שורו דומיא דידיה\u0004 \u0005[בדומה לו\u0006 עצמו\u0005];\u0006 \u0003מה הוא\u0004 עצמו שהבעיר בשבת מדובר במקרה \u0003דקבעי ליה\u0004 \u0005[שהוא צריך\u0006 את האפר\u0005]\u0006 \u0003אף שורו\u0004 שהבעיר גדיש בשבת מדובר במקרה \u0003דקבעי ליה\u0004 \u0005[שהוא צריך\u0006 את האפר\u0005].\u0006","ושואלים: \u0003שורו היכי משכחת ליה\u0004 \u0005[איך\u0006 באיזה אופן \u0005מוצא אתה אותו]\u0006 שזקוק הוא לאפר, והדליק לשם האפר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אויא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בשור פקח שעלתה לו נשיכה בגבו, וקא בעי למקלייה\u0004 \u0005[והוא רוצה לשרוף אותו\u0006 את הגדיש\u0005]\u0006 \u0003ואיגנדר בקוטמא\u0004 \u0005[ולהתגלגל ב\u0006תוך \u0005האפר],\u0006 על מנת לרפא את הנשיכה.","ושואלים: \u0003ומנא ידעינן\u0004 \u0005[ומנין יודעים אנו]\u0006 שלשם כך הדליק? ומשיבים: \u0003דלבתר דקלייה קמגנדר בקוטמא\u0004 \u0005[שלאחר ששרף אותו,\u0006 את הגדיש, הוא אכן \u0005מתגלגל ב\u0006תוך \u0005האפר]\u0006 שנוצר שם.","ושואלים: \u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש\u0006 שור פיקח \u0005כעין זה]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 ומביאים דוגמא לדבר: \u0003דההוא תורא דהוה בי\u0004 \u0005[שור אחד שהיה בבית]\u0006 של \u0003רב פפא\u0004 \u0003דהוה כיבין ליה חינכיה\u0004 \u0005[שכאבו לו שיניו],\u0006 \u0003עייל ופתקיה לנזייתא ושתי שיכרא ואיתסי\u0004 \u0005[נכנס ושבר את המכסה\u0006 שבפי הכלי \u0005ושתה\u0006 ממנו \u0005שיכר והתרפא]\u0006 ונמצא שיש שור פיקח עד כדי כך.","ובענין זה מביאים, \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא: מי מצית אמרת\u0004 \u0005[האם יכול אתה לומר]\u0006 במשנתנו \u0003שורו דומיא דידיה\u0004 \u0005[\u0006ב\u0005דומה לו]?\u0006 \u0003והא קתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003שורו שבייש\u0004 — \u0003פטור, והוא שבייש\u0004 — \u0003חייב.\u0004 ואם נפרש \u0003שורו דומיא דידיה\u0004 \u0005[\u0006ב\u0005דומה לו]\u0006 \u0003נתכוון לבייש היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 שהשור יתכוון לבייש אדם? שהרי אף אדם אינו מתחייב על הבושת עד שיתכוון!","ומשיבים: כאן מדובר \u0003כגון שנתכוון\u0004 השור \u0003להזיק,\u0004 ובמקרה כזה אדם חייב על הבושת, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 בכל מקרה ש\u0003נתכוון\u0004 אדם \u0003להזיק, אף על פי שלא נתכוון לבייש\u0004 — חייב על הבושת.","\u0003רבא אמר:\u0004 כדי ליישב את שיטת ר' יוחנן אין צורך להגיע לדוחק זה, אלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת באדם שהדליק בשבת או שחבל באביו \u0003בשוגג,\u0004 שאף שעל מעשה זה אינו חייב מיתה, מכל מקום, כיון שיש בעבירה זו עונש מיתה אם עשאה במזיד — הוא פטור מתשלומים.","\u0003וכ\u0004שיטת \u0003תנא דבי\u0004 \u0005[החכם של בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 היא, \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה:\u0004 נאמר \"ומכה בהמה ישלמנה ומכה אדם יומת\" (ויקרא כד, כא), ומן ההיקש בכתוב של \u0003מכה אדם ומכה בהמה\u0004 נלמד להשוות דינם:","\u0003מה מכה בהמה\u0004 — \u0003לא חלקת בה\u0004 בהכאה זו \u0003בין\u0004 היה זה ב\u0003שוגג בין\u0004 היה זה ב\u0003מזיד, בין\u0004 היה זה בדרך \u0003מתכוון לשאין מתכוון, בין\u0004 היה זה \u0003דרך ירידה לדרך עלייה,\u0004 והשוואה זו לא באה \u0003לפוטרו ממון\u0004 בכל אלה \u0003אלא לחייבו ממון,\u0004 שההורג בהמה חייב בכל מקרה. \u0003אף מכה אדם\u0004 — \u0003לא תחלוק בו\u0004 בדינו, \u0003בין\u0004 \u0003שוגג למזיד, בין מתכוון לשאין מתכוון, בין דרך ירידה לדרך עלייה, לחייבו ממון\u0004 על נזקים שגרם לו בשעה שגרם לו מיתה \u0003אלא לפוטרו ממון.\u0004 שכל אדם שעשה מעשה שיש בו עונש מוות, אף שבפועל, כיון שהיה שוגג, הוא פטור מעונש זה, מכל מקום נפטר מכל תשלומי נזקים.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: מי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד אותה\u0006 את משנתנו\u0005]\u0006 \u0003בשוגג?\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מפני שנדון בנפשו\" קתני\u0004 \u0005[שנה],\u0006 משמע שמדובר במזיד, שהוא זה שנידון בנפשו!","והשיב להם: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 כך יש להבין\u0005]:\u0006 הרי הוא פטור \u0003כיון\u0004 שעל מעשה שכזה שהיה נעשה \u0003במזיד\u0004 — \u0003נדון בנפשו, והיכי דמי\u0004 \u0005[וכיצד היה מקרה כזה]\u0006 שנידון למיתה בהבערה במזיד — \u0003דקא בעי\u0004 \u0005[\u0006כ\u0005שהוא צריך]\u0006 \u0003לאפרו\u0004 של הגדיש, \u0003השתא\u0004 \u0005[עכשיו]\u0006 גם אם עשה זאת \u0003בשוגג\u0004 — בכל אופן \u0003פטור,\u0004 לפי השיטה שהעושה דבר שיש בו עונש מוות אף שבפועל אינו נענש בכך — אינו חייב בתשלומים כלל.","\u0003שור שהיה רודף אחר שור אחר, והוזק\u0004 השור הנרדף, ולא ראו כיצד הוזק, \u0003זה,\u0004 בעל השור הניזק, \u0003אומר: שורך הזיק\u0004 את שורי, וחייב אתה בתשלומי נזקי, \u0003וזה אומר: לא כי, אלא בסלע לקה\u0004 (קיבל מכה) ולא מחמת נגיחת שורי, ופטור אני מכל תשלום. במקרה כזה — \u0003המוציא מחבירו עליו הראיה,\u0004 שכל עוד לא הוכיח הניזק שהשור הרודף עשה זאת — אין בעל השור הרודף משלם על הנזק.","\u0003היו שנים\u0004 (שני שוורים של שני בעלים) \u0003רודפים אחר\u0004 שור \u0003אחד\u0004 של אדם שלישי, והוזק השור על ידי אחד מן השוורים הרודפים, אלא ש\u0003זה\u0004 (בעל שור אחד) \u0003אומר\u0004 לחבירו: \u0003שורך הזיק, וזה אומר: שורך הזיק\u0004 —"],["\u0003שניהם פטורים,\u0004 שכל אחד מהם דוחהו ואומר ששורו של השני הזיק. \u0003אם היו שניהם של איש אחד\u0004 — \u0003שניהם חייבים\u0004 כאשר יבואר הלאה בגמרא.","היו השוורים המזיקים שייכים לאדם אחד ו\u0003היה אחד\u0004 מהם \u0003גדול ואחד קטן,\u0004 ושניהם תמים, שגובים מגוף השור בלבד, \u0003הניזק אומר:\u0004 השור ה\u0003גדול\u0004 הוא ש\u0003הזיק,\u0004 שעל ידי כך יקבל מגופו של שור זה תשלום חצי נזק, \u0003והמזיק אומר: לא כי, אלא קטן הזיק\u0004 ואין במחצית דמי הקטן כדי לשלם הנזק. וכן אם היו אותם שני שוורים של אדם אחד, \u0003אחד תם ואחד מועד, הניזק אומר: מועד הזיק\u0004 ומגיע לו תשלום מלא, \u0003והמזיק אומר: לא כי, אלא תם הזיק\u0004 ואינו משלם אלא חצי נזק, בשני מקרים אלה הכלל הוא — \u0003המוציא מחבירו עליו הראיה.\u0004","\u0003היו\u0004 השוורים \u0003הניזקין שנים, אחד גדול ואחד קטן, ו\u0004השוורים \u0003המזיקין שנים,\u0004 \u0003אחד גדול ואחד קטן, הניזק אומר: גדול הזיק את הגדול וקטן את הקטן, והמזיק אומר: לא כי, אלא קטן את הגדול,\u0004 שאם אין בגופו כדי לשלם מחצית הנזק, אינו משלם יותר, \u0003וגדול את הקטן;\u0004 וכן אם היה \u0003אחד תם ואחד מועד, הניזק אומר: מועד הזיק את הגדול ותם את הקטן, והמזיק אומר: לא כי, אלא תם את הגדול ומועד את הקטן\u0004 — \u0003המוציא מחבירו עליו הראיה.\u0004","\u0003אמר ר' חייא בר אבא:\u0004 משנתנו הקובעת במקרה של ספק אם שור הזיק שור את הכלל שהמוציא מחבירו עליו הראיה \u0003[זאת אומרת]\u0004 כי \u0003חלוקים עליו חביריו על סומכוס,\u0004 ש\u0003אמר: ממון המוטל בספק\u0004 — \u0003חולקין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בר ממל לר' חייא בר אבא:\u0004 וכי \u0003אמר סומכוס\u0004 את הכלל הזה \u0003אפילו\u0004 במצב של \u0003ברי\u0004 (וודאי) \u0003וברי,\u0004 ששני הצדדים טוענים כל חד בוודאות שהדבר הוא כדבריהם, כפי שהוא במשנתנו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אמר סומכוס אפילו\u0004 ב\u0003ברי וברי.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 אפשר להוכיח \u0003דמתניתין\u0004 \u0005[שמשנתנו]\u0006 \u0003בברי וברי הוא? דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003זה אומר: שורך הזיק, וזה אומר: לא כי,\u0004 ומשמע ששניהם טוענים בוודאות.","על העמדה זו של דין המשנה בברי וברי \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: מדרישא\u0004 \u0005[מכיון ש\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 מדובר בטענת \u0003ברי וברי, סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן]\u0006 מדובר בטענת \u0003ברי וברי,\u0004 אבל","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 את המקרה שאחר כך: \u0003היה אחד גדול ואחד קטן, ניזק אומר: גדול הזיק, ומזיק אומר: לא כי, אלא קטן הזיק;\u0004 וכן במקרה הנוסף, \u0003אחד תם ואחד מועד, ניזק אומר: מועד הזיק, והמזיק אומר: לא כי, אלא תם הזיק\u0004 — \u0003המוציא מחבירו עליו הראיה;\u0004 ומכאן נסיק:","\u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא מייתי\u0004 \u0005[מביא]\u0006 \u0003ראיה\u0004 — הריהו \u0003שקיל כדאמר\u0004 \u0005[מקבל כמו שאומר]\u0006 \u0003מזיק,\u0004 ואם כן \u0003נימא תהוי תיובתא\u0004 \u0005[נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה\u0006 \u0005חמורה]\u0006 על דעת \u0003רבה בר נתן,\u0004 ש\u0003אמר:\u0004 \u0003טענו\u0004 אדם את חבירו שהלה הפקיד אצלו \u0003חטים והודה לו בשעורים\u0004 אך לא בחטים — \u0003פטור\u0004 מכל תשלום, שהרי מה שטענו — לא הודה לו, ומה שהודה לו — לא טענו. ואף כאן הניזק שהוא התובע טוען שהשור הגדול הזיק, והמזיק שהוא הנתבע מודה ששור קטן הזיק, ונמצא שמודה לו שלא ממין הטענה שטענו!","\u0003אלא\u0004 יש לפרש כי בסוף המשנה מדובר \u0003בברי ושמא,\u0004 שאחד מהם טוען שבוודאי כך היה, והשני טוען כנגדו: אין בידך הוכחה, ושמא לא היה כדבריך.","ויש לברר: זה \u0003דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ברי מאן\u0004 \u0005[מיהו],\u0006 וזה \u0003דקאמר\u0004 \u0005[שאומר]\u0006 \u0003שמא מאן\u0004 \u0005[מיהו]?\u0006 \u0003אי נימא דקאמר\u0004 \u0005[אם נאמר שאומר]\u0006 \u0003ניזק\u0004 שהוא התובע: \u0003ברי\u0004 שהגדול הזיק, \u0003וקאמר\u0004 \u0005[ואומר]\u0006 \u0003מזיק\u0004 שהוא הנתבע: \u0003שמא\u0004 הקטן הזיק, \u0003אכתי לימא תהוי תיובתא\u0004 \u0005[עדיין נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה\u0006 \u0005חמורה]\u0006 לדברי \u0003רבה בר נתן,\u0004 שהרי המזיק שהוא הנתבע לא הודה כאן בטענת התובע כלל, ומכל מקום גובה הניזק מן הקטן!","\u0003אלא\u0004 יש לפרש שמדובר \u0003דקאמר\u0004 \u0005[שאומר]\u0006 ה\u0003ניזק: שמא\u0004 גדול הזיק, \u0003וקאמר\u0004 \u0005[ואומר]\u0006 ה\u0003מזיק: ברי\u0004 שקטן הזיק.","\u0003ומדסיפא\u0004 \u0005[ומכיון ש\u0006ב\u0005סוף]\u0006 המשנה מדובר בטענת \u0003ניזק שמא ו\u0004טענת \u0003מזיק ברי, רישא נמי\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה \u0005גם כן]\u0006 יש לפרש שטוען ה\u0003ניזק: שמא\u0004 שורך הזיק, \u0003ומזיק\u0004 טוען: \u0003ברי\u0004 שבסלע לקה, ולא כפי שדובר קודם — בברי וברי.","ועל כך תוהים: \u0003ו\u0004האם \u0003אמר סומכוס אפילו בהא\u0004 \u0005[בזו]\u0006 שחולקים ביניהם התובע והנתבע, \u0003דאיצטריך לאשמועינן\u0004 \u0005[שהוצרכה\u0006 משנתנו \u0005להשמיענו]\u0006 ש\u0003לא\u0004 כדבריו, אלא כדברי חכמים? הרי במקרה שהתובע טוען שמא, בוודאי לא יאמר סומכוס שיחלקו!","ודוחים: \u0003לא,\u0004 אף שב\u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 מדובר שטען \u0003ניזק שמא ומזיק\u0004 טוען \u0003ברי, רישא\u0004 \u0005[\u0006ב\u0005ראש]\u0006 מדובר ש\u0003ניזק\u0004 טוען \u0003ברי ומזיק\u0004 טוען \u0003שמא,\u0004 ובענין זה חלוקים חכמים על סומכוס הסבור שחולקים.","ושואלים: אם כן אף לשיטת רב פפא, \u0003והא לא דמיא רישא לסיפא\u0004 \u0005[והרי אינה דומה תחילת\u0006 המשנה \u0005לסופה]!\u0006 ומדוע לא נעמיד את תחילתה בברי וברי?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך כתירוץ: \u0003ברי ושמא, שמא וברי\u0004 — \u0003חד מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 שבעיקר יש בשני חלקיה של המשנה טענת ספק של אחד וטענה וודאית של האחר, אף כי המשנה מחליפה את הצדדים. ואולם שני מצבים שהאחד מהם הוא \u0003ברי וברי,\u0004 והשני הוא \u0003שמא וברי\u0004 — \u0003תרי מילי נינהו\u0004 \u0005[שני דברים הם]\u0006 ולפיכך לא ניתן להעמיד את תחילת המשנה בברי וברי.","ומעתה דנים בענין שהזכרנו \u0003גופא\u0004 \u0005[לגופו],\u0006 \u0003אמר רבה בר נתן: טענו חטין והודה לו בשעורין\u0004 — \u0003פטור.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בדבר זה? הלא כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה כן\u0005]:\u0006 \u0003טענו חטין והודה לו בשעורין\u0004 — \u0003פטור!\u0004","ומשיבים: \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהמשנה כך אומרת: \u0003פטור מדמי חטין וחייב בדמי שעורין\u0004 שהרי הודה לו עליהם, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבה בר נתן כי הכוונה היא ש\u0003פטור לגמרי\u0004 אף משעורים.","ומקשים על כך: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003היו הניזקין שנים, אחד גדול ואחד קטן\u0004 והמזיקים שנים אחד גדול ואחד קטן, הניזק אומר גדול הזיק את הגדול וכו' והמזיק אומר לא כי אלא קטן את הגדול \u0003וכו'\u0004 — והלכה היא: המוציא מחבירו עליו הראיה. ונדייק מכאן: \u0003הא לא מייתי\u0004 \u0005[הרי\u0006 אם \u0005אינו מביא]\u0006 הניזק \u0003ראיה\u0004 — \u0003שקיל\u0004 \u0005[מקבל]\u0006 הניזק \u0003כדקאמר\u0004 \u0005[כפי שאומר]\u0006 ה\u0003מזיק,\u0004 ולפי הסבר זה שאמרנו \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא כן הדין, הלא \u0003חטים ושעורים נינהו\u0004 \u0005[הם]\u0006 וצריך המזיק להיפטר לגמרי לדעת רבה בר נתן!","ומשיבים: אין צריך לדייק שנוטל ממש, אלא הכוונה היא: \u0003ראוי ליטול ו\u0004בפועל \u0003אין לו\u0004 דבר.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 ברייתא\u0005]\u0006 האומרת כי \u0003הרי זה משתלם על הקטן מן הגדול, ולגדול מן הקטן,\u0004 משמע שנוטל ממש!","ומשיבים: מדובר כאן ש\u0003תפס\u0004 הניזק מדעת עצמו מרכוש המזיק ומניחים בית דין בידו מה שראוי ליטול, אף שלכתחילה אינו יכול להוציא מידי המזיק אף תשלום זה.","ומקשים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה אחד תם ואחד מועד, הניזק אומר: מועד הזיק את הגדול ותם את הקטן, והמזיק אומר: לא כי, אלא תם את הגדול ומועד את הקטן\u0004 — \u0003המוציא מחבירו עליו הראיה; הא לא מייתי\u0004 \u0005[הרי\u0006 אם \u0005אינו מביא]\u0006 \u0003ראיה\u0004 — \u0003שקיל כדקאמר\u0004 \u0005[מקבל כמו שאומר]\u0006 \u0003מזיק, ואמאי\u0004 \u0005[ומדוע]\u0006 יקבל כלל? הלא כמו \u0003חטין ושעורין נינהו\u0004 \u0005[הם]!\u0006"],["ומשיבים: אין הכוונה שנוטל ממש, אלא ש\u0003ראוי ליטול, ואין לו.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על מקרה זה: \u0003הרי זה משתלם לקטן מן המועד, ולגדול מן התם,\u0004 משמע שמקבל תשלום ממש! ומשיבים: אף כאן מדובר לאחר שכבר \u0003תפס,\u0004 שאין מוציאים מידו מה שתפס, אבל אם לא תפס — אינו יכול ליטול.","נאמר במשנה: שני שוורים שרדפו אחרי שור, והוזק, \u0003היו שניהם של איש אחד\u0004 — \u0003שניהם חייבים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזיקא לרב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממה ששנינו ששניהם חייבים כי \u0003שוורים תמים שהזיקו, רצה\u0004 הניזק לגבות חובו \u0003מ\u0004שור \u0003זה\u0004 — \u0003גובה, רצה\u0004 לגבות חובו משור \u0003זה\u0004 — \u0003גובה?\u0004","דחה רב אשי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004שוורים \u0003מועדין,\u0004 שאין הניזק גובה מגוף השור המזיק אלא מרכוש בעליו כולו, ובכלל זה שוורים אלו.","והקשה לו רבא מפרזיקא: \u0003אי\u0004 \u0005[אם]\u0006 \u0003במועדין\u0004 מדובר, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה,\u0006 המשכה של המשנה\u0005]:\u0006 \u0003היה אחד גדול ואחד קטן, הניזק אומר: גדול הזיק, והמזיק אומר: לא כי, אלא קטן הזיק\u0004 — \u0003המוציא מחבירו עליו הראיה. אי\u0004 \u0005[אם]\u0006 \u0003במועדין\u0004 מדובר כאן, \u0003מאי נפקא ליה מיניה\u0004 \u0005[מה יוצא לו מזה],\u0006 מה זה משנה לו מי מהם הזיק? \u0003סוף סוף דמי תורא מעליא בעי לשלומי\u0004 \u0005[דמי שור מעולה,\u0006 שלם, המזיק \u0005צריך לשלם]\u0006 ומה אכפת לו מי מהם הזיק?","","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003סיפא\u0004 \u0005[סופה\u0006 של המשנה\u0005]\u0006 מדבר \u0003ב\u0004שוורים \u0003תמין, ורישא\u0004 \u0005[וראשה]\u0006 \u0003ב\u0004שוורים \u0003מועדין.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא סבא\u0004 \u0005[הזקן]\u0006 \u0003לרב אשי: אי\u0004 \u0005[אם]\u0006 \u0003במועדין\u0004 שאין גובים דווקא מגופם מדובר, האם ניתן להשתמש בלשון \u0003\"חייבים\"?! \"חייב גברא\" מיבעי ליה\u0004 \u0005[\"חייב האיש\" צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"שניהם\u0004 חייבים\u0003\"?\u0004 הלא תלוי הדבר בגובה הנזק! \u0003אלא\u0004 יש לדחות את מה שאמרנו, ולומר כי \u0003לעולם\u0004 יש לפרש שאף בתחילת המשנה מדובר \u0003בתמין,\u0004 ומה עניינו של \"שניהם חייבים\"? משנתנו כשיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר:\u0004 המזיק והניזק \u0003שותפין נינהו\u0004 \u0005[הם]\u0006 ולכן יש לניזק מעין סוג של קניין בגופם של המזיקים, \u0003וטעמא דאיתנהו לתרוייהו, דלא מצי מדחי ליה\u0004 \u0005[ו\u0006אם כן \u0005הטעם,\u0006 דווקא, \u0005כשנמצאים שניהם, שאינו יכול לדחות אותו]\u0006 ולומר לניזק: שמא לא זה, אלא שור שני הזיק — אז חייב לשלם. \u0003אבל\u0004 כאשר \u0003ליתנהו לתרוייהו\u0004 \u0005[אין\u0006 מצויים \u0005שניהם]\u0006 כגון שאבד או מת אחד מהם, \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 בעל השוורים: \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003ראיה דהאי תורא אזקך\u0004 \u0005[ששור זה הזיק לך]\u0006 \u0003ואשלם לך.\u0004","","\u0003שור\u0004 תם \u0003שנגח ארבעה וחמשה שוורים זה אחר זה\u0004 — \u0003ישלם\u0004 בעל השור המזיק \u0003לאחרון שבהם\u0004 מדמי שורו, \u0003ואם יש בו מותר,\u0004 שאחרי תשלום הנזק עדיין נשאר עודף במזיק — \u0003יחזיר\u0004 את השארית \u0003לשלפניו,\u0004 לבעל השור שננגח לפניו, \u0003ואם יש בו\u0004 \u0003מותר\u0004 גם אז — \u0003יחזיר לשלפני פניו. ו\u0004כלל הוא: \u0003האחרון אחרון,\u0004 כלומר, המאוחר יותר, \u0003נשכר,\u0004 אלו \u0003דברי ר' מאיר.\u0004 \u0003ר' שמעון אומר:\u0004 באופן אחר מחלקים, כיצד? \u0003שור\u0004 תם \u0003שוה מאתים\u0004 זוז \u0003שנגח לשור שוה מאתים\u0004 זוז, \u0003ואין הנבלה יפה\u0004 (שווה) \u0003כלום\u0004 — \u0003זה,\u0004 הניזק, \u0003נוטל מנה\u0004 (מאה זוז) שהוא מחצית נזקו, \u0003וזה,\u0004 בעל השור המזיק, \u0003נוטל מנה.\u0004","","\u0003חזר\u0004 השור \u0003ונגח שור אחר שוה מאתים\u0004 ואין הנבילה שווה כלום — בעל השור \u0003האחרון\u0004 שניזק \u0003נוטל מנה, ו\u0004באשר לשור \u0003ש\u0004ננגח \u0003לפניו\u0004 — \u0003זה\u0004 הניזק \u0003נוטל חמשים זוז,\u0004 שהוא מחצית ערכו של השור כעת (לאחר ששילמו מאה דינר לאחרון) \u0003וזה\u0004 הבעלים \u0003נוטל חמשים זוז.\u0004 \u0003חזר ונגח שור אחר שוה מאתים\u0004 ואין הנבילה שווה כלום — הניזק \u0003האחרון נוטל מנה, ושלפניו חמשים זוז, ושנים הראשונים\u0004 הניזק הראשון והמזיק מתחלקים במותר — \u0003דינר זהב\u0004 (כלומר, עשרים וחמשה זוזים) לכל אחד.","","שואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו,\u0006 כלומר, שיטת ר' מאיר, כשיטת \u0005מי היא]?\u0006 לכאורה ש\u0003לא כ\u0004דעת \u0003ר' ישמעאל ו\u0004ש\u0003לא כ\u0004דעת \u0003ר' עקיבא!\u0004","שהרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' ישמעאל\u0004 ש\u0003אמר\u0004 שהניזקים \u0003בעלי חובות\u0004 של המזיק \u0003נינהו\u0004 \u0005[הם],\u0006 הרי אם דינם כבעלי חובות לא צריך לשנות הלכה \u0003האי\u0004 \u0005[זו]\u0006 \u0003\"אחרון אחרון נשכר\",\u0004 אלא \u0003\"ראשון ראשון נשכר\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי בעל חוב ששיעבודו קודם לשיעבוד חבירו — קודם לחבירו בפרעון חובו. ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 כי השור המזיק \u0003תורא דשותפי\u0004 \u0005[שור של שותפים]\u0006 \u0003הוא\u0004 והוא שייך למזיק ולניזק יחד, הרי אז \u0003האי\u0004 \u0005[זו]\u0006 ההלכה ששנינו \u0003\"יש בו מותר\u0004 —"],["\u0003יחזיר לשלפניו\"\u0004 אינה נכונה, אלא \u0003\"\u0004\u0003לכולם\",\u0004 לכל הניזקים הקודמים, \u0003מבעי ליה\u0004 \u0005[צריך לו]\u0006 לומר, שהרי כולם שותפים בו!","\u0003אמר רבא: לעולם\u0004 יש לפרש כי משנתנו \u0003כ\u0004שיטת \u0003ר' ישמעאל\u0004 היא, ש\u0003אמר\u0004 שכל הניזקים \u0003בעלי חובות נינהו\u0004 \u0005[הם],\u0006 \u0003ודקשיא\u0004 \u0005[ו\u0006מה \u0005שקשה]\u0006 \u0003לך:\u0004 אם כן זו ששנינו למה \u0003\"אחרון אחרון נשכר\",\u0004 הלא \u0003\"ראשון ראשון נשכר\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שתפסו ניזק\u0004 ראשון את השור \u0003לגבות הימנו, ו\u0004ממילא \u0003נעשה עליו\u0004 \u0003כשומר שכר ל\u0004ענין אחריות \u0003נזקין,\u0004 ולכן האחריות לנזקים שהזיק השור מאותה שעה ואילך חלה עליו. וכן תחול האחריות על השני אם יתפוס ממנו את השור.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אם כן, מה שאמרו במשנה \u0003\"\u0004אם \u0003יש בו מותר\u0004 — \u0003יחזיר לשלפניו\",\u0004 הלא \u0003\"יחזיר לבעלים\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי מחצית מערך השור המזיק שייכת לבעליו הראשונים, והוא אינו צריך לשלם מחלקו על הנזק החדש שנעשה!","\u0003אמר רבינא:\u0004 דבר זה לענין אחר נאמר, ו\u0003הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין: \u0003אם יש בו מותר בנזקיו,\u0004 שהאחרון הוזק בסכום נמוך יותר מזה שלפניו — \u0003יחזיר\u0004 את מותר הנזק \u0003ל\u0004זה \u0003שלפניו.\u0004","\u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: משום פשיעת שומרין נגעו בה.\u0004 כלומר, הלכה זו מתבססת על דין פשיעת שומרים וכך יש להבינה.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את דברי ר' מאיר במשנתנו \u0003כ\u0004שיטת \u0003ר' ישמעאל, אי הכי אימא סיפא\u0004 \u0005[אם כך אמור\u0006 את \u0005סופה]\u0006 של המשנה, \u0003ר' שמעון אומר: שור שוה מאתים שנגח שור שוה מאתים, ואין הנבלה יפה\u0004 (שווה) \u0003כלום\u0004 — \u0003זה נוטל מנה וזה נוטל מנה.\u0004","\u0003חזר ונגח שור אחר שוה מאתים\u0004 — \u0003האחרון נוטל מנה, ושלפניו\u0004 — \u0003זה נוטל חמשים זוז וזה נוטל חמשים זוז. חזר ונגח שור שוה מאתים\u0004 — \u0003האחרון נוטל מנה, ושלפניו נוטל חמשים זוז, ושנים הראשונים\u0004 נוטלים \u0003דינר זהב\u0004 כל אחד.","אם כן \u0003אתאן\u0004 \u0005[באנו]\u0006 בכך \u0003ל\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר:\u0004 השור המזיק \u0003תורא דשותפי\u0004 \u0005[שור של שותפים]\u0006 \u0003הוא.\u0004 וכי נוכל לומר כי \u0003רישא\u0004 \u0005[ראש\u0006 המשנה\u0005]\u0006 כשיטת \u0003ר' ישמעאל וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' עקיבא\u0004 ואין כל המשנה כשיטה אחת?","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא, שבוק מתניתין ותא בתראי\u0004 \u0005[גדול השיניים, עזוב\u0006 את \u0005משנתנו ובוא אחרי];\u0006 \u0003רישא\u0004 \u0005[ראשה]\u0006 כדעת \u0003ר' ישמעאל וסיפא\u0004 \u0005[וסופה]\u0006 כ\u0003ר' עקיבא,\u0004 אף שאין רגילים לפרש משנה לפי שיטת שני חכמים.","ומעירים: \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 במקום אחר ש\u0003אמר ר' יוחנן:\u0004 החכמים שנחלקו במשנתנו, ר' מאיר ור' שמעון, לגבי השאלה אם \u0003הקדישו ניזק איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, כלומר, עיקר השאלה הוא אם הניזק נחשב כשותף, ואם כן יש לו זכות להקדיש דבר השייך לו. והרי זו ממש מחלוקת ר' ישמעאל ור' עקיבא.","ובענין דינר הזהב שהובא במשנתנו, מביאים, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 בפרק \"החובל\": \u0003התוקע\u0004 (הסוטר) \u0003לחבירו\u0004 — \u0003נותן לו\u0004 כתשלום קנס \u0003סלע, ר' יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי הגלילי: מנה\u0004 (מאה דינרים).","וכעין זה מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 \u0003דתקע לחבריה\u0004 \u0005[שסטר לחבירו].\u0006 \u0003שלחיה\u0004 \u0005[שלח אותו]\u0006 \u0003רב טוביה בר מתנה לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף,\u0004 ושאל אותו: האם סכומי כסף שנזכרו במשנה \u0003סלע צורי תנן\u0004 \u0005[שנינו]\u0006 שהוא סלע ששווה ארבעה דינרים, \u0003או סלע מדינה תנן\u0004 \u0005[שנינו]\u0006 שהוא סלע השווה רק שמינית מזה, כלומר, חצי דינר?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 שאפשר לפתור בעיה זו מן המשנה שלנו שנאמר בה: \u0003ושנים הראשונים דינר זהב\u0004 (עשרים וחמישה דינרים). \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003תני\u0004 \u0005[שונה]\u0006 ה\u0003תנא\u0004 ומשתמש לצורך חישוב הנזקים ב\u0003סלע מדינה,\u0004 אם כן \u0003נפלוג ונתני\u0004 \u0005[יחלק וישנה]\u0006 עוד מקרה שנגח השור, \u0003עד\u0004 שהראשונים יקבלו כל אחד \u0003תריסר\u0004 \u0005[שנים עשר]\u0006 דינרים \u0003וסלע\u0004 שהוא חצי דינר. וכיון שלא עשה כן משמע שאין התנא במשנה דן בסלע מדינה ששוויו פחות מדינר.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 זו אינה הוכחה, וכי ה\u0003תנא כי רוכלא ליתני וליזיל\u0004 \u0005[כרוכל ישנה וילך],\u0006 וכי צריך התנא למנות את כל האפשרויות עד סופן, כרוכל זה שמכריז על כל פריט ופריט שיש בסחורתו? די לו לחכם שיביא דוגמה המסבירה את דבריו, ואינו צריך לפרט הכל. ואם כן אין להוכיח משם.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הבעיה הזו? \u0003פשטוה\u0004 \u0005[פתרו אותה]\u0006 \u0003מהא\u0004 \u0005[מזו]\u0006 ש\u0003אמר רב יהודה אמר רב: כל כסף האמור בתורה,\u0004 כלומר, ששיעורו נקבע בתורה הרי הוא \u0003כסף צורי, ו\u0004אילו כל כסף האמור ב\u0003של דבריהם\u0004 של חכמים — \u0003כסף מדינה.\u0004 ואם כן, סלע זה שאמרו כקנס לסוטר הוא סלע מדינה, ששוויו חצי דינר.","כיון שהגיע למסקנה זו, שסלע זה שמקבל תמורת הסטירה אינו אלא חצי דינר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא גברא\u0004 \u0005[אותו האיש]\u0006 שהוכה: \u0003הואיל ופלגא דזוזא\u0004 \u0005[וחצי זוז]\u0006 בלבד \u0003הוא\u0004 — \u0003לא בעינא\u0004 \u0005[איני רוצה]\u0006 בו, שבוש אני לקחת אותו, \u0003נתביה\u0004 \u0005[שיתן אותו]\u0006 \u0003לעניים.\u0004 אחר כך \u0003הדר\u0004 \u0005[חזר]\u0006 התחרט המוכה, ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב יוסף: \u0003נתביה ניהלי, איזיל ואברי ביה נפשאי\u0004 \u0005[שיתן אותו לי,\u0006 ואני \u0005אלך ואבריא בו את עצמי].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף:\u0004 כיון שאמרת שאתה נותנו לעניים \u0003כבר זכו ביה\u0004 \u0005[בו]\u0006 \u0003עניים\u0004 ושלהם הוא. \u0003ואף על גב דליכא\u0004 \u0005[ואף על פי שאין]\u0006 \u0003עניים הכא\u0004 \u0005[כאן]\u0006 במקום, שיוכלו לזכות בפועל, \u0003אנן\u0004 \u0005[אנחנו]\u0006 בית הדין, \u0003יד עניים אנן\u0004 \u0005[אנחנו],\u0006 שאנו מייצגים אותם. וכפי ש\u0003אמר רב יהודה אמר שמואל\u0004 בענין יתומים: \u0003יתומים\u0004"],["\u0003אינן צריכין פרוזבול\u0004 שהוא נוסח שטר שתיקן הלל הזקן, שמוסר אדם חובותיו לבית דין כדי שלא תשמטנו השנה השביעית. וטעמו של דבר — כי בית הדין נחשב כאפוטרופוס של היתומים, וכל חובותיהם ממילא מסורים לבית הדין, אף בלא המסירה המיוחדת שעושים על ידי פרוזבול.","\u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר חמא: היתומים אינן צריכין פרוזבול,\u0004 משום ש\u0003רבן גמליאל ובית דינו אביהן של יתומין היו\u0004 וכן בית דין שבכל דור, וכאילו קיבל בית דין חשוב זה לגבות את כל חובותיהם.","אגב מעשה זה בקנס על הסוטר לחבירו, מסופר: אדם אחד שהיה קרוי \u0003חנן בישא\u0004 \u0005[הרע]\u0006 \u0003תקע ליה לההוא גברא\u0004 \u0005[סטר לו לאיש אחד],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב הונא\u0004 לדון, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003זיל הב ליה פלגא דזוזא\u0004 \u0005[לך תן לו חצי זוז]\u0006 כפי שאמרנו שהוא סכום הקנס לעבירה זו. \u0003הוה ליה זוזא מכא\u0004 \u0005[היה לו\u0006 לחנן \u0005זוז פחות]\u0006 שנפחתה צורתו, \u0003בעי למיתבה ליה מיניה פלגא דזוזא\u0004 \u0005[רצה לתת לו ממנו חצי זוז],\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 איש שרצה \u0003משתקיל ליה\u0004 \u0005[לקחת לו]\u0006 את הזוז הזה ולפרטו, \u0003תקע ליה אחרינא\u0004 \u0005[סטר לו\u0006 חנן בישא סטירה \u0005אחרת]\u0006 שאף עליה הקנס הוא חצי זוז, \u0003ויהביה נהליה\u0004 \u0005[ונתן לו אותו]\u0006 את הזוז כולו.","\u0003שור שהוא מועד למינו,\u0004 שנגח שלוש פעמים שוורים והרי הוא מועד להם, \u0003ואינו מועד לשאינו מינו,\u0004 וכן השור ה\u0003מועד לאדם ואינו מועד לבהמה,\u0004 או זה ש\u0003מועד ל\u0004בעלי חיים \u0003קטנים ואינו מועד לגדולים,\u0004 בכל אלה אם נגח \u0003את\u0004 \u0003שהוא מועד לו\u0004 — \u0003משלם\u0004 עליו \u0003נזק שלם,\u0004 \u0003ו\u0004אם נגח \u0003את שאינו מועד לו\u0004 — \u0003משלם חצי נזק.\u0004","\u0003אמרו לפני ר' יהודה:\u0004 ומה הדין אם \u0003הרי זה\u0004 השור \u0003מועד לשבתות ואינו מועד ל\u0004ימות ה\u0003חול? אמר להם: ל\u0004נגיחות ב\u0003שבתות\u0004 — \u0003משלם נזק שלם,\u0004 ו\u0003לימות החול\u0004 — \u0003משלם חצי נזק.\u0004","\u0003אימתי הוא תם\u0004 לאחר שנעשה מועד לשבתות — \u0003משיחזור בו\u0004 ולא יגח \u0003שלשה ימי שבתות\u0004 הרי הוא נעשה שוב תם לשבתות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפירוש המשנה, \u0003רב זביד אמר: \"ואינו מועד\u0004 לשאינו מינו \u0003\"\u0004\u0003תנן\u0004 \u0005[שנינו],\u0006 שמדובר בשור שאנו יודעים בו שאינו מועד למין אחר, ועליו אומרת המשנה שאם נגח את שאינו מינו משלם חצי נזק. \u0003רב פפא אמר: \"אינו מועד\" תנן\u0004 \u0005[שנינו],\u0006 לומר שאף שמועד הוא למין אחד אין אומרים שהוא מועד למין אחר עד שייודע הדבר.","ומסבירים: \u0003רב זביד אמר: \"ואינו מועד\" תנן\u0004 \u0005[שנינו],\u0006 כלומר, שצריך שיהא מוכח שאינו מועד למין אחר, \u0003הא סתמא\u0004 \u0005[הרי מן הסתם],\u0006 כאשר אין מוכח להיפך — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מועד\u0004 לכל. ואילו \u0003רב פפא אמר: \"אינו מועד\" תנן\u0004 \u0005[שנינו],\u0006 כלומר, \u0003דסתמא\u0004 \u0005[שמן הסתם]\u0006 \u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003מועד\u0004 למין אחר עד שיוכח שהוא מזיק אותו.","ומסבירים עוד: \u0003רב זביד דייק\u0004 והוציא את סברתו \u0003מסיפא\u0004 \u0005[מסופה]\u0006 של משנתנו, \u0003רב פפא דייק מרישא\u0004 \u0005[מראשה].\u0006","ומפרשים: \u0003רב זביד דייק מסיפא\u0004 \u0005[מסופה],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה: \u0003מועד לקטנים ואינו מועד לגדולים.\u0004 וכך הוא מוכיח: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003\"ואינו מועד\" קתני\u0004 \u0005[שנה\u0006 במשנה\u0005],\u0006 כלומר, \u0003הא סתמיה הוי\u0004 \u0005[הרי סתמו,\u0006 מן הסתם, \u0005הריהו]\u0006 \u0003מועד,\u0004 אם כן \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו מקטנים לגדולים\u0004 שיש פחות חשש שיבוא לנגחם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מסתמא הוי\u0004 \u0005[מן הסתם הריהו]\u0006 \u0003מועד\u0004 ואין אומרים שיש הבדל ביניהם.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003\"אינו מועד\" קתני\u0004 \u0005[שנה],\u0006 כלומר, \u0003סתמא לא הוי\u0004 \u0005[מן הסתם אין הוא\u0006 נעשה\u0005]\u0006 \u0003מועד\u0004 לשאינו מינו, אם כן,","\u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003יש לומר\u0004 שאם \u0003מקטנים לקטנים דעלמא\u0004 \u0005[בכלל]\u0006 \u0003סתמא לא הוי\u0004 \u0005[מן הסתם אין הוא\u0006 נעשה\u0005]\u0006 \u0003מועד,\u0004 אם כן \u0003מקטנים לגדולים\u0004 ואף מאותו מין \u0003צריכא למימר\u0004 \u0005[צריך לומר]\u0006 \u0003דלא הוי מועד\u0004 \u0005[שאינו מועד]\u0006? אלא ודאי יש לשנות \"ואינו מועד\", כלומר, דווקא אם ברור לנו שאינו מועד למין אחר משלם רק חצי נזק. \u0003ורב\u0004","\u0003פפא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כמענה לכך: גם אם נפרש \"אינו מועד\" \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, כי \u0003סלקא דעתיך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ופרץ ביה בההוא מינא\u0004 \u0005[נעשה פרוץ במין זה]\u0006 שהוא נוגח אותם — \u0003פרץ ביה\u0004 \u0005[בו]\u0006 בכל המין כולו, \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003גדולים דידיה\u0004 \u0005[שלו,\u0006 של מין זה\u0005]\u0006 \u0003ולא שנא\u0004 \u0005[שונה]\u0006 \u0003קטנים דידיה\u0004 \u0005[שלו]\u0006 שהוא נוגח את כולם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003מועד\u0004 לגדולים. עד כאן דנה הגמרא בהוכחתו של רב זביד מן המשנה.","ואילו \u0003רב פפא דייק מרישא\u0004 \u0005[מראשה]\u0006 של משנתנו, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בה: \u0003מועד לאדם אינו מועד לבהמה.\u0004 וכך הוא מוכיח: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003\"אינו מועד\" תנן\u0004 \u0005[שנינו],\u0006 כלומר, \u0003סתמא\u0004 \u0005[בסתם]\u0006 \u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003מועד,\u0004 אם כן \u0003הא קא משמע לן\u0004 \u0005[\u0006חידוש \u0005זה השמיע לנו]\u0006 ש\u0003אפילו מאדם לבהמה נמי\u0004 \u0005[גם כן]\u0006 למרות שמצוי שיפגע השור בבהמה יותר מבאדם, בכל זאת \u0003סתמא לא הוי\u0004 \u0005[בסתם אין הוא]\u0006 \u0003מועד.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003\"ואינו מועד\" קתני\u0004 \u0005[שנה],\u0006 כלומר, \u0003הא סתמא הוי\u0004 \u0005[הרי\u0006 ב\u0005סתם הריהו]\u0006 \u0003מועד,\u0004 מה חידוש אם כן יש בדבר? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר: מבהמה לבהמה סתמא הוי\u0004 \u0005[בסתם הריהו]\u0006 \u0003מועד, מאדם לבהמה צריכא למימר דהוי\u0004 \u0005[צריך לומר שהוא]\u0006 \u0003מועד?!\u0004","\u0003ורב זביד אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כמענה לכך: \u0003רישא\u0004 \u0005[ראשה]\u0006 של המשנה \u0003אחזרה\u0004 \u0005[על\u0006 דין \u0005חזרה]\u0006 ממועד \u0003קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005],\u0006 \u0003כגון דהוה\u0004 \u0005[שהיה]\u0006 אותו שור \u0003מועד לאדם ומועד לבהמה, והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003מ\u0004לנגוח \u0003בהמה,\u0004 כיצד? — \u0003דקאי גבי\u0004 \u0005[שעמד אצל]\u0006 \u0003בהמה תלתא זימני\u0004 \u0005[שלוש פעמים]\u0006 \u0003ולא נגח,\u0004 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 ש\u0003לא הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003מ\u0004נגיחת \u0003אדם\u0004 — \u0003חזרה\u0004 של \u0003בהמה\u0004 שאינו נוגח אותה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חזרה היא,\u0004 כל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003חזרה\u0004 של \u0003בהמה מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003חזרה היא,\u0004 ואינו מועד עוד לבהמה.","על שיטת רב זביד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא שנשנית על האמור במשנתנו, \u0003סומכוס אומר: מועד ל\u0004נגוח \u0003אדם\u0004 הרי הוא \u0003מועד לבהמה, מקל וחומר\u0004 זה: \u0003ומה לאדם מועד\u0004 אותו השור — \u0003לבהמה לא כל שכן\u0004 שיהא מועד? ו\u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של משנתנו \u0003\"אינו מועד\" קאמר\u0004 \u0005[אומר],\u0006 כדברי רב פפא!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב זביד\u0004 כתשובה על כך: לדרך שבה פירשתי את המשנה יש לפרש כי \u0003סומכוס אחזרה קאי\u0004 \u0005[על\u0006 ענין \u0005חזרה עומד,\u0006 מתייחס\u0005]\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אומר לו]\u0006 \u0003לתנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003דקאמרת\u0004 \u0005[\u0006מה \u0005שאומר אתה]\u0006 \u0003חזרה\u0004 מ\u0003בהמה חזרה היא\u0004 אף שעדיין לא חזרה מאדם — אני סבור כי \u0003חזרה\u0004 של \u0003בהמה לאו\u0004 \u0005[לא]\u0006 \u0003חזרה היא, מקל וחומר מאדם: ומה מאדם לא קא מהדר ביה\u0004 \u0005[אינו חוזר בו],\u0006 \u0003מבהמה לא כל שכן?\u0004","\u0003אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו, \u0003אמרו לפני ר' יהודה: הרי זה מועד לשבתות ואינו מועד לימות החול. אמר להן: לשבתות\u0004 — \u0003משלם נזק שלם, לימות החול\u0004 — \u0003משלם חצי נזק.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003\"ואינו מועד\" קתני\u0004 \u0005[שנה],\u0006 \u0003שיולי\u0004 \u0005[לשאול]\u0006 \u0003הוא דקא משיילי [ליה]\u0004 \u0005[ששואלים אותו]\u0006 בהלכה זו, מה הדין בשור שאינו מועד לימות החול, \u0003והוא נמי קמהדר להו\u0004 \u0005[גם כן משיב להם]\u0006 מה הדין. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003\"אינו מועד\" קתני\u0004 \u0005[שנה],\u0006 וכי \u0003אגמורי הוא דקא מגמרי ליה\u0004 \u0005[מלמדים הם אותו]\u0006 הלכה? שהרי לפי דרך זו הם האומרים לו ששור המועד לשבתות אינו מועד לימים אחרים. \u0003ותו, איהו מאי קא מהדר להו\u0004 \u0005[ועוד, הוא מה משיב להם]?\u0006 הרי כבר הם עצמם אמרו שאינו מועד לימות החול!","\u0003אמר רב ינאי: מרישא נמי דיקא\u0004 \u0005[מראשה\u0006 של המשנה \u0005גם כן מדוייק]\u0006 שיש לפרש כך, \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003את שמועד לו\u0004 — \u0003משלם נזק שלם, ואת שאינו מועד לו\u0004 — \u0003משלם חצי נזק.\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003\"ואינו מועד\" קתני\u0004 \u0005[שנה],\u0006 אם כן — \u0003פרושי קא מפרש לה\u0004 \u0005[מפרש הוא אותה\u0006 הלכה שאמר קודם\u0005],\u0006 שבמקרה שלא הועד אלא למין אחד, רק עליו משלם נזק שלם.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003\"אינו מועד\" קתני\u0004 \u0005[שנה]\u0006 הרי \u0003פסקה\u0004 \u0005[פסק אותה]\u0006 קבע פה הלכה פסוקה, שלמינים אחרים אינו מועד, ואם כן \u0003מאי תו\u0004 \u0005[מה עוד]\u0006 היה צריך לפרש: \u0003את שמועד לו\u0004 — \u0003משלם נזק שלם, ואת שאינו מועד לו\u0004 — \u0003משלם חצי נזק?\u0004 וכי \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לא אשמעינן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003התם משלם חצי נזק ומועד משלם נזק שלם?\u0004","ומעירים: \u0003ואי תימצי לומר נמי איתא\u0004 \u0005[ואם תמצא לומר גם כן\u0006 ש\u0005יש\u0006 מקום\u0005]\u0006 \u0003ל\u0004שיטת \u0003רב פפא\u0004 ומועד למין אחד אינו מועד למין אחר, מכל מקום אף לשיטתו אם \u0003נגח שור חמור וגמל\u0004 הרי זה \u0003נעשה מועד לכל\u0004 ואין צורך שיגח כל אחד ממינים אלה שלוש פעמים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ראה שור\u0004 — ו\u0003נגח\u0004 אותו, ואחרי כן ראה \u0003שור\u0004 אחר — \u0003ולא נגח\u0004 אותו, ושוב ראה \u0003שור\u0004 — \u0003נגח, שור\u0004 — \u0003לא נגח, שור\u0004 — \u0003נגח, שור\u0004 — \u0003לא נגח\u0004 — \u0003נעשה מועד לסירוגין לשוורים.\u0004 שהוא מועד לנגוח כל שור שני אותו הוא רואה, ולגבי השוורים שבאמצע הרי הוא לפי שעה תם, ואינו משלם אלא חצי נזק.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003ראה שור\u0004 — ו\u0003נגח\u0004 אותו, \u0003חמור\u0004 — \u0003לא נגח, סוס\u0004 — \u0003נגח, גמל\u0004 — \u0003לא נגח, פרד\u0004 — \u0003נגח, ערוד\u0004 — \u0003לא נגח\u0004 — \u0003נעשה מועד לסירוגין\u0004 בכל פעם שניה שהוא רואה בעל חיים, \u0003לכל,\u0004 לכל מיני בעלי חיים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003נגח\u0004"],["\u0003שור שור ושור, חמור וגמל, מהו\u0004 דינו, למה יהא מועד?","האם נאמר \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003שור בתרא\u0004 \u0005[\u0006ה\u0005אחרון]\u0006 שנגח בפעם השלישית — \u0003בתר\u0004 \u0005[אחר]\u0006 שני ה\u0003שוורים\u0004 הראשונים שנגח \u0003שדינן ליה\u0004 \u0005[אנו מטילים,\u0006 מייחסים \u0005אותו]\u0006 ונאמר שנגח שלושה שוורים בזה אחר זה, \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 רק \u0003לשוורים הוא דאייעד\u0004 \u0005[שנעשה מועד],\u0006 ואילו \u0003למידי אחרינא\u0004 \u0005[לדבר אחר]\u0006 שאינו שוורים \u0003לא אייעד\u0004 \u0005[נעשה מועד],\u0006 שהרי נגח רק שנים — חמור וגמל. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003שור בתרא\u0004 \u0005[האחרון]\u0006 — \u0003בתר\u0004 \u0005[אחר]\u0006 נגיחת ה\u0003חמור וגמל שדינן ליה\u0004 \u0005[אנו מטילים אותו],\u0006 שאומרים שנגח שור חמור וגמל, \u0003ואייעד ליה לכולהו מיני\u0004 \u0005[ונעשה\u0006 בכך \u0005מועד לכל המינים]?\u0006","וכיוצא בזה עוד שאלה: נגח \u0003חמור וגמל, שור, שור ושור מהו\u0004 דינו? האם \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003שור קמא\u0004 \u0005[הראשון]\u0006 שנגח לפני השוורים האחרים, \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003חמור וגמל שדינן ליה\u0004 \u0005[מטילים אנו אותו],\u0006 \u0003ואייעד ליה לכולהו מיני\u0004 \u0005[ונעשה מועד לכל המינים],\u0006 \u0003או דילמא בתר\u0004 \u0005[שמא אחר]\u0006 שני ה\u0003שוורים\u0004 שנגח אחרי כן \u0003שדינן ליה\u0004 \u0005[מטילים אנו אותו],\u0006 \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003לשוורים הוא דאייעד\u0004 \u0005[שהועד],\u0006 ואילו \u0003למינא אחרינא\u0004 \u0005[למין אחר]\u0006 \u0003לא אייעד\u0004 \u0005[הועד]?\u0006","ועוד שאלה דומה: נגח \u0003שבת שבת ושבת, אחד בשבת ושני בשבת מהו? הא\u0004 \u0005[זו]\u0006 ה\u0003שבת בתרייתא\u0004 \u0005[\u0006ה\u0005אחרונה]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003שבת הוא דשדינן ליה\u0004 \u0005[שאנו מטילים אותו],\u0006 \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003לשבת הוא דאייעד\u0004 \u0005[שנעשה מועד],\u0006 \u0003לימות החול לא אייעד\u0004 \u0005[נעשה מועד].\u0006 \u0003או דילמא בתר\u0004 \u0005[שמא אחר]\u0006 \u0003אחד בשבת ושני בשבת שדינן ליה\u0004 \u0005[מטילים אנו אותו],\u0006 \u0003ואייעד ליה לכולי יומא\u0004 \u0005[ונעשה מועד לכל הימים]?\u0006","וכן אם נגח \u0003חמישי בשבת וערב שבת ושבת,\u0004 ו\u0003שבת\u0004 הבאה, \u0003ו\u0004עוד \u0003שבת, מהו? הא\u0004 \u0005[זו]\u0006 ה\u0003שבת קמייתא\u0004 \u0005[\u0006ה\u0005ראשונה]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003חמישי בשבת וערב שבת\u0004 \u0003שדינן ליה\u0004 \u0005[מטילים אנו אותו]\u0006 \u0003ואייעד לכולהו יומי\u0004 \u0005[ונעשה מועד לכל הימים],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003שבת קמייתא\u0004 \u0005[\u0006ה\u0005ראשונה]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003שבתות הוא דשדינן ליה\u0004 \u0005[שאנו מטילים אותה],\u0006 \u0003ולשבתות\u0004 בלבד \u0003הוא דאייעד\u0004 \u0005[שנעשה מועד]?\u0006","לכל אחת מן השאלות הללו לא נמצא פתרון, ו\u0003תיקו\u0004 \u0005[\u0006ו\u0005תעמודנה]\u0006 השאלות במקומן.","ושאלה אחרת בנושא דומה \u0003נגח שור\u0004 ב\u0003יום חמשה עשר בחודש זה, ו\u0004אחר כך נגח ב\u0003יום ששה עשר בחודש זה\u0004 הבא אחריו, \u0003ויום שבעה עשר בחודש זה\u0004 שלאחריו. שנגח לא באותו יום בחודש, חודש אחר חודש, אלא בהבדלי ימים, הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003רב ושמואל\u0004 בענין אחר, המקביל לכך.","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בענין אשה ש\u0003ראתה\u0004 דם נידה ב\u0003יום חמשה עשר בחדש זה, ויום ששה עשר בחדש זה,\u0004 הבא, \u0003ויום שבעה עשר בחדש זה\u0004 לאחריו. \u0003רב אמר: קבעה לה וסת,\u0004 שעל ידי ראיות אלה קבעה לה זמן קבוע לנידתה בכל חודש ויום אחד, \u0003ושמואל אמר: עד שתשלש בדילוג,\u0004 כלומר, לא התאריך הוא הגורם לקביעות, אלא תוספת היום היא שיוצרת אותה, ולכן רק אם תדלג שלוש פעמים רצופות, דהיינו בפעם הרביעית — הרי זו קביעות.","ועוד בענין העדאה, \u0003אמר רבא: שמע\u0004 השור \u0003קול שופר ונגח,\u0004 שמע \u0003קול שופר ונגח,\u0004 ושמע שוב \u0003קול שופר ונגח\u0004 — \u0003נעשה מועד לשופרות.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הך\u0004 \u0005[\u0006בקול \u0005זה]\u0006 של ה\u0003שופר קמא\u0004 \u0005[הראשון]\u0006 \u0003סיוטא בעלמא\u0004 \u0005[פחד בלבד]\u0006 \u0003הוא דנקטיה\u0004 \u0005[שאחזו]\u0006 ומשום כך נגח, ונגיחה זו אינה נחשבת לעשותו מועד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שחוזר ונוגח בשמיעת קול השופר, רואים שדבר זה גורם לו לנגוח.","\u0003שור של ישראל שנגח שור של הקדש, ו\u0004כן \u0003שור של הקדש שנגח שור של הדיוט,\u0004 כלומר, של איש פרטי — \u0003פטור\u0004 מתשלומי השור הנוגח, \u0003שנאמר: \"\u0004וכי יגוף שור איש את \u0003שור רעהו\"\u0004 (שמות כא, לה), ומהלשון \"שור רעהו\" מובן — \u0003ולא שור של הקדש,\u0004 בין אם היה זה השור הנוגח או הננגח.","\u0003שור של ישראל שנגח לשור של גוי\u0004 — \u0003פטור, ו\u0004אילו שור \u0003של גוי שנגח לשור של ישראל, בין\u0004 שהיה השור הנוגח \u0003תם\u0004 ו\u0003בין\u0004 שהיה \u0003מועד\u0004 — \u0003משלם נזק שלם.\u0004","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' שמעון בן מנסיא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שור של הדיוט שנגח שור של הקדש, ו\u0004כן \u0003של הקדש שנגח שור של הדיוט\u0004 — \u0003פטור, שנאמר \"שור רעהו\"\u0004 — \u0003ולא שור של הקדש. ר' שמעון בן מנסיא אומר: שור של הקדש שנגח שור של הדיוט\u0004 — אכן \u0003פטור, ו\u0004אולם שור \u0003של הדיוט שנגח שור של הקדש, בין\u0004 שהיה \u0003תם בין\u0004 שהיה \u0003מועד\u0004 — \u0003משלם נזק שלם.\u0004 ובאים לברר את השיטות.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מאי קא סבר\u0004 \u0005[מה סבור]\u0006 \u0003ר' שמעון\u0004 בן מנסיא שמבחין בין שור הקדש שנגח שפטור, לנוגח את שור הקדש שחייב? \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"רעהו\"\u0004 שכתוב בפסוק \u0003דוקא\u0004 \u0005[מדוייק]\u0006 — אם כן \u0003אפילו של הדיוט שנגח של הקדש ליפטר\u0004 \u0005[יהא פטור],\u0006 שהרי אינו \"שור רעהו\", \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003\"רעהו\" לאו דוקא\u0004 \u0005[אינו מדוייק]\u0006 וכל שור בכלל זה, \u0003אפילו\u0004 שור של \u0003הקדש נמי\u0004 \u0005[גם כן]\u0006 \u0003כי נגח דהדיוט ליחייב\u0004 \u0005[כאשר נוגח של הדיוט שיתחייב]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לעולם קסבר\u0004 \u0005[סבור]\u0006 ר' שמעון בן מנסיא כי \u0003\"רעהו\" דוקא\u0004 \u0005[מדוייק],\u0006 ולכן שור של הקדש שנגח שור של הדיוט — פטור. \u0003ומיהו\u0004 \u0005[ומכל מקום]\u0006 שור של \u0003הדיוט כי נגח\u0004 \u0005[כאשר נוגח]\u0006 שור של \u0003הקדש היינו טעמא דמיחייב\u0004 \u0005[זה הטעם שמתחייב]\u0006 — \u0003משום דקא מייתי ליה\u0004 \u0005[שהוא מביאו\u0006 לומד את הדבר\u0005]\u0006 \u0003מקל וחומר\u0004 של \u0003הדיוט,\u0004 וכך הוא לומד: \u0003ומה\u0004 שור של \u0003הדיוט שנגח\u0004 שור \u0003של הדיוט\u0004 הריהו \u0003חייב, כי נגח\u0004 \u0005[כאשר נוגח]\u0006 של \u0003הקדש לא כל שכן דמיחייב\u0004 \u0005[שיתחייב]?\u0006 וכיון שהתחייב להקדש — משלם הוא נזק שלם בכל אופן שהזיק, בין הוא תם בין מועד.","ואולם אם בקל וחומר הוא לומד, הלא במקרה זה קיים הכלל של \u0003דיו לבא מן הדין להיות כנדון\u0004 שאין למדים להחמיר בדבר הנלמד יותר מן המלמד עצמו, ולפיכך נאמר: \u0003מה להלן\u0004 בהדיוט \u0003תם\u0004 משלם \u0003חצי נזק\u0004 בלבד \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 שור תם הנוגח שור של הקדש ישלם \u0003חצי נזק\u0004 ולא יותר!","\u0003אלא אמר ריש לקיש,\u0004 זה הטעם של ר' שמעון בן מנסיא: \u0003הכל,\u0004 כל המזיקים בעצם \u0003היו בכלל נזק שלם,\u0004 שמעיקרו של דבר כל מי שמזיק או גורם נזק צריך לשלם תשלום מלא עבורו, ו\u0003כשפרט לך הכתוב: \"רעהו\" גבי\u0004 \u0005[אצל]\u0006 שור \u0003תם,\u0004 הרי הוא בא להוציא מן הכלל, ויש לדייק בו: דווקא במקרה שנגח את שור \u0003רעהו הוא\u0004 ש\u0003תם משלם חצי נזק, מכלל\u0004 הדברים נשמע שאם נגח שורו שור של \u0003הקדש, בין תם בין מועד\u0004 — \u0003משלם נזק שלם\u0004."]]};
